int minOps(vector<int> &arr, int k) {

    int ans = INT_MAX;

    for (int target : arr) {

        int operations = 0;
        bool valid = true;

        for (int x : arr) {

            if (x > target || (target - x) % k != 0) {
                valid = false;
                break;
            }

            operations += (target - x) / k;
        }

        if (valid) {
            ans = min(ans, operations);
        }
    }

    return ans == INT_MAX ? -1 : ans;
}

