#include <vector>
#include <algorithm>
#include <iostream>

using namespace std;

// function to calculate the minimum cost (Brute Force Approach)
int cost(vector<int>& arr)
{
    // Base case: if array size is 1 or less, no operations needed
    if (arr.size() <= 1) {
        return 0;
    }

    int n = arr.size();
    int minTotalCost = 1e9;

    // Try all possible pairs (i, j)
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

            // Cost of operation is the smaller of the two elements
            int opCost = min(arr[i], arr[j]);

            // Remove the larger element
            int removeIdx = (arr[i] >= arr[j]) ? i : j;

            // Create the new array for the next step
            vector<int> next_a;
            for (int k = 0; k < n; k++) {
                if (k != removeIdx) {
                    next_a.push_back(arr[k]);
                }
            }

            // Recurse and find total cost for this choice
            int totalCost = opCost + cost(next_a);
            minTotalCost = min(minTotalCost, totalCost);
        }
    }

    return minTotalCost;
}

int main()
{
    vector<int> arr = { 4, 3, 2 };
    cout << cost(arr) << endl;
    return 0;
}

