            // Assign even indexes (1-based) with maximum elements
            if ((i + 1) % 2 == 0) {
                result[i] = arr[ptr2--];
            }
            // Assign odd indexes (1-based) with remaining elements
            else {
                result[i] = arr[ptr1++];
            }
        }

        return result;
    }

