using namespace std;

vector<int> findTwoElement(vector<int>& arr) {
    long long n = arr.size();

    // Sum of first n natural numbers
    long long s = (n * (n + 1)) / 2;
    // Sum of squares of first n natural numbers
    long long ssq = (n * (n + 1) * (2 * n + 1)) / 6;

    // Subtract actual values from expected sums
    for (int i = 0; i < n; i++) {
        s -= arr[i];
        ssq -= 1LL * arr[i] * arr[i];
    }

    // Using the equations: missing - repeating = s
    // missing^2 - repeating^2 = ssq
    long long missing = (s + ssq / s) / 2;
    long long repeating = missing - s;

    return {(int)repeating, (int)missing};
}

int main() {
    vector<int> arr = {3, 1, 3};
    vector<int> ans = findTwoElement(arr);

    cout << ans[0] << " " << ans[1] << endl;
    return 0;
}

