class GfG {
    static ArrayList<Integer> findTwoElement(int[] arr) {
        long n = arr.length;

        // Expected sum and sum of squares for numbers from 1 to n
        long s = (n * (n + 1)) / 2;
        long ssq = (n * (n + 1) * (2 * n + 1)) / 6;

        long missing = 0, repeating = 0;

        // Subtract actual values from expected sums
        for (int i = 0; i < n; i++) {
            s -= arr[i];
            ssq -= (long) arr[i] * arr[i];
        }

        // Let x = missing, y = repeating
        // s = x - y
        // ssq = x^2 - y^2 = (x - y)(x + y) = s * (x + y)
        // => x + y = ssq / s
        // => x = (s + ssq / s) / 2
        // => y = x - s
        missing = (s + ssq / s) / 2;
        repeating = missing - s;

        ArrayList<Integer> res = new ArrayList<>();
        res.add((int) repeating);
        res.add((int) missing);
        return res;
    }

