        // by comparing rightmost set bit
        for (int i = 0; i < n; i++) {

            // decide whether arr[i] is in first set
            // or second
            if ((arr[i] & setBitIndex) != 0) {
                x ^= arr[i];
            }
            else {
                y ^= arr[i];
            }

            // decide whether (i+1) is in first set
            // or second
            if (((i + 1) & setBitIndex) != 0) {
                x ^= (i + 1);
            }
            else {
