                int sum1 = findSum(arr, 0, i);
                int sum2 = findSum(arr, i + 1, j);
                int sum3 = findSum(arr, j + 1, n - 1);

                // If all three segments have equal sum,
                // then return true
                if (sum1 == sum2 && sum2 == sum3)
                    return new int[] { i, j };
            }
        }

        // No possible index pair found
        return new int[] { -1, -1 };
    }

