int maxCircularSum(vector<int> &arr) {
    int n = arr.size();
    int res = arr[0];

    // Subarray that starts with index i
    for(int i = 0; i < n; i++) {
        int currSum = 0;

        // Considering all possible endpoints of the
        // Subarray that begins with index i
        for(int j = 0; j < n; j++) {

            // Circular index
            int idx = (i + j) % n;
            currSum = currSum + arr[idx];
            res = max(res, currSum);
        }
    }

    return res;
}

