vector<int> constructArr(vector<int>& arr) {

    if(arr.size() == 1)
        return {1, arr[0]-1} ;

    // size of the result array
    int n = (1 + sqrt(1 + 8 * arr.size())) / 2;

    // find the result array
    vector<int> res(n);
    res[0] = (arr[0] + arr[1] - arr[n - 1]) / 2;
    for (int i = 1; i < n; i++)
        res[i] = arr[i - 1] - res[0];

    return res;
}

int main() {
    vector<int> arr = {4, 5, 3};
    vector<int> res = constructArr(arr);
    for (int x : res)
        cout << x << " ";
    return 0;
}

