    const n = Math.floor((1 + Math.sqrt(1 + 8 * arr.length)) / 2);

    // reconstruct the original array
    const res = new Array(n);
    res[0] = (arr[0] + arr[1] - arr[n - 1]) / 2;
    for (let i = 1; i < n; i++) {
        res[i] = arr[i - 1] - res[0];
    }

    return res;
}

