// Function to find k numbers with most occurrences
function topKFreq(arr, k) {

    // Count frequency of each element
    const mp = new Map();
    for (const val of arr)
        mp.set(val, (mp.get(val) || 0) + 1);

    // Min-heap of [frequency, element] to keep the top k
    const heap = [];

    // Compare by frequency first, then by element
    const less = (a, b) => {
        if (a[0] !== b[0])
            return a[0] < b[0];
        return a[1] < b[1];
    };

    // Push an entry and move it up until the heap order is restored
    const push = (x) => {
        heap.push(x);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (!less(heap[i], heap[p]))
                break;
            [heap[i], heap[p]] = [heap[p], heap[i]];
            i = p;
        }
    };

    // Remove the smallest entry and move the last one down
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            heap[0] = last;
            let i = 0;
            while (true) {
                const l = 2 * i + 1;
                const r = 2 * i + 2;
                let s = i;
                if (l < heap.length && less(heap[l], heap[s])) s = l;
                if (r < heap.length && less(heap[r], heap[s])) s = r;
                if (s === i)
                    break;
                [heap[i], heap[s]] = [heap[s], heap[i]];
                i = s;
            }
        }
        return top;
    };

    for (const [element, freq] of mp) {

        // Push the current element and its frequency
        push([freq, element]);

        // If heap size exceeds k, remove the smallest entry
        if (heap.length > k)
            pop();
    }

    const res = new Array(k);

    // Fill the result from the back, as the heap pops lowest priority first
    for (let i = k - 1; i >= 0; i--)
        res[i] = pop()[1];

    return res;
}

