using System;
using System.Collections.Generic;

class GFG {

    static Random rand = new Random();

    // Swap two elements of the list
    static void swap(List<int> a, int i, int j) {
        int t = a[i];
        a[i] = a[j];
        a[j] = t;
    }

    // Partition distinct[left..right] around the pivot by (frequency, value)
    static int partition(int left, int right, int pivotIdx,
                         List<int> distinct, Dictionary<int, int> mp) {

        // Frequency and value of the pivot element
        int pivotFreq = mp[distinct[pivotIdx]];
        int pivotVal = distinct[pivotIdx];

        // Move the pivot to the end
        swap(distinct, pivotIdx, right);

        int j = left;
        for (int i = left; i < right; i++) {

            // Smaller frequency, or smaller value on same frequency, goes first
            if (mp[distinct[i]] < pivotFreq ||
                (mp[distinct[i]] == pivotFreq && distinct[i] < pivotVal)) {
                swap(distinct, i, j);
                j++;
            }
        }

        // Place the pivot at its final position
        swap(distinct, j, right);
        return j;
    }

    // Move the element of rank k to index k, with larger ones after it
    static void quickselect(int left, int right, int k,
                            List<int> distinct, Dictionary<int, int> mp) {
        if (left >= right)
            return;

        // Pick a random pivot and partition
        int pivotIdx = left + rand.Next(right - left + 1);
        pivotIdx = partition(left, right, pivotIdx, distinct, mp);

        // Recurse only into the side that contains index k
        if (pivotIdx == k)
            return;
        else if (pivotIdx > k)
            quickselect(left, pivotIdx - 1, k, distinct, mp);
        else
            quickselect(pivotIdx + 1, right, k, distinct, mp);
    }

    // Function to find top k frequent elements
    static List<int> topKFreq(int[] arr, int k) {
        Dictionary<int, int> mp = new Dictionary<int, int>();

        // Count frequency of each element
        foreach (int val in arr) {
            if (mp.ContainsKey(val))
                mp[val]++;
            else
                mp[val] = 1;
        }

        // Store the distinct elements
        List<int> distinct = new List<int>(mp.Keys);

        int n = distinct.Count;

        // Move the top k elements to the end
        quickselect(0, n - 1, n - k, distinct, mp);

        // Sort the top k by frequency, then by value, in descending order
        distinct.Sort(n - k, k, Comparer<int>.Create((a, b) => {
            if (mp[a] != mp[b])
                return mp[b].CompareTo(mp[a]);
            return b.CompareTo(a);
        }));

        // Collect the top k elements
        return distinct.GetRange(n - k, k);
    }

    static void Main() {
        int[] arr = { 3, 1, 4, 4, 5, 2, 6, 1 };
        int k = 2;
        List<int> res = topKFreq(arr, k);

        Console.WriteLine("[" + string.Join(", ", res) + "]");
    }
}

