int maxProfit(vector<int>& prices) {
    int n = prices.size();
    int minSoFar = prices[0], res = 0;

    for (int i = 1; i < n; i++) {
        if (prices[i] > minSoFar) {

            // Profit from first transaction + best profit
            // from remaining days
            int curr = prices[i] - minSoFar + maxProfOne(prices, i+1);
            res = max(res, curr);
        }
        else {
            minSoFar = min(minSoFar, prices[i]);
        }
    }
    return res;
}

