    vector<vector<int>> queries = { {0, 4}, {4, 7}, {7, 8} };
    vector<int> res = solveQueries(arr, queries);
    for (int i = 0; i < res.size(); i++) {
        cout << res[i] << " ";
    }
    return 0;
