// Queries:
// {type, x, y}
// type 1 → update index x with value y
// type 2 → query LCM in range [x, y]
let queries = [ [ 2, 0, 2 ], [ 1, 3, 8 ], [ 2, 2, 5 ] ];

let res = RangeLCMQuery(arr, queries);

// Print results
