int minJumps(vector<int>& arr) {
    int n = arr.size();
    vector<int> dp(n, INT_MAX);

    dp[n - 1] = 0;

    for (int i = n - 2; i >= 0; i--) {
        // Try all reachable positions from i
        for (int j = i + 1; j <= i + arr[i] && j < n; j++) {
            if (dp[j] != INT_MAX)
                dp[i] = min(dp[i], 1 + dp[j]);
        }
    }

    return (dp[0] == INT_MAX) ? -1 : dp[0];
}

