// i*arr[i] with rotations using Optimized Approach
#include <iostream>
#include <vector>
#include <climits>
using namespace std;

// Function to find maximum value of i*arr[i]
// after any number of rotations
int maxRotateSum(vector<int> &arr) {

    int n = arr.size();

    int totalSum = 0;
    int currVal = 0;

    // Compute initial value of i*arr[i]
    // and total sum
    for (int i = 0; i < n; i++) {
        totalSum += arr[i];
        currVal += i * arr[i];
    }

