int getMinDiff(int arr[], int n, int k)
{
    int res = arr[n - 1] - arr[0];

    // Sort the array using qsort
    qsort(arr, n, sizeof(int), compare);

    // For all indices i, increment
    // arr[0...i-1] by k and decrement and arr[i...n-1] by k
