        if (arr[i] - k < 0)
            continue;

        int minH = (arr[0] + k < arr[i] - k) ? arr[0] + k : arr[i] - k;
        int maxH = (arr[i - 1] + k > arr[n - 1] - k) ? arr[i - 1] + k : arr[n - 1] - k;
        res = (res > maxH - minH) ? maxH - minH : res;
    }

    return res;
}

