        for (char ch : a) x += '0' + charToDigit[ch];
        for (char ch : b) y += '0' + charToDigit[ch];
        for (char ch : sum) z += '0' + charToDigit[ch];
        return {x, y, z};
    }
    return {"-1"};
}

