int dfs(int u, int dest, vector<vector<int>>& adj,
        vector<int>& visited) {
    if (u == dest) return 1;
    if (visited[u]!= -1) return visited[u];

    int total = 0;
    for (int v : adj[u]) {
        total += dfs(v, dest, adj, visited);
    }

    return visited[u] = total;
}

