    vector<vector<int>> adj(V);
    for (auto& e : edges) adj[e[0]].push_back(e[1]);

    // visited[u] stores the number of paths from u to dest, once computed
    vector<int> visited(V, -1);

    return dfs(src, dest, adj, visited);
}

