#include <iostream>
#include <vector>
#include <queue>
using namespace std;

int countPaths(int V, vector<vector<int>>& edges,
               int src, int dest) {

    vector<vector<int>> adj(V);
    vector<int> indegree(V, 0);

    for (auto& e : edges) {
        adj[e[0]].push_back(e[1]);
        indegree[e[1]]++;
    }

    queue<int> q;
    vector<int> topo;

    for (int i = 0; i < V; i++) {
        if (indegree[i] == 0)
            q.push(i);
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        topo.push_back(u);

        for (int v : adj[u]) {
            if (--indegree[v] == 0)
                q.push(v);
        }
    }

    vector<int> dp(V, 0);

    dp[dest] = 1;

    for (int i = topo.size() - 1; i >= 0; i--) {
        int u = topo[i];

        for (int v : adj[u])
            dp[u] += dp[v];
    }

    return dp[src];
}

