        int[] arr = { 1, 2, 2 };

        List<List<int>> result = findSubsets(arr);

        foreach (var subset in result) {
            Console.Write("[");
            for (int i = 0; i < subset.Count; i++) {
                Console.Write(subset[i]);
                if (i != subset.Count - 1) Console.Write(", ");
            }
            Console.WriteLine("]");
