        // if current element is same as previous,
        // only extend subsets added in previous step
        if (i > 0 && arr[i] === arr[i - 1]) {
            start = end + 1;
        }
        end = res.length - 1;

        let n = res.length;
        for (let j = start; j < n; j++) {
            let subset = res[j].slice();
            subset.push(arr[i]);
            res.push(subset);
        }
    }

    return res;
}

