        {0, 1, 4},
        {0, 2, 8},
        {1, 4, 6},
        {2, 3, 2},
        {4, 3, 10}
    };
    int k = 8;

    cout << (pathMoreThanK(V, edges, k) ? "true" : "false");

    return 0;
}

