        if (isSafe(row, col, n, mat)
            && path[row][col] == 0) {

            // Mark cell
            path[row][col] = 1;

            // Try moving right first
            for (int jump = 1;
                 jump <= mat[row, col] && jump < n;
                 jump++) {
                if (col + jump < n
                    && findPath(mat, path, row, col + jump,
                                n))
                    return true;
                if (row + jump < n
                    && findPath(mat, path, row + jump, col,
                                n))
                    return true;
            }

            // Backtrack
            path[row][col] = 0;
            return false;
        }
