using System;
using System.Collections.Generic;

class GfG {

    static bool solve(int i, int j, int[,] mat, List<List<int>> ans, int[,] dp) {
        int n = mat.GetLength(0);

        // Out of bounds
        if (i >= n || j >= n)
            return false;

        // Destination
        if (i == n - 1 && j == n - 1) {
            ans[i][j] = 1;
            return true;
        }

        // Blocked cell
        if (mat[i, j] == 0)
            return false;

        // Memoization
        if (dp[i, j] != -1)
            return dp[i, j] == 1;

        ans[i][j] = 1;

        int jump = mat[i, j];

        // Shortest jumps first
        for (int step = 1; step <= jump; step++) {
            // Right first
            if (j + step < n && solve(i, j + step, mat, ans, dp)) {
                dp[i, j] = 1;
                return true;
            }

            // Down
            if (i + step < n && solve(i + step, j, mat, ans, dp)) {
                dp[i, j] = 1;
                return true;
            }
        }

        ans[i][j] = 0;
        dp[i, j] = 0;
        return false;
    }

    static List<List<int>> shortestDist(int[,] mat) {
        int n = mat.GetLength(0);

        List<List<int>> ans = new List<List<int>>();
        for (int i = 0; i < n; i++) {
            List<int> row = new List<int>();
            for (int j = 0; j < n; j++) {
                row.Add(0);
            }
            ans.Add(row);
        }

        // Special case matrix size 1
        if (n == 1) {
            ans[0][0] = 1;
            return ans;
        }

        // Blocked start
        if (mat[0, 0] == 0)
            return new List<List<int>> { new List<int> { -1 } };

        int[,] dp = new int[n, n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                dp[i, j] = -1;
            }
        }

        // Call the helper. If no path is found, return [[-1]]
        if (!solve(0, 0, mat, ans, dp))
            return new List<List<int>> { new List<int> { -1 } };

        return ans;
    }

    static void print2dArray(List<List<int>> arr) {
        foreach (var row in arr) {
            foreach (var cell in row) {
                Console.Write(cell + " ");
            }
            Console.WriteLine();
        }
    }

    static void Main(string[] args) {
        int[,] mat = new int[,] {
            { 2, 1, 0, 0 },
            { 3, 0, 0, 1 },
            { 0, 1, 0, 1 },
            { 0, 0, 0, 1 }
        };

        // Get shortest path matrix
        List<List<int>> result = shortestDist(mat);

        print2dArray(result);
    }
}

