#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
#include <algorithm>
using namespace std;

// builds sentences from s[start..], where path holds the words chosen so far
void backtrack(string& s, int start, unordered_set<string>& st,
               vector<string>& path, vector<string>& res) {

    // the whole string is covered, so the words in path form one sentence
    if (start == s.size()) {
        string sentence = path[0];
        for (int i = 1; i < path.size(); i++)
            sentence += " " + path[i];
        res.push_back(sentence);
        return;
    }

    // try every prefix of the remaining string
    for (int end = start + 1; end <= s.size(); end++) {
        string word = s.substr(start, end - start);

        // continue only if the prefix is a valid dictionary word
        if (st.count(word)) {
            path.push_back(word);
            backtrack(s, end, st, path, res);

            // remove the word to try the next prefix
            path.pop_back();
        }
    }
}

vector<string> wordBreak(vector<string>& dict, string& s) {

    // set of words for fast lookups
    unordered_set<string> st(dict.begin(), dict.end());

    vector<string> res;
    vector<string> path;
    backtrack(s, 0, st, path, res);

    return res;
}

int main() {
    vector<string> dict = {"lik", "like", "egfg", "gfg"};
    string s = "likegfg";

    vector<string> res = wordBreak(dict, s);
    sort(res.begin(), res.end());

    cout << "[";
    for (int i = 0; i < res.size(); i++) {
        if (i > 0)
            cout << ", ";
        cout << "\"" << res[i] << "\"";
    }
    cout << "]" << endl;

    return 0;
}

