import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;

class GFG {

    // builds sentences from s[start..], where path holds the words chosen so far
    static void backtrack(String s, int start, HashSet<String> st,
                          ArrayList<String> path, ArrayList<String> res) {

        // the whole string is covered, so the words in path form one sentence
        if (start == s.length()) {
            res.add(String.join(" ", path));
            return;
        }

        // try every prefix of the remaining string
        for (int end = start + 1; end <= s.length(); end++) {
            String word = s.substring(start, end);

            // continue only if the prefix is a valid dictionary word
            if (st.contains(word)) {
                path.add(word);
                backtrack(s, end, st, path, res);

                // remove the word to try the next prefix
                path.remove(path.size() - 1);
            }
        }
    }

    static ArrayList<String> wordBreak(String[] dict, String s) {

        // set of words for fast lookups
        HashSet<String> st = new HashSet<>(Arrays.asList(dict));

        ArrayList<String> res = new ArrayList<>();
        ArrayList<String> path = new ArrayList<>();
        backtrack(s, 0, st, path, res);

        return res;
    }

    public static void main(String[] args) {
        String[] dict = {"lik", "like", "egfg", "gfg"};
        String s = "likegfg";

        ArrayList<String> res = wordBreak(dict, s);
        Collections.sort(res);

        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < res.size(); i++) {
            if (i > 0)
                sb.append(", ");
            sb.append("\"").append(res.get(i)).append("\"");
        }
        sb.append("]");
        System.out.println(sb);
    }
}

