#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
#include <unordered_map>
#include <algorithm>
using namespace std;

// returns all the sentences that can be formed from s[start..n)
vector<string> wordBreakHelper(string& s, unordered_set<string>& st,
                               unordered_map<int, vector<string>>& memo, int start) {
    int n = s.size();

    // the sentences of this index are already computed, so return them
    if (memo.count(start))
        return memo[start];

    vector<string> result;

    // the end of the string is reached, so add the empty sentence to mark a valid split
    if (start == n) {
        result.push_back("");
        return result;
    }

    // try every substring that starts at index start
    for (int end = start + 1; end <= n; end++) {
        string word = s.substr(start, end - start);

        // continue only if the substring is a valid dictionary word
        if (st.count(word)) {

            // find all the sentences that can be formed from s[end..n)
            vector<string> subSentences = wordBreakHelper(s, st, memo, end);

            // put the word in front of every one of them
            for (string& sub : subSentences) {
                if (sub.empty())
                    result.push_back(word);
                else
                    result.push_back(word + " " + sub);
            }
        }
    }

    // store the sentences of this index, so that they are not computed again
    memo[start] = result;
    return result;
}

vector<string> wordBreak(vector<string>& dict, string& s) {

    // set of words for fast lookups
    unordered_set<string> st(dict.begin(), dict.end());
    unordered_map<int, vector<string>> memo;

    return wordBreakHelper(s, st, memo, 0);
}

