#include <string>
#include <unordered_set>
#include <algorithm>
using namespace std;

// builds sentences from s[start..], where path holds the words chosen so far
void backtrack(string& s, int start, int maxLen, unordered_set<string>& st,
               vector<bool>& canBreak, vector<string>& path, vector<string>& res) {

    // the whole string is covered, so the words in path form one sentence
    if (start == s.size()) {
        string sentence = path[0];
        for (int i = 1; i < path.size(); i++)
            sentence += " " + path[i];
        res.push_back(sentence);
        return;
    }

    // try every prefix of the remaining string, up to the longest word
    for (int end = start + 1; end <= min((int)s.size(), start + maxLen); end++) {

        // move ahead only if the rest of the string can be broken
        if (!canBreak[end])
            continue;

        string word = s.substr(start, end - start);

        // continue only if the prefix is a valid dictionary word
        if (st.count(word)) {
            path.push_back(word);
            backtrack(s, end, maxLen, st, canBreak, path, res);

            // remove the word to try the next prefix
            path.pop_back();
        }
    }
}

