    // canBreak[i] is true if s[i..n) can be split into dictionary words,
    // and an empty suffix is always valid
    vector<bool> canBreak(n + 1, false);
    canBreak[n] = true;

    for (int i = n - 1; i >= 0; i--) {
        for (int end = i + 1; end <= min(n, i + maxLen); end++) {
            if (canBreak[end] && st.count(s.substr(i, end - i))) {
