        if (i < 0 || i >= r || j < 0 || j >= c || mat[i][j] == 0 || visited[i, j])
            return int.MaxValue;

        // If last column reached
        if (j == c - 1)
            return 1;

        visited[i, j] = true;

        int[] rowDir = {-1, 1, 0, 0};
        int[] colDir = {0, 0, -1, 1};

        int minPath = int.MaxValue;

