            // Move right
            if (j + 1 < m)
                findPaths(mat, i, j + 1, path, paths);

            // Move down
            if (i + 1 < n)
                findPaths(mat, i + 1, j, path, paths);
        }

        // Backtrack
        path.remove(path.size() - 1);
    }

    // Function to return all possible paths
