            cur += word.charAt(ind);

            // map the character to the substring
            mp.put(ch, cur);

            // see if it leads to the solution
            if (patternMatchUtil(ind + 1, j + 1, word, pat, mp))
                return true;

            // if not, remove ch from the map
            mp.remove(ch);
        }

