#include <bits/stdc++.h>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node* left;
    Node* right;
    Node(int val) {
        data = val;
        left = right = NULL;
    }
};

// Function to find Inorder Successor
int inOrderSuccessor(Node *root, Node *p) {

    // Edge case: if tree or given node is NULL
    if (root == NULL || p == NULL)
        return -1;

    Node *suc = NULL;

    // Traverse the BST
    while (root != NULL) {

        // If current node's value is <= target node,
        // then successor must be in right subtree
        if (root->data <= p->data)
            root = root->right;

        // If current node's value is greater than target,
        // this node can be a successor
        else {
            suc = root;
            root = root->left;
        }
    }

    // If no successor found
    if (suc == NULL)
        return -1;

    return suc->data;
}
