#include <iostream>
#include <vector>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

vector<int> nodesInRange(Node* root, int low, int high) {
    vector<int> ans;
    Node* curr = root;

    while (curr) {

        // Skip entire left subtree
        if (curr->data < low) {
            curr = curr->right;
            continue;
        }

        // Skip entire right subtree
        if (curr->data > high) {
            curr = curr->left;
            continue;
        }

        // Morris Inorder Traversal
        if (curr->left == nullptr) {
            ans.push_back(curr->data);
            curr = curr->right;
        }
        else {
            Node* pre = curr->left;

