#include <bits/stdc++.h>
using namespace std;

class Node
{
  public:
    int data;
    Node *left, *right;
    Node(int val)
    {
        data = val;
        left = right = nullptr;
    }
};

// Function to insert a key into BST
Node *insertBST(Node *root, int key)
{
    Node *newNode = new Node(key);
    if (root == nullptr)
        return newNode;
    Node *curr = root;
    Node *parent = nullptr;
    while (curr != nullptr)
    {
        parent = curr;
        if (key < curr->data)
            curr = curr->left;
        else
            curr = curr->right;
    }
    if (key < parent->data)
        parent->left = newNode;
    else
        parent->right = newNode;

    return root;
}

// Function to construct BST from preorder traversal
Node *preToBST(vector<int> &pre)
{
    Node *root = nullptr;

    // Insert elements one by one into BST
    for (int x : pre)
    {
        root = insertBST(root, x);
    }

    return root;
}

// Driver Code
int main()
{
    vector<int> pre = {40, 30, 35, 80, 100};

    Node *root = preToBST(pre);

