  Node* node = (Node*)malloc(sizeof(Node));
  node->data = val;
  node->left = NULL;
  node->right = NULL;
  return node;
}

Node* preToBST(int pre[], int n) {
  // Stack to keep track of ancestors
  Node** st = (Node**)malloc(n * sizeof(Node*));
  int top = -1;

  // First element is root
  Node* root = newNode(pre[0]);
  st[++top] = root;

  // Process remaining elements
  for (int i = 1; i < n; i++) {
    Node* temp = NULL;
    // Find correct parent by popping smaller elements
    while (top >= 0 && pre[i] > st[top]->data) {
      temp = st[top--];
    }
    // If popped, attach as right child
    if (temp!= NULL) {
      temp->right = newNode(pre[i]);
      st[++top] = temp->right;
    }
    else {
      // Else attach as left child
      st[top]->left = newNode(pre[i]);
      st[++top] = st[top]->left;
    }
  }
  free(st);
  return root;
}

