// C++ program to Construct BST from
// its given level order traversal
#include <iostream>
#include<vector>
using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;
    Node(int val) {
        data = val;
        left = nullptr;
        right = nullptr;
    }
};

Node* insertIntoBST(Node* root, int val) {

    // If node is null, then we can insert
    // val here.
    if (!root) return new Node(val);

    // If value is less than root value,
    // insert into left subtree.
    if (val < root->data) {
        root->left = insertIntoBST(root->left, val);
    }

    // Else, insert into right subtree.
    else {
        root->right = insertIntoBST(root->right, val);
    }

    return root;
}

Node* constructBst(vector<int> &arr) {
    int n = arr.size();

    Node* root = nullptr;

    // Insert each value one by one
    for (int i = 0; i < n; i++) {
        root = insertIntoBST(root, arr[i]);
    }
    return root;
}

void preOrder(Node* root) {
    if (!root) return;

    cout << root->data << " ";
    preOrder(root->left);
    preOrder(root->right);
}

int main() {
    vector<int> arr = {7, 4, 12, 3, 6, 8, 1, 5, 10};
    Node* root = constructBst(arr);
    preOrder(root);
    return 0;
}

