    vector<int> arr = {18, 36, 9, 6, 12, 10, 1, 8};
    int a = 1, b = 10;
    int n = arr.size();

    Node *root = new Node(arr[0]);

    for (int i = 1; i < n; i++)
        insertNode(root, arr[i]);

    cout << findMaxElement(root, a, b) << endl;

    return 0;
}

