    function upperBound(arr, target) {
        let l = 0, r = arr.length;
        while (l < r) {
            let mid = Math.floor((l + r) / 2);
            if (arr[mid] <= target) l = mid + 1;
            else r = mid;
        }
        return l;
    }

    for (let i = n - 1; i >= 0; i--) {
        let idx = upperBound(sortedset, arr[i]);

        if (idx < sortedset.length)
            res[i] = sortedset[idx];

        sortedset.splice(idx, 0, arr[i]); // insert sorted
