        List<int[]> temp = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            temp.add(new int[]{arr[i], i});
        }

        // we sort the temp according to the first of the pair
        // i.e value
        Collections.sort(temp, (a, b) -> {
            if (a[0] == b[0])
                return b[1] - a[1];
            return a[0] - b[0];
        });

        int[] indexes = nextGreaterIndex(temp);

        int[] res = new int[n];
        Arrays.fill(res, -1);

        for (int i = 0; i < n; i++) {
            if (indexes[temp.get(i)[1]] != -1)
