#include <iostream>
#include <queue>
using namespace std;

// Structure of a binary tree node
class Node {
  public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// Function to check if two nodes are cousins
bool areCousins(Node* root, int a, int b) {

    // Empty tree or same node values cannot be cousins
    if (root == nullptr || a == b)
        return false;

    queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        int sz = q.size();

        // Track whether a and b are present at the current level
        bool aFound = false, bFound = false;

        while (sz--) {
            Node* curr = q.front();
            q.pop();

            if (curr->data == a)
                aFound = true;
            if (curr->data == b)
                bFound = true;

            // If a and b have the same parent, they are siblings
            if (curr->left && curr->right) {
                int left = curr->left->data;
                int right = curr->right->data;

                if ((left == a && right == b) ||
                    (left == b && right == a))
                    return false;
            }

            if (curr->left)
                q.push(curr->left);

            if (curr->right)
                q.push(curr->right);
        }

        // Both nodes found at the same level
        if (aFound && bFound)
            return true;

        // Only one node found at this level
        if (aFound || bFound)
            return false;
    }

    return false;
}

