// C++ program to check foldable binary tree
#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;
    Node (int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Function to convert subtree
// into its mirror
void mirror(Node* root) {
    if (root == nullptr) return;

    // Recursively process the left
    // and right subtrees.
    mirror(root->left);
    mirror(root->right);

    // swap the left and right nodes.
    Node* temp = root->left;
    root->left = root->right;
    root->right = temp;
}

// function to check if two trees have
// same structure
bool isStructSame(Node* a, Node* b) {

    // If both subtrees are null, return
    // true.
    if (a == nullptr && b == nullptr)
        return true;

    // If one of the subtrees is null,
    // return false.
    if (a == nullptr || b == nullptr)
        return false;

    // check left and right subtree.
    return isStructSame(a->left, b->left)
    &&
    isStructSame(a->right, b->right);
}

// Function to check if a tree is foldable.
bool isFoldable(Node* root) {
    if (root == nullptr)
        return true;

    // Convert left subtree into
    // its mirror.
    mirror(root->left);

    // Compare the left subtree
    // and right subtree.
    bool ans = isStructSame(root->left, root->right);

    // Revert the left subtree.
    mirror(root->left);

    return ans;
}

int main() {

    // The constructed binary tree is
    //      1
    //     / \
    //     2 3
    //     \ /
    //     4 5
    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->right = new Node(4);
    root->right->left = new Node(5);

    if (isFoldable(root)) {
        cout << "True" << endl;
    } else {
        cout << "False" << endl;
    }
    return 0;
}

