bool isFoldable(Node* root) {
    if (root == nullptr)
        return true;

    queue<Node*> q;
    q.push(root->left);
    q.push(root->right);

    while (!q.empty()) {
        Node *a = q.front();
        q.pop();
        Node* b = q.front();
        q.pop();

        // If both subtrees are null, continue.
        if (a == nullptr && b == nullptr)
            continue;

        // If one of the subtrees is null,
        // return false.
        if (a==nullptr || b==nullptr)
            return false;

        // Push left node of a and right
        // node of b.
        q.push(a->left);
        q.push(b->right);

        // Push right node of b and left
        // node of a.
        q.push(a->right);
        q.push(b->left);
    }

    return true;
}

