using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node *left, *right;

    Node(int val) {
        data = val;
        left = right = nullptr;
    }
};

bool isSymmetric(Node* root) {
    if (root == nullptr)
        return true;

    stack<Node*> s1, s2;

    // Initialize the stacks with the left
  	// and right subtrees
    s1.push(root->left);
    s2.push(root->right);

    while (!s1.empty() && !s2.empty()) {

        // Get the current pair of nodes
        Node* node1 = s1.top();
        Node* node2 = s2.top();
        s1.pop();
        s2.pop();

        // If both nodes are null, continue to the next pair
        if (node1 == nullptr && node2 == nullptr) {
            continue;
        }

        if (node1 == nullptr || node2 == nullptr
            || node1->data != node2->data) {
            return false;
        }

        // Push children of node1 and node2 in opposite order
        // Push left child of node1 and right child of node2
        s1.push(node1->left);
        s2.push(node2->right);

        // Push right child of node1 and left child of node2
        s1.push(node1->right);
        s2.push(node2->left);
    }

    return s1.empty() && s2.empty();
}

