class Solution:
    def isCompleteBT(self, root):
        if root is None:
            return True

        q = deque([root])
        null_encountered = False

        while q:
            curr = q.popleft()

            if curr is None:
                # A NULL position has been found
                null_encountered = True
            else:
                # Non-NULL node after a NULL position
                if null_encountered:
                    return False

                q.append(curr.left)
                q.append(curr.right)

