#include <bits/stdc++.h>
using namespace std;

/* Structure of Tree Node */
class Node
{
  public:
    int data;
    Node *left;
    Node *right;

    Node(int val)
    {
        data = val;
        left = right = nullptr;
    }
};

vector<int> reverseLevelOrder(Node *root)
{
    vector<int> result;

    // If the tree is empty, return an empty result.
    if (root == nullptr)
        return result;

    queue<Node *> q;

    // Store each level separately.
    vector<vector<int>> levels;

    // Start BFS traversal from the root.
    q.push(root);

    while (!q.empty())
    {
        // Number of nodes present at the current level.
        int size = q.size();

        vector<int> currentLevel;

        // Process all nodes of the current level.
        for (int i = 0; i < size; i++)
        {
            Node *curr = q.front();
            q.pop();

            // Store the current node's value.
            currentLevel.push_back(curr->data);

            // Push the left child first.
            if (curr->left)
                q.push(curr->left);

            // Push the right child.
            if (curr->right)
                q.push(curr->right);
        }

        // Store the current level.
        levels.push_back(currentLevel);
    }

    // Traverse the levels from bottom to top.
    for (int i = levels.size() - 1; i >= 0; i--)
    {
        for (int value : levels[i])
        {
            result.push_back(value);
        }
    }

    return result;
}

int main()
{
    /*
            1
           / \
          2   3
         / \
        4   5
    */

    Node *root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);

    vector<int> result = reverseLevelOrder(root);

    for (int x : result)
        cout << x << " ";

    return 0;
}

