#include <iostream>
using namespace std;

// Node structure
struct Node
{
    int data;
    Node *left;
    Node *right;
    Node *next;

    Node(int val)
    {
        data = val;
        left = right = next = NULL;
    }
};

// Helper function (Reverse Inorder Traversal)
// Right → Root → Left
void populateNextUtil(Node *root, Node *&nextNode)
{
    if (root == NULL)
        return;

    // Step 1: Traverse right subtree first
    populateNextUtil(root->right, nextNode);

    // Step 2: Set next pointer
    root->next = nextNode;

    // Step 3: Update nextNode to current node
    nextNode = root;

    // Step 4: Traverse left subtree
    populateNextUtil(root->left, nextNode);
}

// Main function to populate next pointers
void populateNext(Node *root)
{
    Node *nextNode = NULL;
    populateNextUtil(root, nextNode);
}

// Driver code
int main()
{
    Node *root = new Node(10);

    root->left = new Node(8);
    root->right = new Node(12);
    root->left->left = new Node(3);

    // Populate next pointers
    populateNext(root);

    Node *curr = root;

    while (curr->left)
        curr = curr->left;

    while (curr != NULL)
    {
        cout << curr->data << "->";
        if (curr->next)
            cout << curr->next->data << " ";
        else
            cout << "-1 ";
        curr = curr->next;
    }

    cout << endl;

    return 0;
}

