    // Base Case
    if (root == nullptr)  return;

    // Create an empty queue for
  	// level order traversal
    queue<Node *> q;

    // Enqueue Root and initialize height
    q.push(root);

    while (1) {

        // nodeCount (queue size) indicates number
        // of nodes at current level.
        int nodeCount = q.size();
