{
    // Traversal Arrays
    vector<int> in = {4, 2, 5, 1, 3};
    vector<int> pre = {1, 2, 4, 5, 3};
    vector<int> post = {4, 5, 2, 3, 1};

    cout << (checktree(pre, in, post) ? "true" : "false");

    return 0;
}

