// tree using BFS

#include <bits/stdc++.h>
using namespace std;

int buildTree(vector<int> &parent, int n,
              vector<vector<int>> &adj) {
    int root = -1;

    // Iterate through all nodes to
   //establish connections
    for (int i = 0; i < n; i++) {
        if (parent[i] == -1)
            root = i;
        else {
            adj[i].push_back(parent[i]);
            adj[parent[i]].push_back(i);
        }
    }
    return root;
}

// Function to compute height of the tree
// using BFS
int getTreeHeight(int root,
                  vector<vector<int>> &adj) {

    // Visited map to track nodes
    map<int, bool> visited;

    // Pair stores (node, level)
    queue<pair<int, int>> q;
    int maxHeight = 0;

    // Start BFS from the
  	// root node
    q.push({root, 0});

    while (!q.empty()) {

        auto node = q.front().first;
        auto level = q.front().second;
        q.pop();

        visited[node] = true;
        maxHeight = max(maxHeight, level);

        // Traverse all children of the
      	// current node
        for (int child : adj[node]) {
            if (!visited[child]) {

                // Increment level
                q.push({child, level + 1});
            }
        }
    }

    return maxHeight;
}

