        int root = -1;

        // Iterate through all nodes to establish
        // connections
        for (int i = 0; i < n; i++) {
            if (parent[i] == -1)
                root = i;
            else {
                adj[i].Add(parent[i]);
                adj[parent[i]].Add(i);
            }
        }
        return root;
