vector<int> diagonal(Node* root) {
    vector<int> ans;
    queue<Node*> q;

    if (root == nullptr)
        return ans;

    q.push(root);

    while (!q.empty()) {
        Node* curr = q.front();
        q.pop();

        // Traverse the current diagonal through right children
        while (curr != nullptr) {
            ans.push_back(curr->data);

            // Store left child for the next diagonal
            if (curr->left != nullptr)
                q.push(curr->left);

            curr = curr->right;
        }
    }

    return ans;
