// Node Structure
class Node {
    public int data;
    public Node left;
    public Node right;

    public Node(int x)
    {
        data = x;
        left = right = null;
    }
}

class GFG {
    static bool isLeaf(Node node) {
        return node.left == null && node.right == null;
    }

    // Function to collect the left boundary nodes
    static void collectLeft(Node root, List<int> res) {
        if (root == null)
            return;

        Node curr = root;
        while (!isLeaf(curr))
        {
            res.Add(curr.data);

            if (curr.left != null)
                curr = curr.left;
            else
                curr = curr.right;
        }
    }

    // Function to collect the leaf nodes using Morris Traversal
    static void collectLeaves(Node root, List<int> res)
    {
        Node current = root;

        while (current != null)
        {
            if (current.left == null)
            {
                // If it's a leaf node
                if (current.right == null)
                    res.Add(current.data);

                current = current.right;
            }
            else
            {
                // Find the inorder predecessor
                Node predecessor = current.left;
                while (predecessor.right != null && predecessor.right != current)
                {
                    predecessor = predecessor.right;
                }

                if (predecessor.right == null)
                {
                    predecessor.right = current;
                    current = current.left;
                }
                else
                {
                    // If its predecessor is a leaf node
                    if (predecessor.left == null)
                        res.Add(predecessor.data);

                    predecessor.right = null;
                    current = current.right;
                }
            }
        }
    }

    // Function to collect the right boundary nodes
    static void collectRight(Node root, List<int> res)
    {
        if (root == null)
            return;

        Node curr = root;
        List<int> temp = new List<int>();
        while (!isLeaf(curr))
        {
            temp.Add(curr.data);

            if (curr.right != null)
                curr = curr.right;
            else
                curr = curr.left;
        }

        for (int i = temp.Count - 1; i >= 0; --i)
            res.Add(temp[i]);
    }

