#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// Recursive function to construct full binary tree
Node* constructBinaryTreeUtil(vector<int> &pre,
                              vector<int> &preMirror,
                              int &preIndex,
                              int l,
                              int h,
                              int n) {

    // Base case
    if (preIndex >= n || l > h)
        return nullptr;

    // Create root node
    Node* root = new Node(pre[preIndex++]);

    // If single element
    if (l == h)
        return root;

    // Find next preorder element in preMirror
    int i;
    for (i = l; i <= h; i++) {
        if (pre[preIndex] == preMirror[i])
            break;
    }

    // Build left and right subtrees
    if (i <= h) {

        root->left = constructBinaryTreeUtil(pre, preMirror,
                                            preIndex, i, h, n);

        root->right = constructBinaryTreeUtil(pre, preMirror,
                                             preIndex, l + 1, i - 1, n);
    }

    return root;
}

Node* constructBinaryTree(vector<int> &pre, vector<int> &preMirror) {

    int n = pre.size();
    int preIndex = 0;

    return constructBinaryTreeUtil(pre, preMirror,
                                   preIndex, 0, n - 1, n);
}

// Inorder traversal
void printInorder(Node* root) {

    if (root == nullptr)
        return;

    printInorder(root->left);
    cout << root->data << " ";
    printInorder(root->right);
}

int main() {

    vector<int> pre = {1, 2, 4, 5, 3, 6, 7};
    vector<int> preMirror = {1, 3, 7, 6, 2, 5, 4};

    Node* root = constructBinaryTree(pre, preMirror);

    printInorder(root);

    return 0;
}

