#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

// Convert Binary Tree to Circular Doubly Linked List.
void inorder(Node* root, Node*& head, Node*& prev) {
    if (root == nullptr)
        return;

    // Recursively traverse the left subtree.
    inorder(root->left, head, prev);

    // Set the first node as head.
    if (prev == nullptr)
        head = root;
    else {
        // Connect the current node with the previous node.
        prev->right = root;
        root->left = prev;
    }

    // Update the previous node.
    prev = root;

    // Recursively traverse the right subtree.
    inorder(root->right, head, prev);
}

// Convert Binary Tree to Circular Doubly Linked List.
Node* bTreeToCList(Node* root) {
    if (root == nullptr)
        return nullptr;

    Node* head = nullptr;
    Node* prev = nullptr;

    inorder(root, head, prev);

    // Connect the last node with the first node.
    prev->right = head;
    head->left = prev;

    return head;
}

// Display the circular doubly linked list.
void display(Node* head) {
    if (head == nullptr)
        return;

    Node* curr = head;

    do {
        cout << curr->data;

        curr = curr->right;

        if (curr != head)
            cout << " <-> ";
    } while (curr != head);

    cout << endl;
}

int main() {

    // Create the binary tree:
    //
    //         10
    //        /  \
    //      20    30
    //     /  \
    //   40    60
    //
    // Inorder: 40 20 60 10 30

    Node* root = new Node(10);
    root->left = new Node(20);
    root->right = new Node(30);
    root->left->left = new Node(40);
    root->left->right = new Node(60);

    Node* head = bTreeToCList(root);

    display(head);

    return 0;
}

