class Node {
    int data;
    Node left;
    Node right;

    Node(int x) {
        data = x;
        left = right = null;
    }
}

class GFG {

    // Convert Binary Tree to Circular Doubly Linked List.
    public static void inorder(Node root, Node[] nodes) {
        if (root == null)
            return;

        // Recursively traverse the left subtree.
        inorder(root.left, nodes);

        // Set the first node as head.
        if (nodes[1] == null)
            nodes[0] = root;
        else {
            // Connect the current node with the previous node.
            nodes[1].right = root;
            root.left = nodes[1];
        }

        // Update the previous node.
        nodes[1] = root;

        // Recursively traverse the right subtree.
        inorder(root.right, nodes);
    }

    // Convert Binary Tree to Circular Doubly Linked List.
    public static Node bTreeToCList(Node root) {
        if (root == null)
            return null;

        Node[] nodes = new Node[2];

        inorder(root, nodes);

        Node head = nodes[0];
        Node prev = nodes[1];

        // Connect the last node with the first node.
        prev.right = head;
        head.left = prev;

        return head;
    }

    // Display the circular doubly linked list.
    public static void display(Node head) {
        if (head == null)
            return;

        Node curr = head;

        do {
            System.out.print(curr.data);

            curr = curr.right;

            if (curr != head)
                System.out.print(" <-> ");
        } while (curr != head);

        System.out.println();
    }

    public static void main(String[] args) {

        // Create the binary tree:
        //
        //         10
        //        /  \
        //      20    30
        //     /  \
        //   40    60
        //
        // Inorder: 40 20 60 10 30

        Node root = new Node(10);
        root.left = new Node(20);
        root.right = new Node(30);
        root.left.left = new Node(40);
        root.left.right = new Node(60);

