#include <bits/stdc++.h>
using namespace std;

class Node {
public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

Node* buildTree(string &s, int &idx) {

    if (idx >= s.size())
        return nullptr;

    // Skip the opening parenthesis of the current subtree
    if (s[idx] == '(')
        idx++;

    // Empty subtree represented as ()
    if (idx < s.size() && s[idx] == ')') {
        idx++;
        return nullptr;
    }

    bool neg = false;
    if (s[idx] == '-') {
        neg = true;
        idx++;
    }

    int num = 0;
    while (idx < s.size() && isdigit(s[idx])) {
        num = num * 10 + (s[idx] - '0');
        idx++;
    }

    Node* root = new Node(neg ? -num : num);

    // Recursively construct the left and right subtrees
    root->left = buildTree(s, idx);
    root->right = buildTree(s, idx);

    if (idx < s.size() && s[idx] == ')')
        idx++;

    return root;
}

int kLevelSum(string &tree, int k) {

    int idx = 0;
    Node* root = buildTree(tree, idx);

    if (!root)
        return 0;

    queue<Node*> q;
    q.push(root);

    int level = 0;

    while (!q.empty()) {

        int sz = q.size();

        // Sum all nodes when the required level is reached
        if (level == k) {

            int sum = 0;

            while (sz--) {
                sum += q.front()->data;
                q.pop();
            }

            return sum;
        }

        while (sz--) {

            Node* curr = q.front();
            q.pop();

            if (curr->left)
                q.push(curr->left);

            if (curr->right)
                q.push(curr->right);
        }

        level++;
    }

    return 0;
}

int main() {

    string tree = "(0(5(6()())(4()(9())))(7(1()())(3()())))";
    int k = 2;

    cout << kLevelSum(tree, k);

    return 0;
}

