        self.right = None

def buildTree(s, idx):

    if idx[0] >= len(s):
        return None

    # Skip the opening parenthesis of the current subtree
    if s[idx[0]] == '(':
        idx[0] += 1

    # Empty subtree represented as ()
    if idx[0] < len(s) and s[idx[0]] == ')':
        idx[0] += 1
        return None

    neg = False
    if s[idx[0]] == '-':
        neg = True
        idx[0] += 1

    num = 0
    while idx[0] < len(s) and s[idx[0]].isdigit():
        num = num * 10 + int(s[idx[0]])
        idx[0] += 1

    root = Node(-num if neg else num)

    # Recursively construct the left and right subtrees
    root.left = buildTree(s, idx)
    root.right = buildTree(s, idx)

    if idx[0] < len(s) and s[idx[0]] == ')':
        idx[0] += 1

    return root

def kLevelSum(tree, k):

    idx = [0]
    root = buildTree(tree, idx)

    if root is None:
        return 0

    q = deque([root])
    level = 0

    while q:

        size = len(q)

        # Sum all nodes when the required level is reached
        if level == k:

            total = 0
            for _ in range(size):
                total += q.popleft().data

            return total

        for _ in range(size):

            curr = q.popleft()

            if curr.left:
                q.append(curr.left)

            if curr.right:
                q.append(curr.right)

        level += 1

    return 0

