        if (idx < s.Length && s[idx] == ')') {
            idx++;
            return null;
        }

        bool neg = false;
        if (s[idx] == '-') {
            neg = true;
            idx++;
        }

        int num = 0;
        while (idx < s.Length && char.IsDigit(s[idx])) {
            num = num * 10 + (s[idx] - '0');
            idx++;
        }

        Node root = new Node(neg ? -num : num);

        // Recursively construct the left and right subtrees
        root.left = buildTree(s, ref idx);
        root.right = buildTree(s, ref idx);

        if (idx < s.Length && s[idx] == ')')
            idx++;

        return root;
    }

    static int kLevelSum(string tree, int k) {

        int idx = 0;
        Node root = buildTree(tree, ref idx);

        if (root == null)
            return 0;

        Queue<Node> q = new Queue<Node>();
        q.Enqueue(root);

        int level = 0;

        while (q.Count > 0) {

            int size = q.Count;

            // Sum all nodes when the required level is reached
            if (level == k) {

                int sum = 0;

                while (size-- > 0)
                    sum += q.Dequeue().data;

                return sum;
            }

            while (size-- > 0) {

                Node curr = q.Dequeue();

                if (curr.left != null)
                    q.Enqueue(curr.left);

                if (curr.right != null)
                    q.Enqueue(curr.right);
            }

            level++;
        }

        return 0;
    }

    static void Main() {

        string tree = "(0(5(6()())(4()(9())))(7(1()())(3()())))";
        int k = 2;

        Console.WriteLine(kLevelSum(tree, k));
    }
}

