function buildTree(s, idx) {

    if (idx.value >= s.length)
        return null;

    // Skip the opening parenthesis of the current subtree
    if (s[idx.value] === '(')
        idx.value++;

    // Empty subtree represented as ()
    if (idx.value < s.length && s[idx.value] === ')') {
        idx.value++;
        return null;
    }

    let neg = false;
    if (s[idx.value] === '-') {
        neg = true;
        idx.value++;
