#include <bits/stdc++.h>
using namespace std;

// Structure of Binary Tree Node
class Node {
public:
    int data;
    Node *left, *right;

    Node(int x) {
        data = x;
        left = right = nullptr;
    }
};

unordered_map<Node*, Node*> par;

// Build the parent mapping and locate the target node
Node* markParents(Node* root, int target) {
    Node* tar = nullptr;

    queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        Node* cur = q.front();
        q.pop();

        if (cur->data == target)
            tar = cur;

        if (cur->left) {
            par[cur->left] = cur;
            q.push(cur->left);
        }

        if (cur->right) {
            par[cur->right] = cur;
            q.push(cur->right);
        }
    }

    return tar;
}

// Find nodes at distance k using BFS
vector<int> kDistanceNodes(Node* root, int target, int k) {
    vector<int> ans;

    // Build the parent mapping and find the target node
    Node* tar = markParents(root, target);

    unordered_set<Node*> vis;
    queue<Node*> q;

    q.push(tar);
    vis.insert(tar);

    int d = 0;

    // Traverse level by level
    while (!q.empty() && d < k) {
        int sz = q.size();

        while (sz--) {
            Node* cur = q.front();
            q.pop();

            if (cur->left && !vis.count(cur->left)) {
                vis.insert(cur->left);
                q.push(cur->left);
            }

            if (cur->right && !vis.count(cur->right)) {
                vis.insert(cur->right);
                q.push(cur->right);
            }

            if (par.count(cur) && !vis.count(par[cur])) {
                vis.insert(par[cur]);
                q.push(par[cur]);
            }
        }

        d++;
    }

    while (!q.empty()) {
        ans.push_back(q.front()->data);
        q.pop();
    }

    // Sort the result
    sort(ans.begin(), ans.end());

    return ans;
}

