function markParents(root, target, par)
{
    let tar = null;

    let q = [ root ];
    let front = 0;

    while (front < q.length) {
        let cur = q[front++];

        if (cur.data === target)
            tar = cur;

        if (cur.left) {
            par.set(cur.left, cur);
            q.push(cur.left);
        }

        if (cur.right) {
            par.set(cur.right, cur);
            q.push(cur.right);
        }
    }

    return tar;
