    let par = new Map();
    let tar = markParents(root, target, par);

    let vis = new Set();
    let q = [ tar ];
    let front = 0;

    vis.add(tar);

    let d = 0;

    // Traverse level by level
    while (front < q.length && d < k) {
        let sz = q.length - front;

        while (sz--) {
            let cur = q[front++];

            if (cur.left && !vis.has(cur.left)) {
                vis.add(cur.left);
                q.push(cur.left);
