        return res;

    // Current level
    stack<Node*> s1;

    // Next level
    stack<Node*> s2;

    s1.push(root);

    while (!s1.empty() || !s2.empty()) {

        // Print nodes of current level from s1
        // and push nodes of next level to s2
        while (!s1.empty()) {
            Node* curr = s1.top();
            s1.pop();
            res.push_back(curr->data);

            if (curr->left)
                s2.push(curr->left);
            if (curr->right)
