// Node Structure
class Node {
    constructor(x) {
        this.data = x;
        this.left = null;
        this.right = null;
    }
}

class Deque {
    constructor() {
        this.front = [];
        this.back = [];
    }

    pushFront(val) {
        this.front.push(val);
    }

    pushBack(val) {
        this.back.push(val);
    }

    popFront() {
        if (this.front.length === 0) this._balance('front');
        return this.front.pop();
    }

    popBack() {
        if (this.back.length === 0) this._balance('back');
        return this.back.pop();
    }

    length() {
        return this.front.length + this.back.length;
    }

    _balance(side) {
        if (side === 'front') {
            while (this.back.length) this.front.push(this.back.pop());
        } else {
            while (this.front.length) this.back.push(this.front.pop());
        }
    }
}

function zigZagTraversal(root) {
    if (!root) return [];

    let res = [];
    let dq = new Deque();
    dq.pushBack(root);
    let reverse = false;

    while (dq.length() > 0) {
        let n = dq.length();

        for (let i = 0; i < n; i++) {

            // Push right to the front
            // first if reverse is true
            if (reverse) {
                let curr = dq.popBack();
                res.push(curr.data);
                if (curr.right) dq.pushFront(curr.right);
                if (curr.left) dq.pushFront(curr.left);
            }

            // Else push left to the back first
            else {
                let curr = dq.popFront();
                res.push(curr.data);
                if (curr.left) dq.pushBack(curr.left);
                if (curr.right) dq.pushBack(curr.right);
            }
        }

        reverse = !reverse;
    }

    return res;
}

