            // Push left and right children to the queue
            if (curr.left !== null) {
                q.push(curr.left);
            }
            if (curr.right !== null) {
                q.push(curr.right);
            }
        }

        // Toggle odd/even level
        isOdd = !isOdd;
    }

    return oddSum - evenSum;
}

