class Node {
public:
    int data;
    Node* left, *right;
    Node (int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

vector<int> ancestors(Node* root, int key) {
    vector<int> res;
    if (root == nullptr) return res;

    stack<Node*> st;
    Node* curr = root;
    Node* prev = nullptr;

    while (curr != nullptr || !st.empty()) {
        if (curr != nullptr) {
            st.push(curr);
            curr = curr->left;
        }
        else {
            Node* topNode = st.top();
            if (topNode->right != nullptr && prev != topNode->right) {
                curr = topNode->right;
            } else {
                if (topNode->data == key) {

                    // Found the key node, now all nodes
                    // in stack are ancestors
                    st.pop();
                    while (!st.empty()) {
                        res.push_back(st.top()->data);
                        st.pop();
                    }
                    return res;
                }
                prev = st.top();
                st.pop();
            }
        }
    }

    return res;
}

