class Node {
public:
    int data;
    Node* left, *right;
    Node (int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

vector<int> extremeNodes(Node* root) {

    vector<int> res;

    if (root == nullptr) return res;

    queue<Node*> q;
    q.push(root);

    bool rightExtreme = true;

    while (!q.empty()) {

        int size = q.size();

        Node* left = q.front(), *right = q.front();

        // Traverse the nodes of current level.
        while (size--) {

            Node* curr = q.front();
            q.pop();

            // If left subtree exists
            if (curr->left != nullptr) {
                q.push(curr->left);
            }

            // If right subtree exists
            if (curr->right != nullptr) {
                q.push(curr->right);
            }

            // Set right node
            right = curr;
        }

        // Append left or right node
        if (rightExtreme) {
            res.push_back(right->data);
        }
        else {
            res.push_back(left->data);
        }

        // Flip the value
        rightExtreme = !rightExtreme;
    }

    return res;
}

