    }
}

// Return the first node on the right
// side of q and at the next level
function getNextRight(p) {
    let temp = p.nextRight;
    while (temp!== null) {
        if (temp.left!== null)
            return temp.left;
        if (temp.right!== null)
            return temp.right;
        temp = temp.nextRight;
    }
    return null;
}

// Function to connect nodes at the same level
function connect(root) {
    if (root === null)
        return null;
    root.nextRight = null;
    while (root!== null) {
        let q = root;
        while (q!== null) {
            if (q.left!== null) {
                if (q.right!== null)
                    q.left.nextRight = q.right;
                else
                    q.left.nextRight = getNextRight(q);
            }
            if (q.right!== null)
                q.right.nextRight = getNextRight(q);
            q = q.nextRight;
        }
        if (root.left!== null)
            root = root.left;
        else if (root.right!== null)
            root = root.right;
        else
            root = getNextRight(root);
    }
    return root;
}

// Main function to test the connect function
function main() {
    // Constructed binary tree
    //       10
    //      /  \
    //    8     2
    //   /     /
    //  3     4
    let root = new Node(10);
    root.left = new Node(8);
    root.right = new Node(2);
    root.left.left = new Node(3);
    root.right.left = new Node(4);
    connect(root);
    console.log(`Next Right of 8 is ${root.left.nextRight.data}`);
    console.log(`Next Right of 3 is ${root.left.left.nextRight.data}`);
}

main();

