    // Finds LCA of two given nodes
    public static Node findLCA(Node root, int p, int q)
    {
        if (root == null)
            return null;

        if (root.data == p || root.data == q)
            return root;

        Node left = findLCA(root.left, p, q);
        Node right = findLCA(root.right, p, q);

        if (left != null && right != null)
            return root;

        return left ? ? right;
    }

    // Stores path from root to target node using L/R
    // directions
    public static bool findPath(Node root, int target,
                                StringBuilder path)
    {
        if (root == null)
            return false;

        if (root.data == target)
            return true;

        // Try going left
        path.Append('L');
        if (findPath(root.left, target, path))
            return true;
        path.Length--;

        // Try going right
        path.Append('R');
        if (findPath(root.right, target, path))
            return true;
        path.Length--;

        return false;
    }

    // Counts direction changes in a path
    public static int countTurns(string path)
    {
        int turns = 0;

        for (int i = 1; i < path.Length; i++) {
