function findLCA(root, p, q)
{
    if (!root)
        return null;

    if (root.data === p || root.data === q)
        return root;

    const left = findLCA(root.left, p, q);
    const right = findLCA(root.right, p, q);

    if (left && right)
        return root;

    return left || right;
}

// Stores path from root to target node using L/R directions
function findPath(root, target, path)
{
    if (!root)
        return false;

    if (root.data === target)
        return true;

    // Try going left
    path.push("L");
    if (findPath(root.left, target, path))
        return true;
    path.pop();

    // Try going right
    path.push("R");
    if (findPath(root.right, target, path))
        return true;
    path.pop();

    return false;
}

// Counts direction changes in a path
function countTurns(path)
{
    let turns = 0;

    for (let i = 1; i < path.length; i++) {
        if (path[i] !== path[i - 1])
            turns++;
    }

    return turns;
}

// Returns number of turns required from first node to
// second node
