    else {
        /*
        We go:
        first -> LCA -> second

        At LCA, we change direction from one subtree
        to another, so it contributes one turn.
        */
        turns = countTurns(pathFirst)
                + countTurns(pathSecond) + 1;
    }

    // No turns means both nodes lie on a straight path
    return turns === 0 ? -1 : turns;
