// Unsets the rightmost set bit
// of n and returns the result
int unsetLSB(int n) {
    if (n == 0)
        return 0;

    // Find the rightmost set bit
    int pos = 0;
    while (((n >> pos) & 1) == 0) {
        pos++;
    }

    // Unset the rightmost set bit
    n = n ^ (1 << pos);

    return n;
}

