// C++ program to find XOR without using ^
#include <iostream>
using namespace std;

// Returns XOR of x and y
int findXor(int x, int y) {
	int res = 0;

	// Assuming 32-bit Integer
	for (int i = 31; i >= 0; i--) {

		// Find current bits in x and y
		bool b1 = (x & (1 << i)) != 0? true:false;
		bool b2 = (y & (1 << i)) != 0? true:false;

		// If bits are opposite,
		// set i'th bit
		if (b1 != b2) {
		    res = res|(1<<i);
		}
	}
	return res;
}

int main() {
	int x = 1, y = 2;
	cout << findXor(x, y);
	return 0;
}

