#include <bits/stdc++.h>
using namespace std;

// Function to swap bits in a given number
int swapBits(int x, int p1, int p2, int n) {

    int shift1, shift2, val1, val2;

    // Process all n bit positions
    while (n--) {

        // Create masks for positions p1 and p2
        shift1 = 1 << p1;
        shift2 = 1 << p2;

        // Extract the bits at positions p1 and p2
        val1 = x & shift1;
        val2 = x & shift2;

        // Swap only if the bits are different
        if ((!val1 && val2) || (val1 && !val2)) {

            // If bit at p1 is set
            if (val1) {

                // Clear bit at p1
                x &= ~shift1;

                // Set bit at p2
                x |= shift2;
            }
            else {

                // Clear bit at p2
                x &= ~shift2;

                // Set bit at p1
                x |= shift1;
            }
        }

        // Move to the next pair of bits
        p1++;
        p2++;
    }

    return x;
}

int main() {

    int x = 28;
    int p1 = 0;
    int p2 = 3;
    int n = 2;

    cout << swapBits(x, p1, p2, n);

    return 0;
}

