int nextPowerOfTwo(int n) {

    if (n <= 1)
        return 1;

    // Decrement n by 1.
    n--;

    // Propagate the most significant set bit to all lower positions.
    n |= (n >> 1);
    n |= (n >> 2);
    n |= (n >> 4);
    n |= (n >> 8);
    n |= (n >> 16);

    // Return the next power of 2.
    return n + 1;
}

