#include <climits>
using namespace std;

// Assumed int size
#define INT_SIZE 32

// A Trie Node
struct TrieNode
{
    int value;  // Only used in leaf nodes
    TrieNode *arr[2];

    TrieNode() {
        value = 0;
        arr[0] = arr[1] = NULL;
    }
};

// Trie Class
class Trie {
    TrieNode* root;

public:
    // Constructor to initialize Trie
    Trie() {
        root = new TrieNode();
    }

    // Inserts pre_xor to trie with given root
    void insert(int pre_xor)
    {
        TrieNode *temp = root;

        // Start from the msb, insert all bits of
        // pre_xor into Trie
        for (int i = INT_SIZE - 1; i >= 0; i--)
        {
            // Find current bit in given prefix
            bool val = pre_xor & (1 << i);

            // Create a new node if needed
            if (temp->arr[val] == NULL)
                temp->arr[val] = new TrieNode();

            temp = temp->arr[val];
        }

        // Store value at leaf node
        temp->value = pre_xor;
    }

    // Finds the maximum XOR ending with last number in
    // prefix XOR 'pre_xor'
    int query(int pre_xor)
    {
        TrieNode *temp = root;

        for (int i = INT_SIZE - 1; i >= 0; i--)
        {
            // Find current bit in given prefix
            bool val = pre_xor & (1 << i);

            // Traverse Trie, first look for a
            // prefix that has opposite bit
            if (temp->arr[1 - val] != NULL)
                temp = temp->arr[1 - val];

            // If there is no prefix with opposite
            // bit, then look for same bit.
            else if (temp->arr[val] != NULL)
                temp = temp->arr[val];
        }

        return pre_xor ^ (temp->value);
    }
};

// Returns maximum XOR value of a subarray
int maxSubarrayXOR(vector<int> &arr)
{
    // Create a Trie and insert 0 into it
    Trie trie;
    trie.insert(0);

    // Initialize answer and xor of current prefix
    int result = INT_MIN, pre_xor = 0;

    // Traverse all input array element
    for (int i = 0; i < arr.size(); i++)
    {
        // update current prefix xor and insert it into Trie
        pre_xor = pre_xor ^ arr[i];
        trie.insert(pre_xor);

        // Query for current prefix xor in Trie and update
        // result if required
        result = max(result, trie.query(pre_xor));
    }
    return result;
}

