    vector<vector<char>> mat = {{'.', '.', '.', '.', '.', '.', '.'},
                                {'.', 'o', '.', '.', '.', '*', '.'},
                                {'.', '.', '.', '.', '.', '.', '.'},
                                {'.', '*', '.', '.', '.', '*', '.'},
                                {'.', '.', '.', '.', '.', '.', '.'}};

    int res = findMinSteps(mat);
