string computeParity(int n)
{
    // Create a lookup table for all 8-bit numbers.
    int parity[256];

    // Parity of 0 is even.
    parity[0] = 0;

    // Precompute parity for numbers from 1 to 255.
    for (int i = 1; i < 256; i++)
    {
        parity[i] = parity[i >> 1] ^ (i & 1);
    }

    // Fold the number into 8 bits using XOR.
    n ^= n >> 16;
    n ^= n >> 8;

    // Get parity using the last 8 bits.
    int res = parity[n & 255];

    // Return the corresponding parity.
    return res ? "odd" : "even";
}

