#include <iostream>
#include <queue>
#include <string>
using namespace std;

// Convert binary string into integer
int convertStringToInt(string s)
{
    int num = 0;

    for (int i = 0; i < s.size(); i++)
        num = num * 2 + (s[i] - '0');

    return num;
}

// Find nth binary palindrome number
int getNthNumber(int n)
{
    // Base case
    if (n == 1)
        return 1;

    n--;

    // Store binary palindrome strings
    queue<string> q;

    // Initialize with second palindrome
    q.push("11");

    // Generate palindromes using BFS
    while (!q.empty()) {

        string curr = q.front();
        q.pop();
        n--;

        // Return when nth palindrome is reached
        if (!n)
            return convertStringToInt(curr);

        int mid = curr.size() / 2;

        // If length is even, insert 0 and 1 at middle
        if (curr.size() % 2 == 0) {
            string s0 = curr, s1 = curr;
            s0.insert(mid, "0");
            s1.insert(mid, "1");
            q.push(s0);
            q.push(s1);
        }

        // If length is odd, duplicate middle character
        else {
            string temp = curr;
            temp.insert(mid, string(1, curr[mid]));
            q.push(temp);
        }
    }

    return 0;
}

int main()
{
    int n = 9;

    cout << getNthNumber(n);
}

