    {
        // Final length
        len_f = 2 * group_no + 1;

        // Set first, last and middle bit
        a[len_f - 1] = a[0] = 1;
        a[group_no] = 0;

        // Fill remaining bits symmetrically
        while (aux_num)
        {
            a[group_no + 1 + i] = a[group_no - 1 - i] = aux_num & 1;
            aux_num >>= 1;
            i++;
        }
    }

    // Insert 1 in middle
    else
    {
