int swapNibbles(int n)
{
    // Take & of 00001111 with number to get right nibble
    int right = (n & 0b00001111);

    // Left shift the right nibble
    right = (right << 4);

    // Take & of 11110000 with number to get left nibble
    int left = (n & 0b11110000);

    // Right shift the left nibble
    left = (left >> 4);

    // Combine both values using bitwise OR
    // ( | ) to get the answer
    return (right | left);
}

