// C++ program to find if a number has alternate bit pattern
#include <bits/stdc++.h>
using namespace std;

// Returns true if n has alternate bit pattern else false
bool findPattern(int n)
{
    // Store last bit
    int prev = n % 2;
    n = n / 2;
    // Traverse through remaining bits
    while (n > 0) {
        int curr = n % 2;
        // If current bit is same as previous
        if (curr == prev)
            return false;
        prev = curr;
        n = n / 2;
    }
    return true;
}

// Driver code
int main()
{
    int n = 10;
    if (findPattern(n))
        cout << "Yes";
    else
        cout << "No";
    return 0;
}

