#include <bits/stdc++.h>
using namespace std;

string twosComplement(string s)
{

    // Flip all bits
    for (int i = 0; i < s.size(); i++)
    {
        s[i] = (s[i] == '0') ? '1' : '0';
    }

    // Add 1 to the flipped string
    int carry = 1;

    for (int i = s.size() - 1; i >= 0; i--)
    {

        if (carry == 0)
            break;

        if (s[i] == '0')
        {
            s[i] = '1';
            carry = 0;
        }
        else
        {
            s[i] = '0';
            carry = 1;
        }
    }

    return s;
}

int main()
{

    string s = "00000101";
    cout << twosComplement(s);
    return 0;
}

