#include <iostream>
using namespace std;

bool alternateBits(int n)
{
    if (n == 0)
        return true;

    int prevBit = n & 1;
    n >>= 1;

    while (n > 0)
    {
        int currBit = n & 1;

        // If adjacent bits are same, not alternating
        if (currBit == prevBit)
        {
            return false;
        }

        prevBit = currBit;
        n >>= 1;
    }

    return true;
}

int main()
{
    int n = 5;
    cout << (alternateBits(n) ? "true" : "false") << endl;
    return 0;
}

