#include <bits/stdc++.h>
using namespace std;

bool isMultipleOf3(string &s)
{
    int rem = 0;
    int x = 1;

    // Traverse the binary string from right to left
    for (int i = s.length() - 1; i >= 0; i--)
    {
        // If the current bit is 1,
        // add its contribution to the remainder.
        if (s[i] - '0' == 1)
        {
            rem = (rem + x) % 3;
        }

        // Update the power of 2 modulo 3
        x = (x * 2) % 3;
    }

    // If the final remainder is 0,
    // the binary number is divisible by 3.
    return rem == 0;
}

int main()
{
    string s = "110";
    cout << (isMultipleOf3(s) ? "true" : "false");

    return 0;
}

