int kthLSB(int n, int k)
{

    vector<int> bits;

    // Store binary representation from LSB to MSB.
    while (n > 0)
    {
        bits.push_back(n % 2);
        n /= 2;
    }

    // If kth bit does not exist, it is 0.
    if (k > bits.size())
        return 0;

    return bits[k - 1];
}

