int findCatalan(int n)
{
    // res holds the current Catalan number at each step, starting from C(0) = 1
    long long res = 1;

    // build each Catalan number directly from the previous one,
    // using the recurrence C(i) = C(i-1) * (4i-2)/(i+1)
    for (int i = 2; i <= n; i++)
    {
        // res must stay 'long long' here: the intermediate multiplication
        // (res * (4*i - 2)) can briefly exceed int range before the
        // division brings it back down to the actual Catalan number
        res = (res * (4 * i - 2)) / (i + 1);
    }

    // explicit cast: safe here since n <= 19 keeps the result within int range
    return (int)res;
}

