        // same as last row of matrix
        for (int i = 0; i < n; i++)
            dp[i] = triangle[n - 1][i];

        // Calculation of the remaining rows,
        // in bottom up manner
        for (int i = triangle.Count - 2; i >= 0; i--) {
            int[] new_dp = new int[i + 1];
            for (int j = 0; j < triangle[i].Count; j++) {

