// Function to find the elements
// of n'th row in Pascal's Triangle
vector<int> nthRowOfPascalTriangle(int n) {

    // To follow 0 based indexing, decrement n
    n--;

    vector<int> res;

    // nC0 = 1
    int prev = 1;
    res.push_back(prev);

    for (int i = 1; i <= n; i++) {

        // nCr = (nCr-1 * (n - r + 1))/r
        int curr = (prev * (n - i + 1)) / i;
        res.push_back(curr);
        prev = curr;
    }
    return res;
}

