#include <iostream>
using namespace std;

int solve(int i, int j, int m, int n) {

    // Base case - reached bottom-right cell
    if (i == m - 1 && j == n - 1)
        return 1;

    // Out of bounds
    if (i >= m || j >= n)
        return 0;

    // Move down or right
    return solve(i + 1, j, m, n) + solve(i, j + 1, m, n);
}

int numberOfPaths(int m, int n) {
    return solve(0, 0, m, n);
}

int main() {
    int m = 2, n = 3;
    cout << numberOfPaths(m, n);
    return 0;
}

