                dp[j] = max(dp[j], currentLength + 1);
            }

            // If a[i] is greater, update best LCIS so far
            else if (a[i] > b[j]) {
                currentLength = max(currentLength, dp[j]);
            }

        }
    }

    // The maximum value in dp gives final LCIS length
    return *max_element(dp.begin(), dp.end());
