void distSumRec(vector<int> &arr, int n, int sum,
                int i, set<int> &s) {
    if (i > n)
        return;

    if (i == n) {
        s.insert(sum);
        return;
    }

    // Include the current element
    distSumRec(arr, n, sum + arr[i], i + 1, s);

    // Exclude the current element
    distSumRec(arr, n, sum, i + 1, s);
}

