        // Equivalent to dp[1]
        int prev2 = 0;

        // Equivalent to dp[2]
        int prev1 = 1;

        // Calculate derangements using the optimized
      	// space approach
        for (int i = 3; i <= n; i++) {
            int curr = (i - 1) * (prev1 + prev2);
            prev2 = prev1;
            prev1 = curr;
        }

        return prev1;
    }

    static void Main() {
        int n = 5;
        Console.WriteLine(derangeCount(n));
    }
