{
    int x = 3; // max tasks machine A can process
    int y = 3; // max tasks machine B can process

    vector<int> a = {1, 2, 3, 4, 5};
    vector<int> b = {5, 4, 3, 2, 1};

    cout << maxProfit(x, y, a, b);

    return 0;
}

