    int n = s.length();

    // Memoization table
    vector<vector<int>> memo(n, vector<int>(n, -1));

    int res = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

             // Check if the substring is palindrome
            if (isPalindrome(i, j, s, memo)) {
                res++;
            }
        }
    }

    return res;
}

