        for (int i = 1; i < n; i++) {
            // j = 0 means the string stri[i] is reversed
            // j = 1 means not reversed
            for (int j = 0; j <= 1; j++) {
                // Current string and cost if reversed or not
                string currStr = (j == 1) ? reversed[i] : arr[i];
                int currCost = (j == 1) ? cost[i] : 0;

