    // function to pre-calculate the array out[]
    // which stores the maximum height when traveled
    // via parent
    static void dfs2(Node root, HashMap<Node, Integer> out,
    HashMap<Node, Integer> in) {

        // stores the longest and second
        // longest branches
        int mx1 = -1, mx2 = -1;

        // traverse in the subtrees of root
        for (Node child : root.children) {

            // compare and store the longest
            // and second longest
            if (in.get(child) >= mx1) {
                mx2 = mx1;
                mx1 = in.get(child);
            } else if (in.get(child) > mx2) {
                mx2 = in.get(child);
            }
        }

        // traverse in the subtree of root
        for (Node child : root.children) {
            int longest = mx1;

            // if longest branch has the node, then
            // consider the second longest branch
            if (mx1 == in.get(child))
                longest = mx2;

            // recursively calculate out[i]
            out.put(child, 1 + Math.max(out.getOrDefault(root, 0), 1 + longest));

            // dfs function call
            dfs2(child, out, in);
        }
