            if ((assignedPeople & (1 << person)) == 0) {

                // Assign current cap to the person
                ways += dfs(allMask,
                            assignedPeople | (1 << person),
                                cap + 1, capToPeople, memo);
            }
        }

        // Memoize and return the result
        memo[cap][assignedPeople] = ways;
        return ways;
    }

