using namespace std;

string getLongestPal(string &s)
{
    if (s.empty())
        return "";

    // Transform the string using separators
    // and sentinels.
    string ms = "@";

    for (char c : s)
    {
        ms += "#" + string(1, c);
    }

    ms += "#$";

    int m = ms.size();
    vector<int> p(m, 0);

    int l = 0, r = 0;

    // Manacher's algorithm
    for (int i = 1; i < m - 1; ++i)
    {

        // Use the mirror position
        if (i < r)
        {
            int mirror = l + r - i;
            p[i] = min(r - i, p[mirror]);
        }

        // Expand around the current center
        while (ms[i + 1 + p[i]] == ms[i - 1 - p[i]])
        {
            ++p[i];
        }

        // Update the current palindrome range
        if (i + p[i] > r)
        {
            l = i - p[i];
            r = i + p[i];
        }
    }

    int maxLen = 1;
    int start = 0;

    // Find the longest palindrome
    for (int i = 1; i < m - 1; ++i)
    {
        if (p[i] > maxLen)
        {
            maxLen = p[i];
            start = (i - p[i]) / 2;
        }
    }

    return s.substr(start, maxLen);
}

