                dp[i][j] = (s[i] === s[j]) ? 0 : 1;
            }
            else {

                // If first and last characters match
                if (s[i] === s[j]) {
                    dp[i][j] = dp[i+1][j-1];
                }
                else {

                    // If they don't match, consider minimum of two choices
                    dp[i][j] = 1 + Math.min(dp[i+1][j], dp[i][j-1]);
                }
            }
        }
    }

    // Return minimum deletions for entire string
    return dp[0][n-1];
