{
    static bool IsBitonic(List<int> seq)
    {
        int n = seq.Count;

        if (n < 3)
            return false;

        int i = 1;

        // Strictly increasing part.
        while (i < n && seq[i] > seq[i - 1])
        {
            i++;
        }

        // There must be a decreasing part.
        if (i == 1 || i == n)
            return false;

        // Strictly decreasing part.
        while (i < n && seq[i] < seq[i - 1])
        {
            i++;
        }

        return i == n;
