#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int longestBitonicSequence(vector<int>& arr) {
    int n = arr.size();

    if (n < 3)
        return 0;

    vector<int> lis(n, 1);
    vector<int> lds(n, 1);

    // Compute LIS ending at every index.
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (arr[j] < arr[i]) {
                lis[i] = max(lis[i], lis[j] + 1);
            }
        }
    }

    // Compute LDS starting at every index.
    for (int i = n - 1; i >= 0; i--) {
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[i]) {
                lds[i] = max(lds[i], lds[j] + 1);
            }
        }
    }

    int maxLen = 0;

    for (int i = 0; i < n; i++) {
        // Both increasing and decreasing parts must exist.
        if (lis[i] > 1 && lds[i] > 1) {
            maxLen = max(maxLen, lis[i] + lds[i] - 1);
        }
    }

    return maxLen;
}

int main() {
    vector<int> arr1 = {1, 2, 5, 3, 2};
    cout << longestBitonicSequence(arr1) << endl;

    vector<int> arr2 = {1, 11, 2, 10, 4, 5, 2, 1};
    cout << longestBitonicSequence(arr2) << endl;

    return 0;
}

