int maxWeightNode(vector<int>& exits) {
    int n = exits.size();

    int maxWeight = -1;
    int answer = -1;

    // Calculate the weight of every node separately.
    for (int i = 0; i < n; i++) {
        int currentWeight = 0;

        // Find all nodes pointing to node i.
        for (int j = 0; j < n; j++) {
            if (exits[j] == i) {
                currentWeight += j;
            }
        }

        // Update answer.
        // >= ensures the larger index is chosen in case of a tie.
        if (currentWeight >= maxWeight) {
            maxWeight = currentWeight;
            answer = i;
        }
    }

    return answer;
}

