int findMinCycle(int V, vector<vector<int>>& edges) {
    vector<vector<vector<int>>> adj = constructadj(V, edges);
    int minCycle = INT_MAX;

    for (const auto& edge : edges) {
        int u = edge[0];
        int v = edge[1];
        int w = edge[2];

        int dist = shortestPath(V, adj, u, v);

        if (dist != INT_MAX) {
            minCycle = min(minCycle, dist + w);
        }
    }

    return minCycle;
}

