// Function to perform topological sort
void topoSort(vector<vector<int>> &adj, vector<int> &topo) {
    int V = adj.size();
    vector<int> indegree(V, 0);

    // Calculate in-degree of all vertices
    for (int u = 0; u < V; u++) {
        for (int v : adj[u]) {
            indegree[v]++;
        }
    }

    queue<int> q;

    // Push all vertices with in-degree 0
    for (int i = 0; i < V; i++) {
        if (indegree[i] == 0) {
            q.push(i);
        }
    }

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        topo.push_back(u);

        for (int v : adj[u]) {
            indegree[v]--;
            if (indegree[v] == 0) {
                q.push(v);
            }
        }
    }
}

// Function to return maximum number of additional edges in DAG
int maxEdgesToAdd(vector<vector<int>> &adj) {
    int V = adj.size();
    vector<vector<bool>> exists(V, vector<bool>(V, false));

    // Build existence map from adjacency list
    for (int u = 0; u < V; u++) {
        for (int v : adj[u]) {
            exists[u][v] = true;
        }
    }

    vector<int> topo;
    topoSort(adj, topo);

    int count = 0;

    // Count forward edges that can be added without creating cycles
    for (int i = 0; i < V; i++) {
        for (int j = i + 1; j < V; j++) {
            int u = topo[i];
            int v = topo[j];

            if (!exists[u][v]) {
                count++;
            }
        }
    }

    return count;
}

