from collections import deque

# Function to perform topological sort
def topoSort(adj):
    V = len(adj)
    indegree = [0] * V

    # Calculate in-degree of all vertices
    for u in range(V):
        for v in adj[u]:
            indegree[v] += 1

    q = deque()
    # Push all vertices with in-degree 0
    for i in range(V):
        if indegree[i] == 0:
            q.append(i)

    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indegree[v] -= 1
            if indegree[v] == 0:
                q.append(v)

    return topo

# Function to return maximum number of additional edges in DAG
def maxEdgesToAdd(adj):
    V = len(adj)
    exists = [[False] * V for _ in range(V)]

    # Build existence map from adjacency list
    for u in range(V):
        for v in adj[u]:
            exists[u][v] = True

    topo = topoSort(adj)
    count = 0

    # Count forward edges that can be added without creating cycles
    for i in range(V):
        for j in range(i + 1, V):
            u = topo[i]
            v = topo[j]
            if not exists[u][v]:
                count += 1

    return count

