#include <bits/stdc++.h>
using namespace std;

// Tries to traverse all edges exactly once.
bool dfs(int u, int start, int usedEdges, int totalEdges, vector<vector<pair<int, int>>> &adj,
         vector<bool> &used, bool &isCircuit)
{
    if (usedEdges == totalEdges)
    {
        if (u == start)
            isCircuit = true;
        return true;
    }

    for (auto [v, id] : adj[u])
    {
        if (!used[id])
        {
            used[id] = true;

            if (dfs(v, start, usedEdges + 1, totalEdges, adj, used, isCircuit))
                return true;

            used[id] = false;
        }
    }

    return false;
}

int isEulerCircuit(int V, vector<vector<int>> &graph)
{
    vector<vector<pair<int, int>>> adj(V);

    int id = 0;

    // Assign a unique id to every undirected edge.
    for (int u = 0; u < V; u++)
    {
        for (int v : graph[u])
        {
            if (u < v)
            {
                adj[u].push_back({v, id});
                adj[v].push_back({u, id});
                id++;
            }
        }
    }

    int E = id;

    bool foundPath = false;
    bool foundCircuit = false;

    // Try every starting vertex.
    for (int start = 0; start < V; start++)
    {
        vector<bool> used(E, false);
        bool isCircuit = false;

        if (dfs(start, start, 0, E, adj, used, isCircuit))
        {
            foundPath = true;

            if (isCircuit)
                foundCircuit = true;
        }
    }

    if (foundCircuit)
        return 2;
    if (foundPath)
        return 1;
    return 0;
}

