import java.util.*;

class Pair {
    int v, id;

    Pair(int v, int id)
    {
        this.v = v;
        this.id = id;
    }
}

public class GFG {

    // Tries to traverse all edges exactly once.
    static boolean dfs(int u, int start, int usedEdges,
                       int totalEdges,
                       ArrayList<ArrayList<Pair> > adj,
                       boolean[] used, boolean[] isCircuit)
    {

        if (usedEdges == totalEdges) {
            if (u == start)
                isCircuit[0] = true;
            return true;
        }

        for (Pair p : adj.get(u)) {
            if (!used[p.id]) {
                used[p.id] = true;

                if (dfs(p.v, start, usedEdges + 1,
                        totalEdges, adj, used, isCircuit))
                    return true;

                used[p.id] = false;
            }
        }

        return false;
    }

    static int isEulerCircuit(int V, int[][] graph)
    {

        ArrayList<ArrayList<Pair> > adj = new ArrayList<>();

        for (int i = 0; i < V; i++)
            adj.add(new ArrayList<>());

        int id = 0;

        // Assign a unique id to every undirected edge.
        for (int u = 0; u < V; u++) {
            for (int v : graph[u]) {
                if (u < v) {
                    adj.get(u).add(new Pair(v, id));
                    adj.get(v).add(new Pair(u, id));
                    id++;
                }
            }
        }

        int E = id;

        boolean foundPath = false;
        boolean foundCircuit = false;

        // Try every starting vertex.
        for (int start = 0; start < V; start++) {

            boolean[] used = new boolean[E];
            boolean[] isCircuit = new boolean[1];

            if (dfs(start, start, 0, E, adj, used,
                    isCircuit)) {

                foundPath = true;

                if (isCircuit[0])
                    foundCircuit = true;
            }
        }

        if (foundCircuit)
            return 2;
        if (foundPath)
            return 1;
        return 0;
    }

    public static void main(String[] args)
    {

        int V = 3;

        int[][] adj = { { 1, 2 }, { 0, 2 }, { 0, 1 } };

        System.out.println(isEulerCircuit(V, adj));
    }
}

