class GfG {

    // dfs Function to reach destination
    boolean dfs(int curr, int des, int[][] adj, int[] vis, int n) {
        if (curr == des) return true;
        vis[curr] = 1;

        for (int i = 1; i <= n; i++) {
            if (adj[curr][i] == 1 && vis[i] == 0) {
                if (dfs(i, des, adj, vis, n)) return true;
            }
        }
        return false;
    }

    // To tell whether there is path from source to destination
    boolean isPath(int src, int des, int[][] adj, int n) {
        int[] vis = new int[n + 1];
        return dfs(src, des, adj, vis, n);
    }

    // Function to return all the strongly connected component of a graph.
    int[][] findSCC(int n, int[][] a, int m) {
        // Stores whether a vertex is part of any SCC
        int[] is_scc = new int[n + 1];

        // Adjacency matrix representation of graph
        int[][] adj = new int[n + 1][n + 1];
        for (int i = 0; i < m; i++) {
            int u = a[i][0];
            int v = a[i][1];
            adj[u][v] = 1;
        }

        // Result array to store all SCCs (assume worst-case n SCCs of size n)
        int[][] result = new int[n][n + 1]; // +1 to store count at index 0
        int sccCount = 0;

        // Traversing all the vertices
        for (int i = 1; i <= n; i++) {
            if (is_scc[i] == 0) {
                int[] scc = new int[n + 1];
                int size = 0;
                scc[++size] = i;

                for (int j = i + 1; j <= n; j++) {
                    if (is_scc[j] == 0 && isPath(i, j, adj, n) && isPath(j, i, adj, n)) {
                        is_scc[j] = 1;
                        scc[++size] = j;
                    }
                }

                // Mark current node as visited in SCC
                is_scc[i] = 1;

                // Store size at index 0 and then elements
                scc[0] = size;
                result[sccCount++] = scc;
            }
        }

        // Trim result to valid SCCs only
        int[][] finalResult = new int[sccCount][];
        for (int i = 0; i < sccCount; i++) {
            int size = result[i][0];
            finalResult[i] = new int[size];
            for (int j = 0; j < size; j++) {
                finalResult[i][j] = result[i][j + 1];
            }
        }

        return finalResult;
    }
}

