using System;

class GfG
{
    // DFS function to reach destination
    public bool dfs(int curr, int des, int[,] adj, int[] vis, int n)
    {
        if (curr == des) return true;
        vis[curr] = 1;

        for (int i = 1; i <= n; i++)
        {
            if (adj[curr, i] == 1 && vis[i] == 0)
            {
                if (dfs(i, des, adj, vis, n)) return true;
            }
        }
        return false;
    }

    // To tell whether there is a path from source to destination
    public bool isPath(int src, int des, int[,] adj, int n)
    {
        int[] vis = new int[n + 1];
        return dfs(src, des, adj, vis, n);
    }

    // Function to return all the strongly connected components of a graph
    public int[][] findSCC(int n, int[,] edges, int m)
    {
        int[,] adj = new int[n + 1, n + 1];
        for (int i = 0; i < m; i++)
        {
            int u = edges[i, 0];
            int v = edges[i, 1];
            adj[u, v] = 1;
        }

        int[] isScc = new int[n + 1];
        int[][] result = new int[n][];
        int sccIndex = 0;

        for (int i = 1; i <= n; i++)
        {
            if (isScc[i] == 0)
            {
                int[] temp = new int[n + 1]; // [0] stores size
                int size = 0;
                temp[++size] = i;

                for (int j = i + 1; j <= n; j++)
                {
                    if (isScc[j] == 0 && isPath(i, j, adj, n) && isPath(j, i, adj, n))
                    {
                        isScc[j] = 1;
                        temp[++size] = j;
                    }
                }

                isScc[i] = 1;
                temp[0] = size;

                int[] scc = new int[size];
                for (int k = 0; k < size; k++)
                {
                    scc[k] = temp[k + 1];
                }

                result[sccIndex++] = scc;
            }
        }

        // Trim result to actual number of SCCs
        int[][] finalResult = new int[sccIndex][];
        for (int i = 0; i < sccIndex; i++)
        {
            finalResult[i] = result[i];
        }

        return finalResult;
    }
}

