    static boolean hasEulerianPath(int[][] adj, int[] start, int n) {
        int odd = 0;

        for (int i = 0; i < n; i++) {
            int deg = 0;
            for (int j = 0; j < n; j++) {
                deg += adj[i][j];
            }

            if (deg % 2 != 0) {
                odd++;
                start[0] = i;
            }
        }

        return (odd == 0 || odd == 2);
