    static void dfs(int u, int[][] adj,
                    List<Integer> path, int n) {

        for (int v = 0; v < n; v++) {
            while (adj[u][v] > 0) {
                adj[u][v]--;
                adj[v][u]--;
                dfs(v, adj, path, n);
            }
        }

        path.add(u);
    }

    // Return the Eulerian path or [-1] if not possible
    static List<Integer> findEulerianPath(int[][] adj) {
        int n = adj.length;
        int[] start = new int[1];

