                    vis[v] = true;
                    parent[v] = u;

                    // Sink reached, augmenting path found
                    if (v == sink)
                        return true;

                    q.offer(v);
                }
            }
        }

        return false;
    }

    // Returns the maximum flow from source (1) to sink (V)
    static int findMaxFlow(int V, int[][] edges) {

        // Capacity graph
        int[][] graph = new int[V + 1][V + 1];

        for (int[] edge : edges) {

            int u = edge[0];
            int v = edge[1];
            int cap = edge[2];

            graph[u][v] = cap;
        }

        // Residual graph initially equals the capacity graph
        int[][] rGraph = new int[V + 1][V + 1];

        for (int i = 0; i <= V; i++)
            rGraph[i] = graph[i].clone();

        int src = 1;
        int sink = V;

        int[] parent = new int[V + 1];
        int maxFlow = 0;

        // Keep finding augmenting paths
        while (bfs(rGraph, src, sink, parent)) {

            int pathFlow = Integer.MAX_VALUE;

            // Find bottleneck capacity of the current path
            for (int v = sink; v != src; v = parent[v]) {

                int u = parent[v];
                pathFlow = Math.min(pathFlow, rGraph[u][v]);
            }

            // Update residual capacities of forward and reverse edges
            for (int v = sink; v != src; v = parent[v]) {

                int u = parent[v];

                rGraph[u][v] -= pathFlow;
                rGraph[v][u] += pathFlow;
            }

            // Add path flow to the total maximum flow
            maxFlow += pathFlow;
        }

        return maxFlow;
    }

    public static void main(String[] args) {

        int V = 4;

        int[][] edges = {
            {1, 2, 10},
            {1, 3, 10},
            {2, 3, 10},
            {2, 4, 10},
            {3, 4, 10}
        };

        System.out.println(findMaxFlow(V, edges));
    }
}

