#include <bits/stdc++.h>
using namespace std;

int pairCost(int mask, vector<int> &odd, vector<vector<int>> &dist, vector<int> &dp)
{
    int k = odd.size();

    if (mask == (1 << k) - 1)
        return 0;

    if (dp[mask] != -1)
        return dp[mask];

    int first = 0;

    while (mask & (1 << first))
        first++;

    int ans = INT_MAX;

    // Pair the first unpaired odd-degree vertex with every other unpaired vertex.

    for (int j = first + 1; j < k; j++)
    {
        if (!(mask & (1 << j)))
        {
            int newMask = mask | (1 << first) | (1 << j);

            int cost = dist[odd[first]][odd[j]] + pairCost(newMask, odd, dist, dp);

            ans = min(ans, cost);
        }
    }

    return dp[mask] = ans;
}

int minTourCost(int n, vector<vector<int>> &edges)
{
    const int INF = 1e9;

    vector<vector<int>> dist(n, vector<int>(n, INF));
    vector<vector<int>> adj(n);
    vector<int> degree(n, 0);

    int totalCost = 0;

    // Initialize distance from every vertex to itself as zero.

    for (int i = 0; i < n; i++)
        dist[i][i] = 0;

    // Build the graph, calculate degrees, and store the total edge cost.

    for (auto &edge : edges)
    {
        int u = edge[0] - 1;
        int v = edge[1] - 1;
        int w = edge[2];

        dist[u][v] = min(dist[u][v], w);
        dist[v][u] = min(dist[v][u], w);

        adj[u].push_back(v);
        adj[v].push_back(u);

        degree[u]++;
        degree[v]++;

        totalCost += w;
    }

    // Find a vertex that is incident to at least one edge.

    int start = -1;

    for (int i = 0; i < n; i++)
    {
        if (degree[i] > 0)
        {
            start = i;
            break;
        }
    }

    if (start == -1)
        return 0;

    // Check that all vertices with edges belong to the same component.

    vector<bool> visited(n, false);
    queue<int> q;

    q.push(start);
    visited[start] = true;

    while (!q.empty())
    {
        int u = q.front();
        q.pop();

        for (int v : adj[u])
        {
            if (!visited[v])
            {
                visited[v] = true;
                q.push(v);
            }
        }
    }

    for (int i = 0; i < n; i++)
    {
        if (degree[i] > 0 && !visited[i])
            return -1;
    }

    // Compute the shortest distance between every pair of vertices.

    for (int k = 0; k < n; k++)
    {
        for (int i = 0; i < n; i++)
        {
            for (int j = 0; j < n; j++)
            {
                if (dist[i][k] < INF && dist[k][j] < INF)
                {
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    vector<int> odd;

    // Collect all vertices having odd degree.

    for (int i = 0; i < n; i++)
    {
        if (degree[i] % 2 == 1)
            odd.push_back(i);
    }

    int k = odd.size();

    if (k == 0)
        return totalCost;

    vector<int> dp(1 << k, -1);

    // Find the minimum additional cost required to pair all odd vertices.

    int extraCost = pairCost(0, odd, dist, dp);

    return totalCost + extraCost;
}

int main()
{
    int n = 4;

    vector<vector<int>> edges = {{1, 2, 2}, {2, 3, 3}, {3, 1, 1}, {3, 4, 2}};

    cout << minTourCost(n, edges) << '\n';

    return 0;
}

