import java.util.*;

class GFG {

    static int pairCost(int mask, int[] odd, int[][] dist,
                        int[] dp)
    {
        int k = odd.length;

        if (mask == (1 << k) - 1)
            return 0;

        if (dp[mask] != -1)
            return dp[mask];

        int first = 0;

        while ((mask & (1 << first)) != 0)
            first++;

        int ans = Integer.MAX_VALUE;

        // Pair the first unpaired odd-degree vertex with
        // every other unpaired vertex.

        for (int j = first + 1; j < k; j++) {
            if ((mask & (1 << j)) == 0) {
                int newMask
                    = mask | (1 << first) | (1 << j);

                int cost
                    = dist[odd[first]][odd[j]]
                      + pairCost(newMask, odd, dist, dp);

                ans = Math.min(ans, cost);
            }
        }

        return dp[mask] = ans;
    }

    static int minTourCost(int n, int[][] edges)
    {
        final int INF = 1000000000;

        int[][] dist = new int[n][n];
        int[] degree = new int[n];
        ArrayList<Integer>[] adj = new ArrayList[n];

        for (int i = 0; i < n; i++) {
            Arrays.fill(dist[i], INF);
            dist[i][i] = 0;
            adj[i] = new ArrayList<>();
        }

        int totalCost = 0;

        // Build the graph, calculate degrees, and store the
        // total edge cost.

        for (int[] edge : edges) {
            int u = edge[0] - 1;
            int v = edge[1] - 1;
            int w = edge[2];

            dist[u][v] = Math.min(dist[u][v], w);
            dist[v][u] = Math.min(dist[v][u], w);

            adj[u].add(v);
            adj[v].add(u);

            degree[u]++;
            degree[v]++;

            totalCost += w;
        }

        // Find a vertex that is incident to at least one
        // edge.

        int start = -1;

        for (int i = 0; i < n; i++) {
            if (degree[i] > 0) {
                start = i;
                break;
            }
        }

        if (start == -1)
            return 0;

        // Check that all vertices with edges belong to the
        // same component.

        boolean[] visited = new boolean[n];
        Queue<Integer> q = new LinkedList<>();

        q.add(start);
        visited[start] = true;

        while (!q.isEmpty()) {
            int u = q.poll();

            for (int v : adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.add(v);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (degree[i] > 0 && !visited[i])
                return -1;
        }

        // Compute the shortest distance between every pair
        // of vertices.

        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dist[i][k] < INF
                        && dist[k][j] < INF) {
                        dist[i][j] = Math.min(
                            dist[i][j],
                            dist[i][k] + dist[k][j]);
                    }
                }
            }
        }

        ArrayList<Integer> oddList = new ArrayList<>();

        // Collect all vertices having odd degree.

        for (int i = 0; i < n; i++) {
            if (degree[i] % 2 == 1)
                oddList.add(i);
        }

        int k = oddList.size();
        int[] odd = new int[k];

        for (int i = 0; i < k; i++)
            odd[i] = oddList.get(i);

        if (k == 0)
            return totalCost;

        int[] dp = new int[1 << k];
        Arrays.fill(dp, -1);

        // Find the minimum additional cost required to pair
        // all odd vertices.

        int extraCost = pairCost(0, odd, dist, dp);

        return totalCost + extraCost;
    }

    public static void main(String[] args)
    {
        int n = 4;

        int[][] edges = { { 1, 2, 2 },
                          { 2, 3, 3 },
                          { 3, 1, 1 },
                          { 3, 4, 2 } };

        System.out.println(minTourCost(n, edges));
    }
}

