def pairCost(mask, odd, dist, dp):
    k = len(odd)

    if mask == (1 << k) - 1:
        return 0

    if dp[mask] != -1:
        return dp[mask]

    first = 0

    while mask & (1 << first):
        first += 1

    ans = float('inf')

    # Pair the first unpaired odd-degree vertex with every other unpaired vertex.

    for j in range(first + 1, k):
        if not (mask & (1 << j)):
            newMask = mask | (1 << first) | (1 << j)

            cost = dist[odd[first]][odd[j]] + pairCost(
                newMask, odd, dist, dp
            )

            ans = min(ans, cost)

    dp[mask] = ans
    return ans

def minTourCost(n, edges):
    INF = 10**9

    dist = [[INF] * n for _ in range(n)]
    degree = [0] * n
    adj = [[] for _ in range(n)]

    totalCost = 0

    # Initialize distance from every vertex to itself as zero.

    for i in range(n):
        dist[i][i] = 0

    # Build the graph, calculate degrees, and store the total edge cost.

    for edge in edges:
        u = edge[0] - 1
        v = edge[1] - 1
        w = edge[2]

        dist[u][v] = min(dist[u][v], w)
        dist[v][u] = min(dist[v][u], w)

        adj[u].append(v)
        adj[v].append(u)

        degree[u] += 1
        degree[v] += 1

        totalCost += w

    # Find a vertex that is incident to at least one edge.

    start = -1

    for i in range(n):
        if degree[i] > 0:
            start = i
            break

    if start == -1:
        return 0

    # Check that all vertices with edges belong to the same component.

    visited = [False] * n
    q = deque([start])
    visited[start] = True

    while q:
        u = q.popleft()

        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)

    for i in range(n):
        if degree[i] > 0 and not visited[i]:
            return -1

    # Compute the shortest distance between every pair of vertices.

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] < INF and dist[k][j] < INF:
                    dist[i][j] = min(
                        dist[i][j],
                        dist[i][k] + dist[k][j]
                    )

    odd = []

    # Collect all vertices having odd degree.

    for i in range(n):
        if degree[i] % 2 == 1:
            odd.append(i)

    k = len(odd)

    if k == 0:
        return totalCost

    dp = [-1] * (1 << k)

    # Find the minimum additional cost required to pair all odd vertices.

    extraCost = pairCost(0, odd, dist, dp)

    return totalCost + extraCost

