using System;
using System.Collections.Generic;

class GFG {
    static int pairCost(int mask, int[] odd, int[][] dist,
                        int[] dp)
    {
        int k = odd.Length;

        if (mask == (1 << k) - 1)
            return 0;

        if (dp[mask] != -1)
            return dp[mask];

        int first = 0;

        while ((mask & (1 << first)) != 0)
            first++;

        int ans = int.MaxValue;

        // Pair the first unpaired odd-degree vertex with
        // every other unpaired vertex.

        for (int j = first + 1; j < k; j++) {
            if ((mask & (1 << j)) == 0) {
                int newMask
                    = mask | (1 << first) | (1 << j);

                int cost
                    = dist[odd[first]][odd[j]]
                      + pairCost(newMask, odd, dist, dp);

                ans = Math.Min(ans, cost);
            }
        }

        return dp[mask] = ans;
    }

    static int minTourCost(int n, int[][] edges)
    {
        const int INF = 1000000000;

        int[][] dist = new int[n][];
        int[] degree = new int[n];
        List<int>[] adj = new List<int>[ n ];

        for (int i = 0; i < n; i++) {
            dist[i] = new int[n];
            Array.Fill(dist[i], INF);

            dist[i][i] = 0;
            adj[i] = new List<int>();
        }

        int totalCost = 0;

        // Build the graph, calculate degrees, and store the
        // total edge cost.

        foreach(int[] edge in edges)
        {
            int u = edge[0] - 1;
            int v = edge[1] - 1;
            int w = edge[2];

            dist[u][v] = Math.Min(dist[u][v], w);
            dist[v][u] = Math.Min(dist[v][u], w);

            adj[u].Add(v);
            adj[v].Add(u);

            degree[u]++;
            degree[v]++;

            totalCost += w;
        }

        // Find a vertex that is incident to at least one
        // edge.

        int start = -1;

        for (int i = 0; i < n; i++) {
            if (degree[i] > 0) {
                start = i;
                break;
            }
        }

        if (start == -1)
            return 0;

        // Check that all vertices with edges belong to the
        // same component.

        bool[] visited = new bool[n];
        Queue<int> q = new Queue<int>();

        q.Enqueue(start);
        visited[start] = true;

        while (q.Count > 0) {
            int u = q.Dequeue();

            foreach(int v in adj[u])
            {
                if (!visited[v]) {
                    visited[v] = true;
                    q.Enqueue(v);
                }
            }
        }

        for (int i = 0; i < n; i++) {
            if (degree[i] > 0 && !visited[i])
                return -1;
        }

        // Compute the shortest distance between every pair
        // of vertices.

        for (int mid = 0; mid < n; mid++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (dist[i][mid] < INF
                        && dist[mid][j] < INF) {
                        dist[i][j] = Math.Min(
                            dist[i][j],
                            dist[i][mid] + dist[mid][j]);
                    }
                }
            }
        }

        List<int> oddList = new List<int>();

        // Collect all vertices having odd degree.

        for (int i = 0; i < n; i++) {
            if (degree[i] % 2 == 1)
                oddList.Add(i);
        }

        int k = oddList.Count;
        int[] odd = new int[k];

        for (int i = 0; i < k; i++)
            odd[i] = oddList[i];

        if (k == 0)
            return totalCost;

        int[] dp = new int[1 << k];

        Array.Fill(dp, -1);

        // Find the minimum additional cost required to pair
        // all odd vertices.

        int extraCost = pairCost(0, odd, dist, dp);

        return totalCost + extraCost;
    }

    public static void Main()
    {
        int n = 4;

        int[][] edges = { new int[] { 1, 2, 2 },
                          new int[] { 2, 3, 3 },
                          new int[] { 3, 1, 1 },
                          new int[] { 3, 4, 2 } };

        Console.WriteLine(minTourCost(n, edges));
    }
}

