{
    const INF = 1e9;

    const dist = Array.from({length : n},
                            () => Array(n).fill(INF));

    const degree = Array(n).fill(0);
    const adj = Array.from({length : n}, () => []);

    let totalCost = 0;

    // Initialize distance from every vertex to itself as
    // zero.

    for (let i = 0; i < n; i++)
        dist[i][i] = 0;

    // Build the graph, calculate degrees, and store the
    // total edge cost.

    for (const edge of edges) {
        const u = edge[0] - 1;
        const v = edge[1] - 1;
        const w = edge[2];

        dist[u][v] = Math.min(dist[u][v], w);
        dist[v][u] = Math.min(dist[v][u], w);

        adj[u].push(v);
        adj[v].push(u);

        degree[u]++;
        degree[v]++;

        totalCost += w;
    }

    // Find a vertex that is incident to at least one edge.

    let start = -1;

    for (let i = 0; i < n; i++) {
        if (degree[i] > 0) {
            start = i;
            break;
        }
    }

    if (start === -1)
        return 0;

    // Check that all vertices with edges belong to the same
    // component.

    const visited = Array(n).fill(false);
    const queue = [ start ];

    visited[start] = true;

    let front = 0;

    while (front < queue.length) {
        const u = queue[front++];

        for (const v of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                queue.push(v);
            }
        }
    }

    for (let i = 0; i < n; i++) {
        if (degree[i] > 0 && !visited[i])
            return -1;
    }

    // Compute the shortest distance between every pair of
    // vertices.

    for (let k = 0; k < n; k++) {
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                if (dist[i][k] < INF && dist[k][j] < INF) {
                    dist[i][j]
                        = Math.min(dist[i][j],
                                   dist[i][k] + dist[k][j]);
                }
            }
        }
    }

    const odd = [];

    // Collect all vertices having odd degree.

    for (let i = 0; i < n; i++) {
        if (degree[i] % 2 === 1)
            odd.push(i);
    }

    const k = odd.length;

    if (k === 0)
        return totalCost;

    const dp = Array(1 << k).fill(-1);

    // Find the minimum additional cost required to pair all
    // odd vertices.

    const extraCost = pairCost(0, odd, dist, dp);

    return totalCost + extraCost;
}

