#include <bits/stdc++.h>
using namespace std;

// Maximum 26 lowercase + 26 uppercase letters
static const int SIZE = 52;

// Trie Node Definition
class TrieNode
{
  public:
    TrieNode *child[SIZE];
    bool leaf;

    TrieNode()
    {
        leaf = false;
        for (int i = 0; i < SIZE; i++)
            child[i] = NULL;
    }
};

// A-Z ? 0-25
// a-z ? 26-51
static int getIndex(char ch)
{

    if (ch >= 'A' && ch <= 'Z')
        return ch - 'A';

    if (ch >= 'a' && ch <= 'z')
        return ch - 'a' + 26;

    return -1;
}

// Insert Word into Trie
static void insert(TrieNode *root, string word)
{

    TrieNode *curr = root;

    for (char ch : word)
    {

        int idx = getIndex(ch);

        if (idx == -1)
            continue;

        if (curr->child[idx] == NULL)
            curr->child[idx] = new TrieNode();

        curr = curr->child[idx];
    }

    curr->leaf = true;
}

// Check valid cell
static bool isSafe(int i, int j, vector<vector<bool>> &vis, int r, int c)
{
    return (i >= 0 && i < r && j >= 0 && j < c && !vis[i][j]);
}

// DFS on board + Trie
static void dfs(TrieNode *node, vector<vector<char>> &board, int i, int j, vector<vector<bool>> &vis,
                string path, vector<string> &res, unordered_set<string> &st, int r, int c)
{

    if (!node)
        return;

    if (node->leaf)
    {
        if (st.find(path) == st.end())
        {
            st.insert(path);
            res.push_back(path);
        }
    }

    vis[i][j] = true;

    int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};
    int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int d = 0; d < 8; d++)
    {

        int ni = i + dx[d];
        int nj = j + dy[d];

        if (isSafe(ni, nj, vis, r, c))
        {

            char ch = board[ni][nj];
            int idx = getIndex(ch);

            // validate idx
            if (idx != -1 && node->child[idx] != NULL)
            {

                dfs(node->child[idx], board, ni, nj, vis, path + ch, res, st, r, c);
            }
        }
    }

    vis[i][j] = false;
}

vector<string> wordBoggle(vector<vector<char>> &board, vector<string> &dictionary)
{

    vector<string> empty;
    if (board.empty() || board[0].empty())
        return empty;

    int r = board.size();
    int c = board[0].size();

    TrieNode *root = new TrieNode();

    // Step 1: Build Trie
    for (string word : dictionary)
        insert(root, word);

    vector<string> res;
    unordered_set<string> st;
    vector<vector<bool>> vis(r, vector<bool>(c, false));

    // Step 2: Start DFS from each cell
    for (int i = 0; i < r; i++)
    {
        for (int j = 0; j < c; j++)
        {

            int idx = getIndex(board[i][j]);

            if (idx != -1 && root->child[idx] != NULL)
            {

                dfs(root->child[idx], board, i, j, vis, string(1, board[i][j]), res, st, r, c);
            }
        }
    }

