        vis[i][j] = true;

        int[] dx = { -1, -1, -1, 0, 0, 1, 1, 1 };
        int[] dy = { -1, 0, 1, -1, 1, -1, 0, 1 };

        for (int d = 0; d < 8; d++) {

            int ni = i + dx[d];
            int nj = j + dy[d];

            if (isSafe(ni, nj, vis, r, c)) {

                char ch = board[ni][nj];
                int idx = getIndex(ch);

                // validate idx
                if (idx != -1 && node.child[idx] != null) {

                    dfs(node.child[idx], board, ni, nj, vis,
                        path + ch, res, st, r, c);
                }
            }
        }

        vis[i][j] = false;
    }

