void dfs(int row, int col, vector<vector<int>> &mat, vector<vector<bool>> &vis, bool &stationP,
         bool &stationQ)
{
    int n = mat.size();
    int m = mat[0].size();

    vis[row][col] = true;

    // Signal reaches Station P
    if (row == 0 || col == 0)
        stationP = true;

    // Signal reaches Station Q
    if (row == n - 1 || col == m - 1)
        stationQ = true;

    int dr[] = {-1, 1, 0, 0};
    int dc[] = {0, 0, -1, 1};

    for (int k = 0; k < 4; k++)
    {
        int newRow = row + dr[k];
        int newCol = col + dc[k];

        if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < m && !vis[newRow][newCol] &&
            mat[newRow][newCol] <= mat[row][col])
        {

            dfs(newRow, newCol, mat, vis, stationP, stationQ);
        }
    }
}

int countCoordinates(vector<vector<int>> &mat)
{

    int n = mat.size();
    int m = mat[0].size();

    int ans = 0;

    // Start DFS from every cell
    for (int i = 0; i < n; i++)
    {
        for (int j = 0; j < m; j++)
        {

            vector<vector<bool>> vis(n, vector<bool>(m, false));

            bool stationP = false;
            bool stationQ = false;

            dfs(i, j, mat, vis, stationP, stationQ);

            if (stationP && stationQ)
                ans++;
        }
    }

    return ans;
}

