using namespace std;

// Determinant using Gaussian elimination
double determinant(vector<vector<double>> mat, int n) {
    double det = 1.0;

    for (int i = 0; i < n; i++) {

        // Find pivot
        int pivot = i;
        for (int j = i + 1; j < n; j++) {
            if (fabs(mat[j][i]) > fabs(mat[pivot][i]))
                pivot = j;
        }

        // If pivot is zero → determinant = 0
        if (fabs(mat[pivot][i]) < 1e-9)
            return 0;

        // Swap rows
        if (i != pivot) {
            swap(mat[i], mat[pivot]);
            det *= -1;
        }

        det *= mat[i][i];

        // Eliminate below
        for (int j = i + 1; j < n; j++) {
            double factor = mat[j][i] / mat[i][i];
            for (int k = i; k < n; k++) {
                mat[j][k] -= factor * mat[i][k];
            }
        }
    }

    return det;
}

// Number of spanning trees
int numOfSpanningTree(vector<vector<int>> &graph, int n) {

    // Laplacian matrix
    vector<vector<double>> L(n, vector<double>(n, 0));

    for (int i = 0; i < n; i++) {
        int degree = 0;

        for (int j = 0; j < n; j++) {
            if (graph[i][j]) {
                degree++;
                if (i != j) L[i][j] = -1;
            }
        }

        L[i][i] = degree;
    }

    // Minor matrix
    vector<vector<double>> minor(n - 1, vector<double>(n - 1));

    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1; j++) {
            minor[i][j] = L[i][j];
        }
    }

    // Determinant
    return (int)round(determinant(minor, n - 1));
}

