            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }

        ArrayList<Integer> ans = articulationPoints(V, adj);

        for (int x : ans) {
            System.out.print(x + " ");
        }
    }
}

