            exist[ch - 'a'] = 1;
        }
    }

    //Build the graph
    for (int i = 0; i + 1 < words.size(); i++) {
         string &a = words[i], &b = words[i + 1];
        int n = a.size(), m = b.size(), ind = 0;

        // Find the first different character between a and b
        while (ind < n && ind < m && a[ind] == b[ind])
            ind++;

        if (ind != n && ind == m)
            return "";

        if (ind < n && ind < m)
            graph[a[ind] - 'a'][b[ind] - 'a'] = 1;
    }

    for (int i = 0; i < 26; i++) {
