                            if (!parent.has(word)) {
                                parent.set(word, []);
                            }

                            parent.get(word).push(original);

                            // If target found
                            if (word === e) {
                                found = true;
                            }
                        }
                    }
                }

                // Restore original character
                chars[i] = org;
            }
        }

        // Mark current level words as globally visited
        for (let word of currLevelVisited) {
            visited.add(word);
        }
    }

    // If no sequence exists
    if (!found) {
        return [];
    }

    // Backtracking DFS
    let path = [];

    // Start from end word
    path.push(e);

    buildPaths(e, s, path, parent, ans);

    return ans;
}

