#include <iostream>
#include <vector>
#include <climits>
using namespace std;

int dfs(int i, int j, int removed, int k, vector<vector<int>> &mat,
        vector<vector<bool>> &vis) {
    int n = mat.size(), m = mat[0].size();

    if (i < 0 || j < 0 || i >= n || j >= m || vis[i][j]) return INT_MAX;

    removed += mat[i][j];
    if (removed > k) return INT_MAX;

    if (i == n - 1 && j == m - 1) return 0;

    vis[i][j] = true;

    int res = INT_MAX;

    res = min(res, dfs(i + 1, j, removed, k, mat, vis));
    res = min(res, dfs(i - 1, j, removed, k, mat, vis));
    res = min(res, dfs(i, j + 1, removed, k, mat, vis));
    res = min(res, dfs(i, j - 1, removed, k, mat, vis));

    vis[i][j] = false;

    return res == INT_MAX ? INT_MAX : res + 1;
}

int shortestPath(int k, vector<vector<int>> &mat) {
    int n = mat.size(), m = mat[0].size();

    vector<vector<bool>> vis(n, vector<bool>(m, false));

    int res = dfs(0, 0, 0, k, mat, vis);

    return res == INT_MAX ? -1 : res;
}

