    int k = 1;
    vector<vector<int>> mat = {{0, 0, 0}, {0, 0, 1}, {0, 1, 0}};
    cout << shortestPath(k, mat) << endl;

    k = 0;
    mat = {{0, 1}, {1, 0}};
    cout << shortestPath(k, mat) << endl;

    return 0;
}

