using namespace std;

int shortestPath(int k, vector<vector<int>> &mat) {
    int n = mat.size();
    int m = mat[0].size();

    queue<vector<int>> q;
    vector<vector<vector<bool>>> vis(
        n, vector<vector<bool>>(m, vector<bool>(k + 1, false))
    );

    vector<vector<int>> dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    q.push({0, 0, 0});
    vis[0][0][0] = true;

    int steps = 0;

    while (!q.empty()) {
        int sz = q.size();

        while (sz--) {
            vector<int> curr = q.front();
            q.pop();

            int i = curr[0], j = curr[1], removed = curr[2];

            if (i == n - 1 && j == m - 1) {
                return steps;
            }

            for (auto &dir : dirs) {
                int x = i + dir[0];
                int y = j + dir[1];

                if (x < 0 || y < 0 || x >= n || y >= m) {
                    continue;
                }

                int newRemoved = removed + mat[x][y];

                if (newRemoved > k || vis[x][y][newRemoved]) {
                    continue;
                }

                vis[x][y][newRemoved] = true;
                q.push({x, y, newRemoved});
            }
        }

        steps++;
    }

    return -1;
}

