class GFG {
    static int shortestPath(int k, int[][] mat) {
        int n = mat.length;
        int m = mat[0].length;

        Queue<int[]> q = new LinkedList<>();
        boolean[][][] vis = new boolean[n][m][k + 1];

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        q.offer(new int[] {0, 0, 0});
        vis[0][0][0] = true;

        int steps = 0;

        while (!q.isEmpty()) {
            int sz = q.size();

            while (sz-- > 0) {
                int[] curr = q.poll();

                int i = curr[0], j = curr[1], removed = curr[2];

                if (i == n - 1 && j == m - 1) {
                    return steps;
                }

                for (int[] dir : dirs) {
