class PriorityQueue {
    constructor() {
        this.heap = [];
    }

    enqueue(element, priority) {
        this.heap.push({ element, priority });

        let i = this.heap.length - 1;

        while (i > 0) {
            let parent = Math.floor((i - 1) / 2);

            if (this.heap[parent].priority <= this.heap[i].priority)
                break;

            [this.heap[parent], this.heap[i]] =
                [this.heap[i], this.heap[parent]];

            i = parent;
        }
    }

    dequeue() {
        let root = this.heap[0];
        let last = this.heap.pop();

        if (this.heap.length > 0) {
            this.heap[0] = last;
            let i = 0;

            while (true) {
                let left = 2 * i + 1;
                let right = 2 * i + 2;
                let smallest = i;

                if (left < this.heap.length &&
                    this.heap[left].priority < this.heap[smallest].priority)
                    smallest = left;

                if (right < this.heap.length &&
                    this.heap[right].priority < this.heap[smallest].priority)
                    smallest = right;

                if (smallest === i)
                    break;

                [this.heap[i], this.heap[smallest]] =
                    [this.heap[smallest], this.heap[i]];

                i = smallest;
            }
        }

        return root.element;
    }

    isEmpty() {
        return this.heap.length === 0;
    }
}

function activitySelection(start, finish) {
    let n = start.length;
    let ans = 0;

    // Min Heap to store activities in ascending order
    // of finish time
    let p = new PriorityQueue();

    for (let i = 0; i < n; i++) {
        p.enqueue(
            { finish: finish[i], start: start[i] },
            finish[i]
        );
    }

    // To store the end time of the last selected activity
    let finishtime = -1;

    while (!p.isEmpty()) {
        let activity = p.dequeue();

        if (activity.start > finishtime) {
            finishtime = activity.finish;
            ans++;
        }
    }

    return ans;
}

