                if (arr[j][0] <= end) {
                    end = Math.max(end, arr[j][1]);
                }
            }

            ArrayList<Integer> interval = new ArrayList<>();
            interval.add(start);
            interval.add(end);
            res.add(interval);
        }
        return res;
    }

