#include <iostream>
#include <vector>
using namespace std;

int minPlatform(vector<int> &arr, vector<int>& dep) {
    int n = arr.size();
    int res = 0;

    // Find the max Departure time
    int maxDep = dep[0];
    for (int i = 1; i < n; i++) {
        maxDep = max(maxDep, dep[i]);
    }
    vector<int> v(maxDep + 2, 0);

    // Increment the count at the arrival time and decrement
    // at the departure time
