    vector<vector<int>> res(2);

    // to store the sum of both groups
    int sum1 = 0, sum2 = 0;

    // find half of sum of elements from 1 to n
    int half = n * (n + 1) / 4;

    for(int i = n; i >= 1; i--) {

        // if adding the current element to first
        // group doesn't exceed half, add it
        if(sum1 + i <= half) {
            res[0].push_back(i);
            sum1 += i;
