#include <bits/stdc++.h>
using namespace std;

// Generate a unique key for the current remSq state.
long long getKey(vector<int> &remSq, int b)
{
    long long key = 0;
    long long base = 1;

    for (int i = 0; i < b; i++)
    {
        key += (long long)remSq[i] * base;
        base *= (b + 1);
    }

    return key;
}

// Recursive function to find the minimum number of
// squares required for the current remaining shape.
int minCutUtil(vector<int> &remSq, int a, int b, map<long long, int> &memo)
{
    int start = 0;
    int maxRemSq = 0;

    // Find the first column having the maximum
    // remaining height.
    for (int i = 0; i < b; i++)
    {
        if (remSq[i] > maxRemSq)
        {
            maxRemSq = remSq[i];
            start = i;
        }
    }

    // If all columns have remaining height 0,
    // the entire paper has been covered.
    if (maxRemSq == 0)
        return 0;

    // Generate a key for the current state.
    long long key = getKey(remSq, b);

    // If this state has already been solved,
    // return the stored answer.
    if (memo.find(key) != memo.end())
        return memo[key];

    int ans = INT_MAX;

    // Copy the current state so that we can
    // try different square sizes.
    vector<int> newRemSq = remSq;

    // Try placing squares of different sizes.
    for (int end = start; end < b; end++)
    {
        // The side of the square is equal to
        // the number of columns from start to end.
        int squareEdge = end - start + 1;

        // All columns covered by the square must have
        // the same maximum remaining height.
        if (newRemSq[end] != maxRemSq)
            break;

        // The square must fit within the remaining height.
        if (maxRemSq - squareEdge < 0)
            break;

        // Place the square by reducing the remaining
        // height of all covered columns.
        for (int i = start; i <= end; i++)
        {
            newRemSq[i] = maxRemSq - squareEdge;
        }

        // Count this square and recursively solve
        // the remaining part of the paper.
        ans = min(ans, 1 + minCutUtil(newRemSq, a, b, memo));

        // Restore the state before trying the next
        // possible square size.
        newRemSq = remSq;
    }

    // Store the answer for the current state.
    return memo[key] = ans;
}

// Returns the minimum number of squares required
// to divide a paper of size a x b.
int minCut(int a, int b)
{
    // If the paper is already a square,
    // only one square is required.
    if (a == b)
        return 1;

    // Initially, every column has the full height a.
    vector<int> remSq(b, a);

    // Stores the answer for each previously visited state.
    map<long long, int> memo;

    return minCutUtil(remSq, a, b, memo);
}

int main()
{
    int a = 5;
    int b = 8;

    cout << minCut(a, b) << endl;

    return 0;
}

