    vector<int> sum;

    for(int i = 0; i < n / 2; i++) {

        // group the elements and find sum
        int s = arr[i] + arr[n - i - 1];
        sum.push_back(s);
    }

    // to store the highest and lowest sum
    int high = INT_MIN, low = INT_MAX;

    for(int i = 0; i < sum.size(); i++) {
        high = max(high, sum[i]);
        low = min(low, sum[i]);
    }

    return high - low;
}

