            let start = Math.max(0, i - k);
            let end = Math.min(n - 1, i + k);

            // Search for an uncaught thief within range
            for (let j = start; j <= end; j++) {
                if (arr[j] === 'T' && !caught[j]) {
                    caught[j] = true;
                    count++;
                    break;
                }
            }
        }
    }
