// Queue implementation using front pointer (O(1) enqueue & dequeue)
class Queue {
    constructor() {
        this.arr = [];
        this.front = 0;
    }

    enqueue(x) {
        this.arr.push(x); // O(1)
    }

    dequeue() {
        if (this.isEmpty()) return null;
        return this.arr[this.front++]; // O(1)
    }

    peek() {
        return this.isEmpty() ? null : this.arr[this.front];
    }

    isEmpty() {
        return this.front >= this.arr.length;
    }
}

