int assignHole(int mices[], int holes[],
            int n)
{

    // Sort the arrays
    for(int i=0;i<n;i++){
        for(int j=i+1;j<n;j++){
            if(mices[i]>mices[j]){
                int temp=mices[i];
                mices[i]=mices[j];
                mices[j]=temp;
            }
        }
    }

    for(int i=0;i<n;i++){
        for(int j=i+1;j<n;j++){
            if(holes[i]>holes[j]){
                int temp=holes[i];
                holes[i]=holes[j];
                holes[j]=temp;
            }
