        if (neg % 2 === 1) {
            return prod;
        }

        // Even number of negatives => remove one negative with smallest abs value
        return Math.floor(prod / (-mnNegAbs));
    }

    // No negative numbers
    if (zero > 0) {
        return 0;
    }

    // Only positive numbers
    return mnPos;
}

