#include <algorithm>
#include <cstdlib>
using namespace std;

int maximizeSum(vector<int>& arr, int k) {
    sort(arr.begin(), arr.end());

    // Negate negative elements while operations are available.
    for (int i = 0; i < arr.size() && k > 0; i++) {
        if (arr[i] < 0) {
            arr[i] = -arr[i];
            k--;
        }
    }

    int sum = 0;
    int minValue = abs(arr[0]);

    // Calculate the sum and minimum absolute value.
    for (int value : arr) {
        sum += value;
        minValue = min(minValue, abs(value));
    }

    // Negate the minimum absolute value if one odd operation remains.
    if (k % 2 == 1) {
        sum -= 2 * minValue;
    }

    return sum;
}

