int solve(int a[], int b[], int used[], int idx, int n) {

    // All elements paired
    if (idx == n)
        return 0;

    int res = INT_MAX;

    // Try pairing a[idx] with every unused b[j]
    for (int j = 0; j < n; j++) {
        if (!used[j]) {
            used[j] = 1;

            int curr = abs(a[idx] - b[j]) +
                       solve(a, b, used, idx + 1, n);

            res = res < curr? res : curr;

            used[j] = 0;
        }
    }

    return res;
}

