#include <bits/stdc++.h>
using namespace std;

int solve(int idx, int prev, vector<int> &arr)
{
    // Base Case
    if (idx == arr.size())
        return 0;

    int ans = INT_MAX;

    // Current value can be anything from 0 to prev

    for (int val = 0; val <= prev; val++)
    {
        // Cost to convert arr[idx] -> val
        int cost = abs(arr[idx] - val);

        // Recursive call
        cost += solve(idx + 1, val, arr);

        ans = min(ans, cost);
    }

    return ans;
}

