#include <iostream>
using namespace std;

bool isSubset(vector<int>& a, vector<int>& b) {
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    int i = 0, j = 0;
    int m = a.size(), n = b.size();

    while (i < m && j < n) {
        if (a[i] < b[j]) {
            // move in a to catch up
            i++;
        }
        else if (a[i] == b[j]) {
            i++;
            // matched one element from b
            j++;
        }
        else {
            // a[i] > b[j] → means b[j] is missing
            return false;
        }
    }

    // all b[] matched
    return (j == n);
}

