        int m = high - low + 1;

        // Mark the numbers present in the range
        bool[] present = new bool[m];

        foreach(int x in arr)
        {
            if (x >= low && x <= high)
                present[x - low] = true;
        }

        List<int> res = new List<int>();

        // Collect all missing numbers
        for (int i = 0; i < m; i++) {
            if (!present[i])
                res.Add(low + i);
        }

        return res;
    }

    static void Main()
    {
        int[] arr = { 1, 4, 11, 51, 15 };
        int low = 50, high = 55;

        List<int> res = missingRange(arr, low, high);

        Console.Write("[");

        for (int i = 0; i < res.Count; i++) {
            Console.Write(res[i]);
            if (i != res.Count - 1)
                Console.Write(", ");
        }

        Console.Write("]");
    }
}

