int countDistinct(vector<int> &arr)
{

    int n = arr.size();

    if (n == 0)
    {
        return 0;
    }

    // Stores count of distinct elements
    int res = 1;

    // Pick all elements one by one
    for (int i = 1; i < n; i++)
    {

        int j;

        // Check whether current element
        // appeared before or not
        for (j = 0; j < i; j++)
        {
            if (arr[i] == arr[j])
            {
                break;
            }
        }

        // If current element is seen
        // for the first time
        if (i == j)
        {
            res++;
        }
    }

    return res;
}

