    int cnt = 0;

    for (int i = 0; i < n; i++) {

        // Check if the complement (arr[i] + k)
        // exists in the map. If yes, increment count
        if (freq.find(arr[i] + k) != freq.end())
            cnt += freq[arr[i] + k];

        // Check if the complement (arr[i] - k)
        // exists in the map. If yes, increment count
        if (freq.find(arr[i] - k) != freq.end())
            cnt += freq[arr[i] - k];

        // Increment the frequency of arr[i]
        freq[arr[i]]++;
    }
    return cnt;
}

