    int countGreaterThanK = 0;
    for (int y : arr) {
        if (y > k) countGreaterThanK++;
    }

    for (int x : arr) {
        if (x < k) continue;

        int r = x - k;
        if (r == 0) {

            // x equals k: every other value greater than k forms a valid pair
            total += countGreaterThanK;
            continue;
