#include <algorithm>
#include <iostream>
#include <unordered_map>
#include <vector>
using namespace std;

// Returns top k frequent elements after each insertion
vector<vector<int>> kTop(int k, vector<int> &arr)
{

    // vector of size k+1 to maintain top k elements
    vector<int> top(k + 1);

    // store the result after each insertion
    vector<vector<int>> res;

    // hashmap to store frequency of each element
    unordered_map<int, int> freq;

    // traverse the array from left to right
    for (int m = 0; m < arr.size(); m++)
    {

        // temporary vector to store current top elements
        vector<int> temp;

        // increase the frequency of current element
        freq[arr[m]]++;

        // insert current element at the last position
        top[k] = arr[m];

        // find position of current element
        auto it = find(top.begin(), top.end() - 1, arr[m]);

        // move element to correct position based on frequency
        for (int i = distance(top.begin(), it) - 1; i >= 0; --i)
        {

            // swap if the next element has higher frequency
            if (freq[top[i]] < freq[top[i + 1]])
                swap(top[i], top[i + 1]);

            // if frequencies are same, smaller element comes first
            else if (freq[top[i]] == freq[top[i + 1]] && top[i] > top[i + 1])
                swap(top[i], top[i + 1]);

            // stop if the current order is correct
            else
                break;
        }

        // collect top k elements
        for (int i = 0; i < k && top[i] != 0; ++i)
            temp.push_back(top[i]);

        // store the current result
        res.push_back(temp);
    }

    // return the result
    return res;
}

int main()
{
    int k = 3;
    vector<int> arr = {2, 1, 2, 1, 2, 1};

    vector<vector<int>> result = kTop(k, arr);

    for (auto &row : result)
    {
        cout << "[";
        for (int i = 0; i < row.size(); i++)
        {
            cout << row[i];
            if (i + 1 < row.size())
                cout << ", ";
        }
        cout << "] ";
    }

    return 0;
}

