            // stop if the current order is correct
            else {
                break;
            }
        }

        // collect top k elements
        for (let i = 0; i < k && top[i] !== null; ++i)
            temp.push(top[i]);

        // store the current result
        res.push(temp);
    }

    // return the result
    return res;
}

