        while (i >= 0 && s1[i] != s2[j]) {

            // Increment the number of operations required
            res++;

            // Move pointer i to the left to find a match for s2[j]
            i--;
        }

        // Move both pointers if a match is found or i is exhausted
        i--;
        j--;
    }

    return res;
}

