bool canPairs(vector<int>& arr, int k) {

    int n = arr.size();

    if (n % 2 == 1)
        return false;

    int count = 0;

    vector<int> vis(n, -1);

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {

            // If pair is divisible increment the
            // count and mark elements as visited
            if ((arr[i] + arr[j]) % k == 0 &&
                vis[i] == -1 && vis[j] == -1) {

                count++;
                vis[i] = 1;
                vis[j] = 1;
            }
        }
    }

    return (count == n / 2);
}

