    vector<vector<int>>& queries) {

    // to store the results
    vector<int> result;
    for (auto query : queries) {
        int start = query[0];
        int end = query[1];

        // check if the substring is a palindrome
        if (isPalindrome(s, start, end)) {
            result.push_back(1);
        } else {
            result.push_back(0);
        }
    }
    return result;
}

