                preHash[i + 1][0] =
                    add(multiply(preHash[i][0], base1), input.charAt(i));
                preHash[i + 1][1] =
                    add(multiply(preHash[i][1], base2), input.charAt(i));

                power[i + 1][0] = multiply(power[i][0], base1);
                power[i + 1][1] = multiply(power[i][1], base2);
