#include <iostream>
#include <vector>
#include <string>
using namespace std;

class Manacher {
public:
    vector<int> p;
    string ms;

    Manacher(string &s) {

        // build modified string with sentinels and separators
        ms = "@";
        for (char c : s) ms += "#" + string(1, c);
        ms += "#$";
        runManacher();
    }

    void runManacher() {
        int n = ms.size();
        p.assign(n, 0);

        int left = 0, right = 0;

        for (int i = 1; i < n - 1; ++i) {
            int mirror = left + right - i;

            // initialize radius using mirror or boundary
            if (i < right) p[i] = min(right - i, p[mirror]);

            // expand around i
            while (ms[i + p[i] + 1] == ms[i - p[i] - 1])
                ++p[i];

            // update left and right bounds
            if (i + p[i] > right) {
                left = i - p[i];
                right = i + p[i];
            }
        }
    }

    bool isPalindrome(int l, int r) {

        // compute the center index
        // in modified string
        int mid = l + r + 2;
        int len = r - l + 1;

        // check if radius covers the length
        return p[mid] >= len;
    }
};

vector<int> palQueries(string &s,
        vector<vector<int>> &queries){

    Manacher M(s);

    vector<int> res;

    for (auto& query : queries) {
        int l = query[0], r = query[1];
        res.push_back(M.isPalindrome(l, r));
    }

    return res;
}

int main() {

    string str = "abaaabaaaba";
    vector<vector<int>> queries =
            {{0, 10}, {5, 8}, {2, 5}, {5, 9}};
    vector<int> res = palQueries(str, queries);

    for (auto i : res) {
        cout << i << " ";
    }
    return 0;
}

