        // expand around i
        while (ms[i + p[i] + 1] === ms[i - p[i] - 1])
                p[i]++;

        // update left and right bounds
        if (i + p[i] > right) {
            left = i - p[i];
            right = i + p[i];
        }
    }
    return p;
}

