{
    int n = a.size();
    int m = b.size();

    // Arrays with different sizes cannot be equal.
    if (n!= m)
        return false;

    // Sort both arrays so that equal elements
    // appear at the same positions.
    sort(a.begin(), a.end());
    sort(b.begin(), b.end());

    // Compare elements at each position.
    for (int i = 0; i < n; i++)
    {
        if (a[i]!= b[i])
            return false;
    }

    // All elements and their frequencies are equal.
    return true;
}

