#include <stdlib.h>

// function to find the maximum distance
int maxDistance(int arr[], int n) {
    int res = 0;
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {

            // check if two elements are equal
            if (arr[i] == arr[j]) {

              // calculate the distance and update res
                res = (res > (j - i)) ? res : (j - i);
            }
        }
    }
    return res;
}

