            if (a[i] == b[j]) {
                for (int k = 0; k < *res_size; k++) {
                    if (res[k] == a[i]) {
                        found = 1;
                        break;
                    }
                }
                if (!found) {
                    res[(*res_size)++] = a[i];
                }
            }
        }
    }
