        st.add(a);
        st.add(b);
        while (b < max) {
            int c = a + b;
            a = b;
            b = c;
            st.add(b);
        }

        // Find all numbers in arr[] that are Fibonacci numbers
        ArrayList<Integer> res = new ArrayList<>();
        for (int num : arr) {
            if (st.contains(num)) {
                res.add(num);
            }
        }

        return res;
    }

