    let a = 0, b = 1, c = 0;
    while (c <= mx) {
        c = a + b;
        st.add(c);
        a = b;
        b = c;
    }

    // Check the array elements for Fibonacci number
    const res = [];
    for (let i = 0; i < arr.length; i++) {
        if (st.has(arr[i])) {
            res.push(arr[i]);
        }
    }

    return res;
}

