// in Recaman's sequence using
// BruteForce Approach
#include <bits/stdc++.h>
using namespace std;

// Function to generate Recaman's sequence
vector<int> recamanSequence(int n) {
    vector<int> res(n);
    res[0] = 0;

    // Generate the sequence
    for (int i = 1; i < n; i++) {

        // Calculate previous term - index
        int curr = res[i - 1] - i;

        // Check if curr is valid and
        // not in sequence
        bool exists = false;
        for (int j = 0; j < i; j++) {
            if (res[j] == curr) {
                exists = true;
                break;
            }
        }

        // If curr is invalid, use
        // previous term + index
        if (curr < 0 || exists) {
            curr = res[i - 1] + i;
        }

        res[i] = curr;
    }

    return res;
}

int main() {
    int n = 6;
    vector<int> res = recamanSequence(n);

    for (int x : res) {
        cout << x << " ";
    }

    return 0;
}

