        let curr = res[i - 1] - i;

        // If curr is invalid, use previous term + index
        if (curr < 0 || s.has(curr)) {
            curr = res[i - 1] + i;
        }

        res[i] = curr;
        s.add(curr);
    }
    return res;
}

