#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>

// Linked list node
struct Node
{
    int data;
    struct Node *next;
};

// Function to create a new node
struct Node *newNode(int x)
{
    struct Node *node = (struct Node *)malloc(sizeof(struct Node));
    node->data = x;
    node->next = NULL;
    return node;
}

// Recursive function to search for a key in the linked list
bool searchKey(struct Node *head, int key)
{
    // Base case: list is empty
    if (head == NULL)
        return false;

    // If key is found at current node
    if (head->data == key)
        return true;

    // Recur for the rest of the list
    return searchKey(head->next, key);
}

