#include <bits/stdc++.h>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;
    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

Node *deleteNode(Node *head, int x)
{

    vector<Node *> nodes;

    // Store all node pointers
    Node *curr = head;
    while (curr != nullptr)
    {
        nodes.push_back(curr);
        curr = curr->next;
    }

    // Delete the head node
    if (x == 1)
    {
        Node *temp = head;
        head = head->next;
        delete temp;
        return head;
    }

    Node *prev = nodes[x - 2];
    Node *delNode = nodes[x - 1];

    // Remove the node
    prev->next = delNode->next;
    delete delNode;

    return head;
}

// Function to print the linked list
void printList(Node *head)
{
    while (head != nullptr)
    {
        cout << head->data;
        if (head->next)
            cout << " -> ";
        head = head->next;
    }
    cout << endl;
}

