int getKthFromLast(Node *head, int k)
{

    // Count the total number of nodes
    int cnt = 0;
    Node *curr = head;

    while (curr != nullptr)
    {
        cnt++;
        curr = curr->next;
    }

    // If k is greater than the list size
    if (k > cnt)
        return -1;

    // Move to the (cnt - k)th node
    curr = head;
    for (int i = 0; i < cnt - k; i++)
        curr = curr->next;

    return curr->data;
}

