#include <iostream>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;

    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

Node *deleteK(Node *head, int K)
{
    // If the list is empty, return the head.
    if (head == nullptr)
        return head;

    Node *temp = head;
    Node *prev = nullptr;

    // Move to the K-th node.
    for (int i = 1; i < K && temp != nullptr; i++)
    {
        prev = temp;
        temp = temp->next;
    }

    // If fewer than K nodes remain, return the list.
    if (temp == nullptr)
        return head;

    // Delete the K-th node.
    if (prev == nullptr)
    {
        head = temp->next;
    }
    else
    {
        prev->next = temp->next;
    }

    // Store the next node before deleting.
    Node *nextNode = temp->next;

    // Free memory.
    delete temp;

    // Recursively process the remaining list.
    if (prev == nullptr)
        return deleteK(nextNode, K);

    prev->next = deleteK(nextNode, K);

    return head;
}

void printList(Node *head)
{
    // Traverse and print the linked list.
    while (head != nullptr)
    {
        cout << head->data;

        if (head->next != nullptr)
            cout << " -> ";

        head = head->next;
    }

    cout << endl;
