    // Input case :
    string homepage;
    homepage = "gfg.org";

    // Initialise the object of Browser History
    BrowserHistory obj(homepage);

    string url = "google.com";
    obj.visit(url);

    url = "facebook.com";
    obj.visit(url);

    url = "youtube.com";
    obj.visit(url);

