#include <iostream>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;

    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

// Function to remove duplicate nodes.
Node *removeDuplicates(Node *head)
{

    // Return if the list is empty.
    if (head == nullptr)
        return head;

    Node *prev = head;
    Node *curr = head->next;

    // Traverse the linked list.
    while (curr != nullptr)
    {

        bool duplicate = false;

        // Check all previous nodes.
        Node *temp = head;
        while (temp != curr)
        {
            if (temp->data == curr->data)
            {
                duplicate = true;
                break;
            }
