#include <bits/stdc++.h>
using namespace std;

class Node
{
  public:
    int data;
    Node *next, *prev;

    Node(int val)
    {
        data = val;
        next = prev = nullptr;
    }
};

// Function to find all pairs with given sum
vector<vector<int>> givenSumPairs(Node *head, int target)
{

    vector<vector<int>> res;

    // Check every possible pair
    for (Node *first = head; first != nullptr; first = first->next)
    {

        for (Node *second = first->next; second != nullptr; second = second->next)
        {

            // Pair found
            if (first->data + second->data == target)
                res.push_back({first->data, second->data});
        }
    }

    return res;
}

// Insert node at end
Node *insert(Node *head, int val)
{

    Node *newNode = new Node(val);

    if (!head)
        return newNode;

    Node *curr = head;

    while (curr->next)
        curr = curr->next;

    curr->next = newNode;
    newNode->prev = curr;

    return head;
}

int main()
{

    vector<int> arr = {1, 2, 4, 5, 6, 8, 9};

    Node *head = nullptr;

    for (int x : arr)
        head = insert(head, x);

    int target = 7;

    vector<vector<int>> ans = givenSumPairs(head, target);

    cout << "[";

    for (int i = 0; i < ans.size(); i++)
    {
        cout << "[" << ans[i][0] << ", " << ans[i][1] << "]";
        if (i + 1 != ans.size())
            cout << ", ";
    }

    cout << "]";

    return 0;
}

