    public static Node insert(Node head, int val)
    {
        Node newNode = new Node(val);

        if (head == null)
            return newNode;

        Node curr = head;

        while (curr.next != null)
            curr = curr.next;

        curr.next = newNode;
        newNode.prev = curr;

        return head;
    }

