    {
        data = val;
        next = prev = null;
    }
}

public class GFG {
    // Function to find all pairs with given sum
    public List<List<int> > givenSumPairs(Node head,
                                          int target)
    {
        List<List<int> > res = new List<List<int> >();

        if (head == null)
            return res;

        Node left = head;
        Node right = head;

        // Move right to the last node
        while (right.next != null)
            right = right.next;

        // Find pairs
        while (left != right && right.next != left) {
            int sum = left.data + right.data;

            if (sum == target) {
                List<int> pair = new List<int>();
                pair.Add(left.data);
                pair.Add(right.data);
                res.Add(pair);

                left = left.next;
                right = right.prev;
            }
            else if (sum < target) {
                left = left.next;
            }
            else {
                right = right.prev;
            }
        }

        return res;
    }

    // Insert node at end
    public static Node insert(Node head, int val)
    {
        Node newNode = new Node(val);

        if (head == null)
            return newNode;

        Node curr = head;

        while (curr.next != null)
            curr = curr.next;

        curr.next = newNode;
        newNode.prev = curr;

        return head;
    }

