{
  public:
    int data;
    Node *next;
    Node(int new_data)
    {
        data = new_data;
        next = nullptr;
    }
};

Node *rotate(Node *head, int k)
{
    if (k == 0 || head == nullptr)
        return head;

    // rotate the list by k nodes
    for (int i = 0; i < k; ++i)
    {
        Node *curr = head;
        while (curr->next != nullptr)
            curr = curr->next;

        // move the first node to the last
        curr->next = head;
        curr = curr->next;
        head = head->next;
        curr->next = nullptr;
    }
    return head;
}

