using System.Collections.Generic;

class Node {
    public int Data;
    public Node Next, Random;

    public Node(int x) {
        Data = x;
        Next = Random = null;
    }
}

class GfG {
    static Node cloneLinkedList(Node head) {
        if (head == null)
            return null;

        // Create new nodes and insert them next to
        // the original nodes
        Node curr = head;
        while (curr != null) {
            Node newNode = new Node(curr.Data);
            newNode.Next = curr.Next;
            curr.Next = newNode;
            curr = newNode.Next;
        }

        // Set the random pointers of the new nodes
        curr = head;
        while (curr != null) {
            if (curr.Random != null)
                curr.Next.Random = curr.Random.Next;
            curr = curr.Next.Next;
        }

        // Separate the new nodes from the original nodes
        curr = head;
        Node clonedHead = head.Next;
        Node clone = clonedHead;
        while (clone.Next != null) {

            // Update the next nodes of original node
            // and cloned node
            curr.Next = curr.Next.Next;
            clone.Next = clone.Next.Next;

            // Move pointers of original as well as
            // cloned linked list to their next nodes
            curr = curr.Next;
            clone = clone.Next;
        }
        curr.Next = null;
        clone.Next = null;

        return clonedHead;
    }

    static void printList(Node head) {
        while (head != null) {
            Console.Write(head.Data + "(");
            if (head.Random != null)
                Console.Write(head.Random.Data + ")");
            else
                Console.Write("null)");

            if (head.Next != null)
                Console.Write(" -> ");
            head = head.Next;
        }
        Console.WriteLine();
    }

    public static void Main() {

        // Creating a linked list with random pointer
        Node head = new Node(1);
        head.Next = new Node(2);
        head.Next.Next = new Node(3);
        head.Next.Next.Next = new Node(4);
        head.Next.Next.Next.Next = new Node(5);
        head.Random = head.Next.Next;
        head.Next.Random = head;
        head.Next.Next.Random = head.Next.Next.Next.Next;
        head.Next.Next.Next.Random = head.Next.Next;
        head.Next.Next.Next.Next.Random = head.Next;

        // Print the original list
        Console.WriteLine("Original linked list:");
        printList(head);

        Node clonedList = cloneLinkedList(head);

        Console.WriteLine("Cloned linked list:");
        printList(clonedList);
    }
}

