#include <iostream>

using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// Recursively links nodes of the tree in inorder fashion
void inorder(Node* root) {

    // if left subtree exists
    if (root->left) {

        // find the inorder predecessor of root node
        Node* pred = root->left;
        while (pred->right) {
            pred = pred->right;
        }

        // process the left subtree
        inorder(root->left);

        // link the predecessor and root node
        pred->right = root;
        root->left = pred;
    }

    // if right subtree exists
    if (root->right) {

        // find the inorder successor of root node
        Node* succ = root->right;
        while (succ->left) {
            succ = succ->left;
        }

        // process the right subtree
        inorder(root->right);

        // link the successor and root node
        root->right = succ;
        succ->left = root;
    }
}

// function to convert binary tree to doubly linked list
Node* treeToDLL(Node* root) {

    // return if root is null
    if (root == nullptr) return root;

    // find the head of dll
    Node* head = root;
    while (head->left != nullptr)
        head = head->left;

    // recursively convert the tree into dll
    inorder(root);

    return head;
}

void printList(Node* head) {

    // return if list is empty
    if (head == nullptr) return;

    Node* curr = head;

    // print the list in forward direction
    while (curr->right != nullptr) {
        cout << curr->data << " ";
        curr = curr->right;
    }

    // curr is now at the tail, print the last node
    cout << curr->data << endl;

    // print the list in backward direction
    while (curr != nullptr) {
        cout << curr->data << " ";
        curr = curr->left;
    }
    cout << endl;
}

int main() {

    Node* root = new Node(1);
    root->left = new Node(2);
    root->right = new Node(3);

    Node* head = treeToDLL(root);

    printList(head);

    return 0;
}

