#include <iostream>

using namespace std;

class Node {
public:
    int data;
    Node* left;
    Node* right;

    Node(int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// function to convert binary tree to doubly linked list using morris traversal
Node* treeToDLL(Node* root) {

    // return if root is null
    if (root == nullptr) return root;

    // head and tail node for the dll
    Node* head = nullptr;
    Node* tail = nullptr;

    Node* curr = root;

    while (curr != nullptr) {

        // if left subtree does not exist,
        // link curr into the dll and move to curr.right
        if (curr->left == nullptr) {
            if (head == nullptr) {
                head = tail = curr;
            } else {
                tail->right = curr;
                curr->left = tail;
                tail = curr;
            }
            curr = curr->right;
        } else {
            Node* pred = curr->left;

            // find the inorder predecessor of curr
            while (pred->right != nullptr && pred->right != curr) {
                pred = pred->right;
            }

            // create a thread from pred to curr
            if (pred->right == nullptr) {
                pred->right = curr;
                curr = curr->left;
            } else {

                // left subtree processed, remove the thread,
                // link curr into the dll and move to curr.right
                pred->right = nullptr;
                tail->right = curr;
                curr->left = tail;
                tail = curr;

                curr = curr->right;
            }
        }
    }

    return head;
}

