using System;

class Node {
    public int data;
    public Node left, right;

    public Node(int x) {
        data = x;
        left = null;
        right = null;
    }
}

class GfG {

    // function to convert binary tree to doubly linked list using morris traversal
    static Node treeToDLL(Node root) {

        // return if root is null
        if (root == null) return root;

        // head and tail node for the dll
        Node head = null;
        Node tail = null;

        Node curr = root;

        while (curr != null) {

            // if left subtree does not exist,
            // link curr into the dll and move to curr.right
            if (curr.left == null) {
                if (head == null) {
                    head = tail = curr;
                } else {
                    tail.right = curr;
                    curr.left = tail;
                    tail = curr;
                }
                curr = curr.right;
            } else {
                Node pred = curr.left;

                // find the inorder predecessor of curr
                while (pred.right != null && pred.right != curr) {
                    pred = pred.right;
                }

                // create a thread from pred to curr
                if (pred.right == null) {
                    pred.right = curr;
                    curr = curr.left;
                } else {

                    // left subtree processed, remove the thread,
                    // link curr into the dll and move to curr.right
                    pred.right = null;
                    tail.right = curr;
                    curr.left = tail;
                    tail = curr;

                    curr = curr.right;
                }
            }
        }

        return head;
    }

