    m, n = len(text), len(pattern)

    lps = constructLps(pattern)

    i, j = 0, 0
    while i < m:
        if text[i] == pattern[j]:
            i += 1
            j += 1

        # If end of pattern is reached
        if j == n:
            return True
        if i < m and text[i] != pattern[j]:
            if j != 0:
                j = lps[j - 1]
