    myQueue q;

    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);

    cout << "Front: " << q.front() << "\n";
    cout << "Size: " << q.size() << "\n";

    q.dequeue();
    cout << "Front: " << q.front() << "\n";
    cout << "Size: " << q.size() << "\n";

    return 0;
}

