// Node class for doubly linked list
class Node {
    constructor(data) {
        this.data = data;
        this.prev = null;
        this.next = null;
    }
}

// Queue implemented using doubly linked list
class Queue {
    constructor() {
        this.front = null;
        this.rear = null;
        this.size = 0;
    }

    // Add element at the rear
    enqueue(x) {
        let node = new Node(x);
        if (!this.rear) {
            this.front = this.rear = node;
        } else {
            node.prev = this.rear;
            this.rear.next = node;
            this.rear = node;
        }
        this.size++;
    }

    // Remove element from the front
    dequeue() {
        if (!this.front) {
            console.log("Queue is empty");
            return null;
        }
        let val = this.front.data;
        this.front = this.front.next;
        if (this.front) this.front.prev = null;
        else this.rear = null;
        this.size--;
        return val;
    }

    // Get front element without removing
    frontElement() {
        return this.front ? this.front.data : null;
    }

    isEmpty() {
        return this.size === 0;
    }
}

// Function to find first non-repeating character in a stream
function firstNonRepeating(s) {
    let ans = "";
    let count = new Array(26).fill(0);
    let q = new Queue();

    for (let i = 0; i < s.length; i++) {
        let idx = s.charCodeAt(i) - 'a'.charCodeAt(0);

        // if first occurrence, enqueue it
        if (count[idx] === 0) {
            q.enqueue(s[i]);
        }
        count[idx]++;

        // remove repeating elements from front
        while (!q.isEmpty() &&
            count[q.frontElement().charCodeAt(0) - 'a'.charCodeAt(0)] > 1) {
            q.dequeue();
        }

        // append first non-repeating or '#' if none
        ans += q.isEmpty() ? '#' : q.frontElement();
    }

    return ans;
}

