class MaxHeap {
    constructor() {
        this.heap = [];
    }

    isEmpty() {
        return this.heap.length === 0;
    }

    // Compare two nodes (larger value first)
    compare(a, b) {
        if (a.value !== b.value)
            return a.value > b.value;

        return a.index > b.index;
    }

    push(node) {
        this.heap.push(node);
        this.heapifyUp(this.heap.length - 1);
    }

    pop() {
        if (this.heap.length === 1)
            return this.heap.pop();

        const root = this.heap[0];
        this.heap[0] = this.heap.pop();
        this.heapifyDown(0);

        return root;
    }

    top() {
        return this.heap[0];
    }

    heapifyUp(index) {
        while (index > 0) {
            let parent = Math.floor((index - 1) / 2);

            if (this.compare(this.heap[parent], this.heap[index]))
                break;

            [this.heap[parent], this.heap[index]] =
                [this.heap[index], this.heap[parent]];

            index = parent;
        }
    }

    heapifyDown(index) {
        let size = this.heap.length;

        while (true) {
            let largest = index;
            let left = 2 * index + 1;
            let right = 2 * index + 2;

            if (left < size &&
                this.compare(this.heap[left], this.heap[largest]))
                largest = left;

            if (right < size &&
                this.compare(this.heap[right], this.heap[largest]))
                largest = right;

            if (largest === index)
                break;

            [this.heap[index], this.heap[largest]] =
                [this.heap[largest], this.heap[index]];

            index = largest;
        }
    }
}

function maxOfSubarrays(arr, k) {
    let res = [];
    let heap = new MaxHeap();

    // Insert first k elements
    for (let i = 0; i < k; i++)
        heap.push({ value: arr[i], index: i });

    res.push(heap.top().value);

    // Process remaining elements
    for (let i = k; i < arr.length; i++) {

        heap.push({ value: arr[i], index: i });

        // Remove elements outside the current window
        while (heap.top().index <= i - k)
            heap.pop();

        res.push(heap.top().value);
    }

    return res;
}

