int kBitFlips(vector<int> &arr, int k) {
    int n = arr.size();
    int res = 0;

    for (int i = 0; i < n - k + 1; i++) {
        if (arr[i] == 0) {

            // if arr[i] = 0, flip arr[i...i+k-1]
            for (int j = i; j < (i + k); j++)
                arr[j] = 1 ^ arr[j];

            res += 1;
        }
    }

    // If arr[i] is still 0, then it is impossible
    // to convert all elements to 1
    for (int i = n - k + 1; i < n; i++) {
        if (arr[i] == 0)
            return -1;
    }

    return res;
}

