using System;
using System.Collections.Generic;

class Solution {
    static int FindMax(List<int> arr, int i) {

        // Last index returns the element
        if (i == arr.Count - 1) {
            return arr[i];
        }

        // Find the maximum from the rest of the array
        int recMax = FindMax(arr, i + 1);

        // Compare with i-th element and return
        return Math.Max(recMax, arr[i]);
    }

    public int largest(List<int> arr) {
        return FindMax(arr, 0);
    }

    static void Main(string[] args) {
        List<int> arr = new List<int> { 20, 10, 20, 4, 100 };

        Solution obj = new Solution();
        Console.WriteLine(obj.largest(arr));
    }
}

