#include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> commonElements(vector<int>& a,
                vector<int>& b, vector<int>& c)
{
    unordered_map<int, int> count;

    // Process arr1 (store only unique elements)
    for (int i = 0; i < a.size(); i++) {
        if (i == 0 || a[i] != a[i - 1])
            count[a[i]] = 1;
    }

    // Process arr2
    for (int i = 0; i < b.size(); i++) {
        if (i == 0 || b[i] != b[i - 1]) {
            if (count[b[i]] == 1)
                count[b[i]] = 2;
        }
    }

    // Process arr3
    for (int i = 0; i < c.size(); i++) {
        if (i == 0 || c[i] != c[i - 1]) {
            if (count[c[i]] == 2)
                count[c[i]] = 3;
        }
    }

    // Collect common elements
    vector<int> common;
    for (auto &p : count) {
        if (p.second == 3)
            common.push_back(p.first);
    }

    // Sort result
    sort(common.begin(), common.end());

    return common;
}

int main()
{
    vector<int> a = {1, 5, 10, 20, 30};
    vector<int> b = {5, 13, 15, 20};
    vector<int> c = {5, 20};

    vector<int> common = commonElements(a, b, c);

    if (common.empty())
        cout << "[]" << endl;
    else
        for (int ele : common)
            cout << ele << " ";

    return 0;
}

