#include <iostream>
#include <vector>
using namespace std;

int findCeil(vector<int>& arr, int x) {
    // If x fits before the first element
    if (x <= arr[0])
        return 0;

    // Scan array to find the ceiling position
    for (int i = 0; i < arr.size() - 1; i++){
        // Exact match
        if (arr[i] == x)
            return i;

        // x lies between arr[i] and arr[i+1]
        if (arr[i] < x && arr[i+1] >= x)
            return i + 1;
    }

    // No ceiling found
    return -1;
}

