{
    vector<int> arr = {1, 2, 8, 10, 10, 12, 19};
    int x = 3;
    int index = findCeil(arr, x);

    if (index == -1)
        cout << "Ceiling of " << x << " doesn't exist in array ";
    else
        cout << "Ceiling of " << x << " is " << arr[index];

    return 0;
}

