// C++ implementation of the Worst Case Linear Time algorithm
// to find the k-th smallest element using Median of Medians
#include <bits/stdc++.h>
using namespace std;

// Returns median of a small group (size <= 5)
int getMedian(vector<int> &group) {
    sort(group.begin(), group.end());
    return group[group.size() / 2];
}

// Function to Partition array from index
// l to r around  the pivot value x
int partitionAroundPivot(vector<int> &arr,
                         int l, int r, int x) {

    // Move pivot x to end
    int i;
    for (i = l; i < r; i++) {
        if (arr[i] == x) break;
    }
    swap(arr[i], arr[r]);

    // Standard partition logic
    i = l;
    for (int j = l; j < r; j++) {
        if (arr[j] <= x) {
            swap(arr[i], arr[j]);
            i++;
        }
    }

    swap(arr[i], arr[r]);

    // Final position of pivot
    return i;
}

// Recursively finds the k-th smallest element in arr[l..r]
int selectKthSmallest(vector<int> &arr, int l, int r, int k) {
    if (k > 0 && k <= r - l + 1) {
        int n = r - l + 1;
        vector<int> medians;
        int i;

        // Divide array into groups of 5 and store their medians
        for (i = 0; i < n / 5; i++) {
            vector<int> group(arr.begin() + l + i * 5,
                              arr.begin() + l + i * 5 + 5);
            medians.push_back(getMedian(group));
        }

        // Handle the last group with less than 5 elements
        if (i * 5 < n) {
            vector<int> lastGroup(arr.begin() + l + i * 5,
                                  arr.begin() + l + i * 5 + (n % 5));
            medians.push_back(getMedian(lastGroup));
        }

