int floorSqrt(int n) {

    // initial search space
    int lo = 1, hi = n;
    int res = 1;

    while(lo <= hi) {
        int mid = lo + (hi - lo)/2;

        // if square of mid is less than or equal to n
        // update the result and search in upper half
        if(mid*mid <= n) {
            res = mid;
            lo = mid + 1;
        }

        // if square of mid exceeds n,
      	// search in the lower half
        else {
            hi = mid - 1;
        }
    }

    return res;
}

