bool binarySearch(vector<int> &mat, int target) {
    int n = mat.size();
    int low = 0, high = n - 1;

    // Standard binary search algorithm
    while (low <= high) {
        int mid = (low + high) / 2;

        // Element found
        if (mat[mid] == target)
            return true;

        // Search in the right half
        else if (target > mat[mid])
            low = mid + 1;

        // Search in the left half
        else
            high = mid - 1;
    }

    // Element not found
    return false;
}

