    int i = 0, j = m - 1;

    while (i < n && j >= 0) {

        // If x > mat[i][j], then x will be greater
        // than all elements to the left of mat[i][j]
        // in row i, so move to the next row
        if (x > mat[i][j]) {
            i++;
        }

        // If x < mat[i][j], then x will be smaller
        // than all elements below mat[i][j]
        // in column j, so move to the previous column
        else if (x < mat[i][j]) {
            j--;
        }

        // If x == mat[i][j], return true
        else {
            return true;
        }
    }

    // If x was not found, return false
    return false;
}

