vector<int> find(vector<int> arr, int x) {
    int n = arr.size();

    // Initialize first and last index
    int first = -1, last = -1;

    for (int i = 0; i < n; i++) {

        // If x is different, continue
        if (x != arr[i])
            continue;

        // If first occurrence found
        if (first == -1)
            first = i;

        // Update last occurrence
        last = i;
    }

    vector<int> res = {first, last};
    return res;
}

