// Function for finding first occurrence of x
function findFirst(arr, x) {
    let n = arr.length;

    // Initialize left and right index
    let left = 0, right = n - 1;

    // Initialize first occurrence
    let first = -1;

    // Find first occurrence of x
    while (left <= right) {

        // Find the mid index
        let mid = Math.floor((left + right) / 2);

        // If x is equal to arr[mid]
        if (x === arr[mid]) {
            first = mid;
            right = mid - 1;
        }

        // If x is less than arr[mid],
        // then search in the left subarray
        else if (x < arr[mid])
            right = mid - 1;

        // If x is greater than arr[mid],
        // then search in the right subarray
        else
            left = mid + 1;
    }
    return first;
}
// Function for finding last occurrence of x
function findLast(arr, x) {
    let n = arr.length;

    // Initialize left and right index
    let left = 0, right = n - 1;

    // Initialize last occurrence
    let last = -1;

    // Find last occurrence of x
    while (left <= right) {

        // Find the mid index
        let mid = Math.floor((left + right) / 2);

        // If x is equal to arr[mid]
        if (x === arr[mid]) {
            last = mid;
            left = mid + 1;
        }

        // If x is less than arr[mid],
        // then search in the left subarray
        else if (x < arr[mid])
            right = mid - 1;

        // If x is greater than arr[mid],
        // then search in the right subarray
        else
            left = mid + 1;
    }
    return last;
}

function find(arr, x) {
    let n = arr.length;

    // Find first and last index
    let first = findFirst(arr, x);
    let last = findLast(arr, x);

    let res = [first, last];
    return res;
}

