    int size = arr.size();
    int S = 0;
    int P = 1;
    int x, y;
    int D;
    int n = size - 2, i;

    for (i = 0; i < size; i++)
    {
        S = S + arr[i];
        P = P * arr[i];
    }

    S = S - n * (n + 1) / 2;
    P = P / fact(n);

    D = sqrt(S * S - 4 * P);

    x = (D + S) / 2;
    y = (S - D) / 2;

    return {x, y};
}

