int findNum(int n) {
    int num = 1;
    int cnt = 0;
    while (true) {
        int temp = num;

        // count how many times 5 divides
        // current number
        while (temp % 5 == 0) {
            cnt++;
            temp /= 5;
        }

        // If total trailing zeros counted so far
        // is at least n, return current number
        if (cnt >= n) {
            return num;
        }

        num++;
    }
}

int main() {
    int n = 6;
    cout << findNum(n) << endl;
    return 0;
}

