#include <bits/stdc++.h>
using namespace std;

vector<int> kthSmallest(int n, vector<vector<int>> ranges,
                        vector<int> queries) {

    // Sort ranges by starting point
    sort(ranges.begin(), ranges.end());

    // Merge overlapping ranges
    vector<vector<int>> merged;

    for (auto &range : ranges) {
        if (merged.empty() || range[0] > merged.back()[1])
            merged.push_back(range);
        else
            merged.back()[1] = max(merged.back()[1], range[1]);
    }

    vector<int> ans;

    // Process each query
    for (int k : queries) {
        bool found = false;

        // Find the range containing the kth element
        for (auto &range : merged) {
            int count = range[1] - range[0] + 1;

            if (k <= count) {
                ans.push_back(range[0] + k - 1);
                found = true;
                break;
            }

            k -= count;
        }

        if (!found)
            ans.push_back(-1);
    }

    return ans;
}

int main() {
    int n = 2;
    vector<vector<int>> ranges = {{1, 4}, {6, 8}};
    vector<int> queries = {2, 6, 10};

    vector<int> ans = kthSmallest(n, ranges, queries);

    cout << "[";
    for (int i = 0; i < ans.size(); i++) {
        cout << ans[i];
        if (i + 1 < ans.size())
            cout << ", ";
    }
    cout << "]";

    return 0;
}

