import java.util.ArrayList;
import java.util.Arrays;

class GFG {
    static ArrayList<Integer> kthSmallest(int n, ArrayList<ArrayList<Integer>> ranges,
                                          ArrayList<Integer> queries) {

        // Sort ranges by starting point
        ranges.sort((a, b) -> Integer.compare(a.get(0), b.get(0)));

        // Merge overlapping ranges
        ArrayList<ArrayList<Integer>> merged = new ArrayList<>();

        for (ArrayList<Integer> range : ranges) {
            if (merged.isEmpty() || range.get(0) > merged.get(merged.size() - 1).get(1)) {
                merged.add(new ArrayList<>(range));
            } else {
                merged.get(merged.size() - 1).set(1,
                    Math.max(merged.get(merged.size() - 1).get(1), range.get(1)));
            }
        }

        ArrayList<Integer> ans = new ArrayList<>();

        // Process each query
        for (int k : queries) {
            boolean found = false;

            // Find the range containing the kth element
            for (ArrayList<Integer> range : merged) {
                int count = range.get(1) - range.get(0) + 1;

                if (k <= count) {
                    ans.add(range.get(0) + k - 1);
                    found = true;
                    break;
                }

                k -= count;
            }

            if (!found)
                ans.add(-1);
        }

        return ans;
    }

    public static void main(String[] args) {
