using System.Collections.Generic;

class GFG {
    static List<int> kthSmallest(int n, List<List<int>> ranges,
                                 List<int> queries) {

        // Sort ranges by starting point
        ranges.Sort((a, b) => a[0].CompareTo(b[0]));

        // Merge overlapping ranges
        List<List<int>> merged = new List<List<int>>();

        foreach (List<int> range in ranges) {
            if (merged.Count == 0 ||
                range[0] > merged[merged.Count - 1][1]) {
                merged.Add(new List<int>(range));
            } else {
                merged[merged.Count - 1][1] =
                    Math.Max(merged[merged.Count - 1][1], range[1]);
            }
        }

        List<int> ans = new List<int>();

        // Process each query
        foreach (int query in queries) {
            int k = query;
            bool found = false;

            // Find the range containing the kth element
            foreach (List<int> range in merged) {
                int count = range[1] - range[0] + 1;

                if (k <= count) {
                    ans.Add(range[0] + k - 1);
                    found = true;
                    break;
                }

                k -= count;
            }

            if (!found)
                ans.Add(-1);
        }

        return ans;
    }

