using namespace std;

// Merge all overlapping ranges into disjoint intervals.
vector<vector<int>> mergeIntervals(vector<vector<int>> &ranges) {

    sort(ranges.begin(), ranges.end());

    vector<vector<int>> merged;

    for (const auto &range : ranges) {

        // Start a new interval if there is no overlap.
        if (merged.empty() || merged.back()[1] < range[0])
            merged.push_back(range);
        else
            merged.back()[1] = max(merged.back()[1], range[1]);
    }

    return merged;
}

vector<int> kthSmallest(int n, vector<vector<int>> &ranges,
                        vector<int> &queries) {

    // Merge overlapping intervals.
    vector<vector<int>> merged = mergeIntervals(ranges);

    // prefix[i] stores the total number of elements
    // covered till the i-th merged interval.
    vector<long long> prefix;

    long long total = 0;

    for (const auto &range : merged) {
        total += 1LL * (range[1] - range[0] + 1);
        prefix.push_back(total);
    }

    vector<int> ans;

    for (int k : queries) {

        // If the k-th element does not exist.
        if (k > total) {
            ans.push_back(-1);
            continue;
        }

        // Find the interval containing the k-th element.
        int idx = lower_bound(prefix.begin(), prefix.end(),
                              (long long)k) - prefix.begin();

        long long previous = (idx == 0 ? 0 : prefix[idx - 1]);

        ans.push_back(merged[idx][0] + (k - previous) - 1);
    }

    return ans;
}

