import java.util.ArrayList;
import java.util.Arrays;

class GFG {

    // Merge all overlapping ranges into disjoint intervals.
    public static ArrayList<ArrayList<Integer> >
    mergeIntervals(ArrayList<ArrayList<Integer> > ranges)
    {

        ranges.sort(
            (a, b) -> Integer.compare(a.get(0), b.get(0)));

        ArrayList<ArrayList<Integer> > merged
            = new ArrayList<>();

        for (ArrayList<Integer> range : ranges) {

            // Start a new interval if there is no overlap.
            if (merged.isEmpty()
                || merged.get(merged.size() - 1).get(1)
                       < range.get(0)) {

                merged.add(new ArrayList<>(range));
            }
            else {
                merged.get(merged.size() - 1)
                    .set(1,
                         Math.max(
                             merged.get(merged.size() - 1)
                                 .get(1),
                             range.get(1)));
            }
        }

        return merged;
    }

    public static ArrayList<Integer>
    kthSmallest(int n,
                ArrayList<ArrayList<Integer> > ranges,
                ArrayList<Integer> queries)
    {

        // Merge overlapping intervals.
        ArrayList<ArrayList<Integer> > merged
            = mergeIntervals(ranges);

        // prefix[i] stores the total number of elements
        // covered till the i-th merged interval.
        ArrayList<Long> prefix = new ArrayList<>();

        long total = 0;

        for (ArrayList<Integer> range : merged) {
            total += (long)range.get(1) - range.get(0) + 1;
            prefix.add(total);
        }

        ArrayList<Integer> ans = new ArrayList<>();

        for (int k : queries) {

            // If the k-th element does not exist.
            if (k > total) {
                ans.add(-1);
                continue;
            }

            // Find the interval containing the k-th
            // element.
            int left = 0;
            int right = prefix.size() - 1;

            while (left < right) {
                int mid = left + (right - left) / 2;

                if (prefix.get(mid) >= k)
                    right = mid;
                else
                    left = mid + 1;
            }

            int idx = left;

            long previous
                = (idx == 0 ? 0 : prefix.get(idx - 1));

            ans.add((int)(merged.get(idx).get(0)
                          + (k - previous) - 1));
        }

