                continue;

            if (i > 0) {
                prev = prefix[i - 1];
            }

            // Find the first index where arr[pos] > arr[i] + k
            int pos = upperBound(arr, arr[i] + k, i, n);

            // Total coins to remove:
            // - `prev` for coins from smaller piles (before i)
            // - `(prefix[n - 1] - prefix[pos - 1])` is the total
