vector<int> farMin(vector<int>& arr) {
    int n = arr.size();
    vector<int> ans(n, -1);

    for (int i = 0; i < n; ++i) {

        // check from the end to find the farthest smaller
        for (int j = n - 1; j > i; --j) {

            // update with the farthest valid index
            // break since we need the farthest (rightmost)
            if (arr[j] < arr[i]) {
                ans[i] = j;
                break;
            }
        }
    }

    return ans;
}

