#include <iostream>
#include <vector>
using namespace std;

vector<int> distributeCandies(int n, int k) {
    vector<int> arr(k, 0);

    int low = 0, high = n;
    int count = 0;

    // Find the maximum number of complete distributions.
    while (low <= high) {
        int mid = low + (high - low) / 2;
        long long total = 1LL * mid * (mid + 1) / 2;

        if (total <= n) {
            count = mid / k;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    int last = count * k;

    n -= (int)(1LL * last * (last + 1) / 2);

    int term = last + 1;
    int idx = 0;

    while (n > 0) {
        if (term <= n) {
            arr[idx] = term;
            n -= term;
            term++;
            idx++;
        } else {
            arr[idx] += n;
            n = 0;
        }
    }

    for (int i = 0; i < k; i++) {
        arr[i] += count * (i + 1)
                + k * count * (count - 1) / 2;
    }

    return arr;
}

