function distributeCandies(n, k) {
    let arr = new Array(k).fill(0);

    let low = 0, high = n;
    let count = 0;

    // Find the maximum number of complete distributions.
    while (low <= high) {
        let mid = low + Math.floor((high - low) / 2);
        let total = Math.floor(mid * (mid + 1) / 2);

        if (total <= n) {
            count = Math.floor(mid / k);
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    let last = count * k;

    n -= Math.floor(last * (last + 1) / 2);

    let term = last + 1;
    let idx = 0;

    while (n > 0) {
        if (term <= n) {
            arr[idx] = term;
            n -= term;
            term++;
            idx++;
        } else {
            arr[idx] += n;
            n = 0;
        }
    }

    for (let i = 0; i < k; i++) {
        arr[i] += count * (i + 1)
                + Math.floor(k * count * (count - 1) / 2);
    }

    return arr;
}

