    let res = 0;

    // search Space for Binary Search
    let lo = 1;
    let hi = arr[arr.length - 1] - arr[0];

    while (lo <= hi) {
        let mid = Math.floor(lo + (hi - lo) / 2);

        // if the mid distance is possible, update
        // the result and search for larger distance
        if (check(arr, k, mid)) {
            res = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }

    return res;
}

