        }

        // If current height is less than required
        if (currHeight < maxHeight) {
            int add = maxHeight - currHeight;
            water[i] += add;
            k -= add;

            // If days become negative, not possible
            if (k < 0) {
                return false;
            }
        }
    }

    return true;
