// C++ program to swap the nodes of a linked list rather
// than swapping the data from the nodes.

#include <iostream>
using namespace std;

class Node {
public:
    int data;
    Node* next;
    Node(int x) {
        data = x;
        next = nullptr;
    }
};

// Function to swap nodes x and y in linked list by
// changing links and return the updated head
Node* swapNodes(Node* head, int x, int y) {

    // Nothing to do if x and y are the same
    if (x == y) return head;

    Node *prevX = nullptr, *currX = nullptr;
    Node *prevY = nullptr, *currY = nullptr;
    Node *curr = head;

    // First loop to find x
    while (curr != nullptr) {
        if (curr->data == x) {
            currX = curr;
            break;
        }
        prevX = curr;
        curr = curr->next;
    }

    curr = head;

    // Second loop to find y
    while (curr != nullptr) {
        if (curr->data == y) {
            currY = curr;
            break;
        }
        prevY = curr;
        curr = curr->next;
    }

    // If either x or y is not present, nothing to do
    if (currX == nullptr || currY == nullptr) return head;

    // If x is not head of the linked list
    if (prevX != nullptr) {
        prevX->next = currY;
    } else {
        head = currY;
    }

    // If y is not head of the linked list
    if (prevY != nullptr) {
        prevY->next = currX;
    } else {
        head = currX;
    }

    // Swap next pointers
    Node* temp = currY->next;
    currY->next = currX->next;
    currX->next = temp;

    return head;
}

void print(Node* curr) {
    while (curr != nullptr) {
        cout << curr->data << " ";
        curr = curr->next;
    }
    cout << endl;
}

