    public static Node addPolynomial(Node head1, Node head2)
    {

        Map<Integer, Integer> mp
            = new TreeMap<>(Collections.reverseOrder());

        // Store terms of first polynomial
        while (head1 != null) {
            mp.put(head1.pow, mp.getOrDefault(head1.pow, 0)
                                  + head1.coeff);
            head1 = head1.next;
        }

        // Store terms of second polynomial
        while (head2 != null) {
            mp.put(head2.pow, mp.getOrDefault(head2.pow, 0)
                                  + head2.coeff);
            head2 = head2.next;
        }

        Node head = null;
        Node tail = null;

