        for (Map.Entry<Integer, Integer> entry :
             mp.entrySet()) {

            if (entry.getValue() == 0)
                continue;

            Node newNode = new Node(entry.getValue(),
                                    entry.getKey());

            if (head == null) {
                head = tail = newNode;
            }
            else {
                tail.next = newNode;
                tail = newNode;
            }
