// C++ program for flattening a Linked List

#include<iostream>
#include<algorithm>
#include<vector>
using namespace std;

class Node {
public:
    int data;
    Node *next, *bottom;

    Node(int newdata) {
        data = newdata;
        next = bottom = nullptr;
    }
};

// function to flatten the linked list
Node* flatten(Node* root) {

    vector<int> values;

    // Push values of all nodes into an array
    while (root != nullptr) {

        // Push the head node of the sub-linked-list
        values.push_back(root->data);

        // Push all the nodes of the sub-linked-list
        Node* temp = root->bottom;
        while (temp != nullptr) {
            values.push_back(temp->data);
            temp = temp->bottom;
        }

        // Move to the next head node
        root = root->next;
    }

    // Sort the node values in ascending order
    sort(values.begin(), values.end());

    // Construct the new flattened linked list
    Node* tail = nullptr;
    Node* head = nullptr;
    for (int i = 0; i < values.size(); i++) {
        Node* newNode = new Node(values[i]);

        // If this is the first node of the linked list,
        // make the node as head
        if (head == nullptr) {
            head = newNode;
        }
        else {
            tail->bottom = newNode;
        }
        tail = newNode;
    }
    return head;
}

void printList(Node* head) {
    Node* temp = head;
    while (temp != nullptr) {
        cout << temp->data;
        if(temp->bottom)
        cout<<" -> ";
        temp = temp->bottom;
    }
