#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;

class Node
{
  public:
    int data;
    Node *next;

    Node(int x)
    {
        data = x;
        next = nullptr;
    }
};

// Function to check if sublist from start to end is palindrome
bool isPalindrome(Node *start, Node *end)
{
    // Store elements of sublist in vector
    vector<int> temp;

    Node *curr = start;
    while (curr != end->next)
    {
        temp.push_back(curr->data);
        curr = curr->next;
    }

    // Two pointer check for palindrome
    int i = 0, j = temp.size() - 1;
    while (i < j)
    {
        if (temp[i] != temp[j])
            return false;
        i++;
        j--;
    }

    return true;
}

// Function to get length of sublist from start to end
int getLength(Node *start, Node *end)
{
    int len = 0;
    Node *curr = start;

    // Traverse from start to end
    while (curr != end->next)
    {
        len++;
        curr = curr->next;
    }

    return len;
}

// Function to find maximum length palindrome sublist
int maxPalindrome(Node *head)
{
    int res = 0;

    // Fix starting point
    for (Node *i = head; i != nullptr; i = i->next)
    {
        // Fix ending point
        for (Node *j = i; j != nullptr; j = j->next)
        {
            // Check if sublist is palindrome
            if (isPalindrome(i, j))
            {
                int len = getLength(i, j);

                // Update maximum length
                res = max(res, len);
            }
        }
    }

    return res;
}

