#include <iostream>
#include <vector>
using namespace std;

int maxSubarraySum(vector<int>& arr, int k) {
    int n = arr.size();
    int maxSum = 0;

    // check all subarrays of size k
    for (int i = 0; i <= n - k; i++) {
        int currSum = 0;

        // compute sum of current subarray
        for (int j = 0; j < k; j++) {
            currSum += arr[i + j];
        }

        // update maximum sum
        maxSum = max(maxSum, currSum);
    }

    return maxSum;
}

int main() {
    vector<int> arr = {2, 1, 5, 1, 3, 2};
    int k = 3;
    cout << maxSubarraySum(arr, k) << endl;
    return 0;
}

