int countIncreasing(vector<int>& arr) {

    int n = arr.size();
    int count = 0;

    // Iterate over all possible subarrays
    for (int i = 0; i < n; i++) {

        // Start from index i
        for (int j = i + 1; j < n; j++) {

            // If the sequence breaks, stop early
            if (arr[j - 1] >= arr[j]) {
                break;
            }

            // Otherwise, count the valid subarray
            count++;
        }
    }

    return count;
}

int main() {

    vector<int> arr = {1, 4, 5, 3, 7, 9};

    cout << countIncreasing(arr) << endl;

    return 0;
}

