// with exactly k Distinct characters.
int countSubstr(string &s, int k) {
    int n = s.length();
    int ans = 0;

    // subtract substrings with at most
    // k-1 distinct characters from substrings
    // with at most k distinct characters
    ans = count(s, k) - count(s, k-1);

    return ans;
}

