  for (let i = k - 1; i < n; i++) {
    const addIdx = s.charCodeAt(i) - 97;
    if (++cnt[addIdx] === 1) distinctCnt++;

    if (distinctCnt === k - 1) ans++;

    const remIdx = s.charCodeAt(i - k + 1) - 97;
    if (--cnt[remIdx] === 0) distinctCnt--;
