                int f = getMaxFreq(s, l, r);

                // If the number of changes required is <= k,
                // update the maximum length
                if (r - l + 1 - f <= k)
                    maxlen = Math.max(maxlen, r - l + 1);
            }
        }

        return maxlen;
    }

