            else if (cnt < k)
                r++, cnt++;
            else if (s[l] === String.fromCharCode(c))
                l++;
            else
                l++, cnt--;

            // Update the maximum length of substring
            res = Math.max(res, r - l);
        }
    }

    return res;
}

