bool areAnagram(string s1, string s2) {
    vector<int> cnt(26, 0);

    int n1 = s1.length();
    int n2 = s2.length();

    for (int i = 0; i < n1; i++)
        cnt[s1[i] - 'a']++;

    for (int i = 0; i < n2; i++)
        cnt[s2[i] - 'a']--;

    for (int i = 0; i < 26; i++) {
        if (cnt[i] != 0)
            return false;
    }

    return true;
}

