class PriorityQueue {
    constructor(comparator) {
        this.comparator = comparator || ((a, b) => a - b);
        this.data = [];
    }

    get count() {
        return this.data.length;
    }

    enqueue(item) {
        this.data.push(item);
        this.data.sort(this.comparator);
    }

    dequeue() {
        if (this.count === 0) {
            throw new Error("Priority queue is empty.");
        }
        return this.data.shift();
    }
}

