        int n = arr1.Length;
        int m = arr2.Length;

        // temporary array to store all elements
        // from arr1 and arr2
        int[] merged = new int[n + m];

        // copy elements from arr1 and arr2
        // into merged array
        for (int i = 0; i < n; ++i) {
            merged[i] = arr1[i];
        }
        for (int j = 0; j < m; ++j) {
            merged[n + j] = arr2[j];
        }

        // sort the merged array
        Array.Sort(merged);

        // distribute first n elements to arr1
        for (int i = 0; i < n; ++i) {
            arr1[i] = merged[i];
        }

        // distribute remaining m elements to arr2
        for (int j = 0; j < m; ++j) {
            arr2[j] = merged[n + j];
        }
    }

    static void Main() {
        int[] arr1 = {1, 3, 5, 7};
        int[] arr2 = {2, 4, 6, 8};

        mergeArrays(arr1, arr2);

        foreach (int num in arr1) {
            Console.Write(num + " ");
        }
        Console.WriteLine();

        foreach (int num in arr2) {
            Console.Write(num + " ");
        }
        Console.WriteLine();
    }
}

