#include <iostream>
#include <vector>
using namespace std;

void mergeTwoParts(vector<int> &arr)
{
    int n = arr.size();

    // starting index of second half
    int index = 0;

    // Temp Array store sorted resultant array
    vector<int> temp(n);

    // First Find the point where array is divided
    // into two half
    for (int i = 0; i < n - 1; i++)
    {
        if (arr[i] > arr[i + 1])
        {
            index = i + 1;
            break;
        }
    }

    // If Given array is all-ready sorted
    if (index == 0)
        return;

    // Merge two sorted arrays in single sorted array
    int i = 0, j = index, k = 0;
    while (i < index && j < n)
    {
        if (arr[i] < arr[j])
            temp[k++] = arr[i++];
        else
            temp[k++] = arr[j++];
    }

    // Copy the remaining elements of arr[i to index]
    while (i < index)
        temp[k++] = arr[i++];

    // Copy the remaining elements of arr[index to n]
    while (j < n)
        temp[k++] = arr[j++];

    for (int i = 0; i < n; i++)
    {
        arr[i] = temp[i];
    }
}

int main()
{
    vector<int> arr = {2, 3, 8, -1, 7, 10};
    int n = arr.size();
    mergeTwoParts(arr);

    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    return 0;
}

