    int n = arr.size();
    // finding all possible pairs
    for(int i = 0; i < n; i++){
        for(int j = i + 1; j < n; j++){
            int sum = arr[i] + arr[j];
            if(sum == target){
                return {i+1, j+1};
            }
        }
    }
    // no pair sum with given target
    return {-1, -1};
}

