void threeWayPartition(vector<int> &arr, int a, int b)
{
    vector<int> low, mid, high;

    // Divide elements into three groups
    for (int x : arr)
    {
        if (x < a)
            low.push_back(x);
        else if (x <= b)
            mid.push_back(x);
        else
            high.push_back(x);
    }

    int i = 0;

    // Copy elements smaller than a
    for (int x : low)
        arr[i++] = x;

    // Copy elements in the range [a, b]
    for (int x : mid)
        arr[i++] = x;

    // Copy elements greater than b
    for (int x : high)
        arr[i++] = x;
}

