#include <bits/stdc++.h>
using namespace std;

class Node {
  public:
    int data;
    Node *next;

    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

// Sort a linked list of 0s, 1s, and 2s by changing pointers
Node *sortList(Node *head) {
    if (!head || !(head->next))
        return head;

    // Create three dummy nodes to point to the beginning of
    // three linked lists. These dummy nodes are created to
    // avoid null checks.
    Node *zeroD = new Node(0);
    Node *oneD = new Node(0);
    Node *twoD = new Node(0);

    // Initialize current pointers for three lists
    Node *zero = zeroD, *one = oneD, *two = twoD;

    // Traverse the list
    Node *curr = head;
    while (curr != NULL) {
        if (curr->data == 0) {

            // If the data of the current node is 0,
            // append it to pointer zero and update zero
            zero->next = curr;
            zero = zero->next;
        }
        else if (curr->data == 1) {

            // If the data of the current node is 1,
            // append it to pointer one and update one
            one->next = curr;
            one = one->next;
        }
        else {

            // If the data of the current node is 2,
            // append it to pointer two and update two
            two->next = curr;
            two = two->next;
        }
        curr = curr->next;
    }

    // Combine the three lists
    if (oneD->next)
        zero->next = oneD->next;
    else
        zero->next = twoD->next;

    one->next = twoD->next;
    two->next = nullptr;

    // Updated head
    head = zeroD->next;
    return head;
}

