        {
            if (nCols > 0)
                minHeap.Add((mat[i, 0], i, 0));
        }

        // Merge all elements
        while (minHeap.Count() > 0)
        {
            var top = minHeap.Pop();
            int val = top.val;
            int i = top.arrIdx;
