// Function to find the smallest subarray
// sorting which makes whole array sorted
vector<int> printUnsorted(vector<int> &arr) {

    // create the temp array equal to arr
    vector<int> temp = arr;

    // sort the temp array
    sort(temp.begin(), temp.end());

    // to store the first and last index
    // with unmatching elements
    int s = 0, e = 0;

    // find the leftmost unmatching index
    for(int i = 0; i < arr.size(); i++) {
        if(arr[i] != temp[i]) {
            s = i;
            break;
        }
    }

    // find the rightmost unmatching index
    for(int i = arr.size() - 1; i >= 0; i--) {
        if(arr[i] != temp[i]) {
            e = i;
            break;
        }
    }

    return {s, e};
}

int main() {
    vector<int> arr = {0, 1, 15, 25, 6, 7, 30, 40, 50};
    vector<int> res = printUnsorted(arr);
    cout << res[0] << " " << res[1];
    return 0;
}

