// Function to find the smallest subarray
// sorting which makes whole array sorted
vector<int> printUnsorted(vector<int> &arr) {
    int n = arr.size();

    // find the leftmost and rightmost index
    // from where the array is not sorted
    int left = n + 1, right = -1;

    // to store the maximum element
    int maxi = INT_MIN;

    // stack to store the index of the elements
    stack<int> st;

    for (int i = 0; i < n; ++i) {

        // pop while current element is less than
        // the element at the top of the stack
        while (!st.empty() && arr[i] < arr[st.top()])
            st.pop();

        // if stack is not empty, then
        // the array is not sorted
        if (!st.empty()) {

            // update the left index
            if (i - st.top() > 1) {
                left = min(left, st.top());
                right = i;
            }
            else {

                // if the current element is less
                // than the maximum element
                if (arr[i] < maxi)
                    right = i;

                // if the element at the top of the stack
                // is not the maximum element
                else if (arr[st.top()] != maxi)
                    right = i - 1;
            }
        }

        // if stack is empty
        else if (i != 0) {
            left = -1;
            right = i;
        }

        // update the maximum element
        maxi = max(maxi, arr[i]);

        // push the current index
        st.push(i);
    }
    return {left + 1, right};
}

