using System;

class GFG {
    class MinHeap {
        private int[] heap;
        private int size;

        public MinHeap(int capacity)
        {
            heap = new int[capacity];
            size = 0;
        }

        public void Push(int value)
        {
            int i = size;
            heap[size++] = value;

            while (i > 0) {
                int parent = (i - 1) / 2;

                if (heap[parent] <= heap[i])
                    break;

                int temp = heap[parent];
                heap[parent] = heap[i];
                heap[i] = temp;

                i = parent;
            }
        }

        public int Pop()
        {
            int result = heap[0];

            heap[0] = heap[size - 1];
            size--;

            int i = 0;

            while (true) {
                int left = 2 * i + 1;
                int right = 2 * i + 2;
                int smallest = i;

                if (left < size
                    && heap[left] < heap[smallest])
                    smallest = left;

                if (right < size
                    && heap[right] < heap[smallest])
                    smallest = right;

                if (smallest == i)
                    break;

                int temp = heap[i];
                heap[i] = heap[smallest];
                heap[smallest] = temp;

                i = smallest;
            }

            return result;
        }

        public bool IsEmpty() { return size == 0; }
    }

    public void nearlySorted(int[] arr, int k)
    {
        int n = arr.Length;

        MinHeap pq = new MinHeap(k + 1);

        // Pushing first k elements in heap
        for (int j = 0; j < k; j++)
            pq.Push(arr[j]);

        int i;

        for (i = k; i < n; i++) {
            pq.Push(arr[i]);

            // Size becomes k + 1, so pop minimum
            // and add it at (i - k) index
            arr[i - k] = pq.Pop();
        }

        // Putting remaining elements in array
        while (!pq.IsEmpty()) {
            arr[i - k] = pq.Pop();
            i++;
        }
    }

    static void Main()
    {
        int[] arr = { 2, 3, 1, 4 };
        int k = 2;

        GFG obj = new GFG();

        obj.nearlySorted(arr, k);

        Console.Write("[");

        for (int i = 0; i < arr.Length; i++) {
            Console.Write(arr[i]);

            if (i != arr.Length - 1)
                Console.Write(", ");
        }

        Console.Write("]");
    }
}

