bool sortedAfterSwap(vector<int> &arr, vector<int> &brr) {
    int n = arr.size();

    // sort all continuous segments
    // that can be swapped
    for (int i = 0; i < n - 1; i++) {
        int start = i;
        while (i < n - 1 && brr[i] == 1) {
            i++;
        }

        // sort the segment
        sort(arr.begin() + start, arr.begin() + i + 1);
    }

    // Check if array is sorted or not
    for (int i = 0; i < n; i++) {
        if (arr[i] != i + 1)
            return false;
    }

    return true;
}

