    for (let i = 0; i < n - 1; i++) {
        arr[i] = temp[i];
    }

    // Shift elements right
    for (let i = n - 2; i >= k; i--) {
        [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
