    // Initialize answer with maximum possible value
    int mini = INT_MAX;

    // Generate all possible pairs
    for (int i = 0; i < n; i++)
    {
        for (int j = i + 1; j < n; j++)
        {
            // Update minimum product if current pair gives a smaller product
            mini = min(mini, arr[i] * arr[j]);
        }
    }

    // Return the minimum product found
