function mergeThree(A, B, C)
{
    let m, n, o, i, j, k;

    // Get Sizes of three vectors
    m = A.length;
    n = B.length;
    o = C.length;

    // Vector for storing output
    let D = [];
    i = j = k = 0;
    while (i < m && j < n && k < o)
    {

        // Get minimum of a, b, c
        let m = Math.min(Math.min(A[i], B[j]), C[k]);

        // Put m in D
        D.push(m);

        // Increment i, j, k
        if (m == A[i])
            i++;
        else if (m == B[j])
            j++;
        else
            k++;
    }

    // C has exhausted
    while (i < m && j < n) {
        if (A[i] <= B[j]) {
            D.push(A[i]);
            i++;
        }
        else {
            D.push(B[j]);
            j++;
        }
    }

    // B has exhausted
    while (i < m && k < o) {
        if (A[i] <= C[k]) {
            D.push(A[i]);
            i++;
        }
        else {
            D.push(C[k]);
            k++;
        }
    }

    // A has exhausted
    while (j < n && k < o) {
        if (B[j] <= C[k]) {
            D.push(B[j]);
            j++;
        }
        else {
            D.push(C[k]);
            k++;
        }
    }

    // A and B have exhausted
    while (k < o)
        D.push(C[k++]);

    // B and C have exhausted
    while (i < m)
        D.push(A[i++]);

    // A and C have exhausted
    while (j < n)
        D.push(B[j++]);

    return D;
}

