using namespace std;

int maxPartitions(vector<int> &arr)
{
    int n = arr.size();
    int res = 0;

    // Traverse every prefix of the array.
    for (int i = 0; i < n; i++)
    {
        int mx = arr[0];

        // Find the maximum element in the current prefix.
        for (int j = 1; j <= i; j++)
            mx = max(mx, arr[j]);

        // If the maximum element is equal to the current index,
        // then a partition can end at this index.
        if (mx == i)
            res++;
    }

    return res;
}

int main()
{
    vector<int> arr = {2, 1, 0, 3, 4, 5};

    cout << maxPartitions(arr);

    return 0;
}

