    int n = a.size();

    // Iterate through each index
    for (int i = 0; i < n; i++) {

        // If elements don't match at index i
        if (a[i] != b[i]) {

            // Find correct element in the rest of array 'b'
            for (int j = i + 1; j < n; j++) {
                if (b[j] == a[i]) {

                    // Swap to bring correct element at position i
                    swap(b[i], b[j]);
                    swaps++;
                    break;
                }
            }
        }
    }

    return swaps;
}

