    for (int i = 1; i < n-1; i++) {
        int leftDiff = arr[i] - arr[i-1];
        int rightDiff = arr[i+1] - arr[i];

        // Add the minimum of left
        // and right differences
        sum += min(leftDiff, rightDiff);
    }

    return sum;
}

