        for (int i = 0; i < n; i++) {
            if (Character.isLowerCase(s.charAt(i))) {
                result.setCharAt(i, lower[lowerIndex++]);
            } else {
                result.setCharAt(i, upper[upperIndex++]);
            }
        }

        return result.toString();
    }

