#include <bits/stdc++.h>
using namespace std;

int maxIntersections(vector<vector<int>> &lines)
{
    int n = lines.size();

    // Store all starting and ending points separately.
    vector<int> start(n), end(n);

    for (int i = 0; i < n; i++)
    {
        start[i] = lines[i][0];
        end[i] = lines[i][1];
    }

    // Sort starting and ending points independently.
    sort(start.begin(), start.end());
    sort(end.begin(), end.end());

    int i = 0, j = 0;
    int intersect = 0, maxInter = 0;

    // Sweep through the sorted starting and ending points.
    while (i < n && j < n)
    {
        // If a line starts before or exactly when
        // the current line ends, both lines overlap.
        if (start[i] <= end[j])
        {
            intersect++;

            // Update the maximum number of
            // overlapping line segments.
            maxInter = max(maxInter, intersect);

            i++;
        }
        else
        {
            // A line has ended before the next line starts,
            // so it is no longer part of the current overlap.
            intersect--;
            j++;
        }
    }

    return maxInter;
}

int main()
{
    vector<vector<int>> lines = {{1, 3}, {5, 6}, {3, 4}};
    cout << maxIntersections(lines) << endl;

    return 0;
}

