        s[i] = s[n - i - 1];
        s[n - i - 1] = temp;
    }

    // swap '(' and ')'
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') s[i] = ')';
        else if (s[i] == ')') s[i] = '(';
