bool isBalanced(string& s) {

    // stack top index in string
    int top = -1;
    for (int i = 0; i < s.length(); i++) {
        if (s[i] == '(' || s[i] == '{' || s[i] == '[') {

            // push opening bracket
            s[++top] = s[i];
        }
        else if (s[i] == ')' || s[i] == '}' || s[i] == ']') {

            // no opening bracket
            if (top == -1) return false;
            if ((s[i] == ')' && s[top] != '(') ||
                (s[i] == '}' && s[top] != '{') ||
                (s[i] == ']' && s[top] != '[')) {
                return false;
            }
            top--;
        }
    }

    // balanced if stack empty
    return top == -1;
}

