    [1, 10, 1],
    [1, 20, 1],
    [1, 30, 1],
    [1, 100, 0],
    [1, 200, 0],
    [2, 1],
    [2, 1],
    [2, 0],
    [1, 2, 2]
];

let opCount = operations.length;

for (let i = 0; i < opCount; i++) {
    if (operations[i][0] === 1) {
        let x = operations[i][1], m = operations[i][2];
        st.push(x, m);
    } else if (operations[i][0] === 2) {
        let m = operations[i][1];
        let res = st.pop(m);
        if (res !== -1)
            console.log('Popped Element: ' + res);
    }
}

