    stack<int> st;

    st.push(11);
    st.push(2);
    st.push(32);
    st.push(3);
    st.push(41);

    sortStack(st);

    cout << "[";

    // Print stack from top to bottom
    while (!st.empty()) {
        cout << st.top();
        st.pop();

        if (!st.empty())
            cout << ", ";
    }

    cout << "]";

    return 0;
}

