int maxLength(string& s) {
    int maxLen = 0;

    // Left to Right Traversal
    int open = 0, close = 0;
    for (int i=0; i<s.length(); i++) {
        char ch=s[i];
        if (ch == '(') {
            open++;
        }
        else if (ch == ')') {
            close++;
        }

        if (open == close) {
            maxLen = max(maxLen, 2 * close);
        }
        else if (close > open) {
            open = close = 0;
        }
