        // Reverse the last word (since there may not be
        // space at the end)
        while (st.Count > 0) {
            result += st.Pop();
        }

        return result;
    }

    // Driver Code
    public static void Main(string[] args)
    {
        string str = "Geeks for Geeks";
        string reversed = ReverseWords(str);
        Console.WriteLine(reversed);
    }
}

