function reverseWords(str)
{
    let st = [];
    let result = "";

    for (let i = 0; i < str.length; ++i) {
        if (str[i] !== " ")
            // Push character to stack
            st.unshift(str[i]);
        else {
            while (st.length !== 0) {
                // Pop from stack and append
                result += st.shift();
            }
            // Add space after word is reversed
            result += " ";
        }
    }

    // Reverse the last word
    while (st.length !== 0) {
        result += st.shift();
    }

    return result;
}

