#include <iostream>
#include <stack>
using namespace std;

class myQueue {
    stack<int> s1, s2;

public:

    // Enqueue operation (O(1))
    void enqueue(int x) {
        s1.push(x);
    }

    // Dequeue operation
    void dequeue() {

        // If both stacks are empty → queue underflow
        if (s1.empty() && s2.empty()) return;

        // If s2 is empty, move all elements from s1
        if (s2.empty()) {
            while (!s1.empty()) {
                s2.push(s1.top());
                s1.pop();
            }
        }

        s2.pop();
    }

    // Return the front element without removing it
    int front() {
        if (!s2.empty()) return s2.top();
        if (!s1.empty()) {

            // Move all elements to s2 to access front
            while (!s1.empty()) {
                s2.push(s1.top());
                s1.pop();
            }
            int x = s2.top();
            return x;
        }

        // Queue empty
        return -1;
    }

    // Return the current size of the queue
    int size() {
        return s1.size() + s2.size();
    }
};

int main() {
    myQueue q;

    q.enqueue(1);
    q.enqueue(2);
    q.enqueue(3);

    cout << "Front: " << q.front() << "\n";
    cout << "Size: " << q.size() << "\n";

    q.dequeue();
    cout << "Front: " << q.front() << "\n";
    cout << "Size: " << q.size() << "\n";

    return 0;
}

