    struct myStack st;
    init(&st);

    push(&st, 1);
    push(&st, 2);
    push(&st, 3);
    push(&st, 4);

    reverseStack(&st);

    while (!isEmpty(&st)) {
        printf("%d ", pop(&st));
    }

    return 0;
}

