int maxPeople(vector<int> &arr) {
    int n = arr.size();
    int maxCount = 0;

    for (int i = 0; i < n; i++) {
        int count = 1;

        // Check left side
        for (int j = i - 1; j >= 0; j--) {
            if (arr[j] < arr[i])
                count++;
            if (arr[j] >= arr[i])
                break;
        }

        // Check right side
        for (int j = i + 1; j < n; j++) {
            if (arr[j] < arr[i])
                count++;
            if (arr[j] >= arr[i])
                break;
        }

        if (count > maxCount)
            maxCount = count;
    }

    return maxCount;
}

