    let n = s1.length, m = s2.length;
    let i = 0, j = 0;

    while (i < n && j < m) {
        if (s1[i] == s2[j])
            i++;
        j++;
    }

    // If i reaches end of s1, that means we found all
    //   characters of s1 in s2, so s1 is a subsequence of s2
    return i == n;
}

// Driver code
