#include <iostream>
#include <vector>
using namespace std;

vector<int> computeLPSArray(string& pat) {
  	int n = pat.size();
  	vector<int> lps(n);

    // length of the previous longest prefix suffix
    int len = 0;

    // lps[0] is always 0
    lps[0] = 0;

    // loop calculates lps[i] for i = 1 to n-1
    int i = 1;
    while (i < n) {

        // if the characters match, increment len
        // and extend the matching prefix
        if (pat[i] == pat[len]) {
            len++;
            lps[i] = len;
            i++;
        }

        // if there is a mismatch
        else {

            // if len is not zero, update len to
            // last known prefix length
            if (len != 0) {
                len = lps[len - 1];
            }

            // no prefix matches, set lps[i] = 0
            // and move to the next character
            else {
                lps[i] = 0;
                i++;
            }
        }
    }
  	return lps;
}

// function to check if s1 and s2 are rotations of each other
bool areRotations(string &s1, string &s2) {
  	string txt = s1 + s1;
  	string pat = s2;

  	// search the pattern string s2 in the concatenation string
  	int n = txt.length();
    int m = pat.length();

    // create lps[] that will hold the longest prefix suffix
    // values for pattern
    vector<int> lps = computeLPSArray(pat);

    int i = 0;
    int j = 0;
    while (i < n) {
        if (pat[j] == txt[i]) {
            j++;
            i++;
        }

        if (j == m) {
            return true;
        }

        // mismatch after j matches
        else if (i < n && pat[j] != txt[i]) {

            // do not match lps[0..lps[j-1]] characters,
            // they will match anyway
            if (j != 0)
                j = lps[j - 1];
            else
                i = i + 1;
        }
    }
    return false;
}

int main() {
    string s1 = "aab";
  	string s2 = "aba";
    cout << (areRotations(s1, s2) ? "true" : "false");
