    // Length must be between 1 and 3
    if (n == 0 || n > 3)
        return false;

    // Check if all characters are digits
    for (char c : s)
    {
        if (c < '0' || c > '9')
            return false;
    }

    // Prevent numbers like "00", "01"
    if (s[0] == '0' && n > 1)
        return false;

    // Convert the part to an integer manually
    int num = 0;
    for (char c : s)
    {
        num = num * 10 + (c - '0');
    }

    // Check if the value lies in the range 0 to 255
    return num >= 0 && num <= 255;
}

