int countRecur(int i, int n) {

    // Base case
    if (i >= n) return 1;

    // If we take 1 at ith index,
    // we cannot have 1 at (i-1)
    int take = countRecur(i+2, n);

    // If we skip 1, we can consider
    // 1 at i-1.
    int noTake = countRecur(i+1, n);

    return take + noTake;
}

int countStrings(int n) {
    return countRecur(0, n);
}

