string nextString(string &s) {
    int i = s.length() - 1;

    // Move left while characters are 'z'
    while (i >= 0 && s[i] == 'z') {
        i--;
    }

    // If all characters were 'z', append
    // 'a' to the string
    if (i == -1) {
        return s + 'a';
    }

    // Otherwise, increment the
    // rightmost non-'z' character
    s[i]++;

    // Erase all characters after
    // the incremented one
    s.erase(i + 1);
    return s;
}

