import java.util.*;

public class GfG {

    public static boolean isBalanced(String expr) {
        int count = 0;

        // Traversing the expression
        for (int i = 0; i < expr.length(); i++) {
            if (expr.charAt(i) == '{') {
                count++;
            } else {
                // It is a closing bracket
                count--;
            }
            if (count < 0) {
                // This means there are more closing brackets than opening ones
                return false;
            }
        }

        // If count is not zero, it means there are more opening brackets
        return count == 0;
    }

    // Recursive function to find the number of reversals
    public static void recur(String expr, int n, int ind, int change, int[] ans) {
        // When generated expression is balanced
        if (isBalanced(expr)) {
            ans[0] = Math.min(ans[0], change);
        }

        // When we have covered the whole string
        if (ind == n) {
            return;
        }

        // Keep bracket as it is
        recur(expr, n, ind + 1, change, ans);

        // Reverse the bracket
        char[] exprArray = expr.toCharArray();
        if (exprArray[ind] == '{') {
            exprArray[ind] = '}';
        } else {
            exprArray[ind] = '{';
        }
        recur(new String(exprArray), n, ind + 1, change + 1, ans);
    }

    public static int countMinReversals(String expr) {
        // Length of expression
        int n = expr.length();

        // To store answer
        int[] ans = { Integer.MAX_VALUE };

        // When the total number of brackets is odd
        if (n % 2 == 1) {
            return -1;
        } else {
            // Function call for finding answer
            recur(expr, n, 0, 0, ans);
            return ans[0];
        }
    }

    public static void main(String[] args) {
        String expr = "}{{}}{{{";
        System.out.println(countMinReversals(expr));
    }
}

