#include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<int> buildLps(string& s1) {
    int n = s1.size();
    vector<int> lps(n, 0);

    int len = 0;
    int i = 1;

    // Build longest prefix suffix array.
    while (i < n) {
        if (s1[i] == s1[len]) {
            lps[i++] = ++len;
        } else if (len != 0) {
            len = lps[len - 1];
        } else {
            lps[i++] = 0;
        }
    }

    return lps;
}

string replaceAll(string& s, string& s1, string& s2) {
    vector<int> lps = buildLps(s1);

    int i = 0, j = 0, last = 0;
    int n = s.size(), m = s1.size();

    string res = "";

    // Use KMP to find all non-overlapping matches.
    while (i < n) {
        if (s[i] == s1[j]) {
            i++;
            j++;
        }

        if (j == m) {
            int start = i - m;

            // Add text before match and then replacement.
            res += s.substr(last, start - last);
            res += s2;

            last = i;
            j = 0;
        } else if (i < n && s[i] != s1[j]) {
            if (j != 0) j = lps[j - 1];
            else i++;
        }
    }

    // Add remaining text.
    res += s.substr(last);
    return res;
}

int main() {
    string s = "xxforxx xx for xx", s1 = "xx", s2 = "Geeks";
    cout << replaceAll(s, s1, s2) << endl;

    s = "india is the xx country", s1 = "xx", s2 = "best";
    cout << replaceAll(s, s1, s2) << endl;

    return 0;
}

