// C++ program to Find Excel column
// name from a given column number
#include <bits/stdc++.h>
using namespace std;

string colName(int n) {
    string res = "";

    while (n > 0) {

        // Find remainder
        int rem = n % 26;

        // If remainder is 0, then a 'Z'
        // must be there in output
        if (rem == 0) {
            res += 'Z';
            n = (n / 26) - 1;
        }

        // If remainder is non-zero
        else {
            res += (rem - 1) + 'A';
            n = n / 26;
        }
    }

    // Reverse the string
    reverse(res.begin(), res.end());

    return res;
}

