        // Check if x has same length (to maintain digit count)
        if (curr.length > n.length) break;

        // Check palindrome property
        if (!isPalindrome(curr)) continue;

        // Check same digit frequency
        if (sameFreq(n, curr)) {
            return curr;
        }
    }

