    for (int i = 0; i < str.size(); i++) {
        if (stk.empty()) {
            stk.push(make_pair(str[i], 1));
        } else {
            if (str[i] == stk.top().first) {
                pair<char, int> p = stk.top();
                stk.pop();
                p.second++;
                if (p.second < k) stk.push(p);
            } else {
                stk.push(make_pair(str[i], 1));
            }
        }
    }

    while (!stk.empty()) {
        if (stk.top().second > 1) {
            int count = stk.top().second;
            while (count--) ans += stk.top().first;
        } else {
            ans += stk.top().first;
        }
        stk.pop();
    }

    reverse(ans.begin(), ans.end());
    return ans;
}

