bool canFormPalindrome(string& s, int l, int r) {
    vector<int> freq(26, 0);

    for (int i = l; i <= r; i++) {
        freq[s[i] - 'a']++;
    }

    int odd = 0;
    for (int x : freq) {
        if (x % 2) odd++;
    }

    return odd <= 1;
}

int longestSubstring(string& s) {
    int n = s.length();
    int ans = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            if (canFormPalindrome(s, i, j)) {
                ans = max(ans, j - i + 1);
            }
        }
    }

    return ans;
}

int main() {
    cout << longestSubstring("aabe") << endl;
    cout << longestSubstring("adbabd") << endl;
    return 0;
}

