#include <iostream>
#include <string>
#include <vector>
using namespace std;

int longestSubstring(string& s) {
    int n = s.length();
    vector<int> prefix(n + 1, 0);

    for (int i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] ^ (1 << (s[i] - 'a'));
    }

    int ans = 0;

    for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
            int mask = prefix[j + 1] ^ prefix[i];

            // Valid if at most one character has odd frequency.
            if ((mask & (mask - 1)) == 0) {
                ans = max(ans, j - i + 1);
            }
        }
    }

    return ans;
}

