void printSubSeqRec(string s, int n, int index = -1,
                    string curr = "") {
    // base case
    if (index == n)
        return;

    // Print the current subsequence (including empty)
    cout << curr << "\n";

    for (int i = index + 1; i < n; i++) {
        curr += s[i];
        printSubSeqRec(s, n, i, curr);

        // backtracking
        curr = curr.erase(curr.size() - 1);
    }
    return;
}

