    static int subseqCount(String txt, String pat) {

        int m = pat.length();
        int n = txt.length();

        // pat can't appear as a subsequence in txt
        if (m > n)
            return 0;

        int[][] dp = new int[m + 1][n + 1];

        // initialize dp with -1
        for (int x = 0; x <= m; x++)
            Arrays.fill(dp[x], -1);

        return countSubsequences(m, n, pat, txt, dp);
    }

