{
    vector<string> d = {"aab", "mno", "xyx", "aba", "ccc"};
    string pat = "xyx";

    vector<string> res = matchingStrings(d, pat);

    cout << "[";
    for (int i = 0; i < res.size(); i++)
    {
        cout << "\"" << res[i] << "\"";
        if (i + 1 < res.size())
            cout << ", ";
    }
    cout << "]";

    return 0;
}

