#include <iostream>
#include <string>
using namespace std;

bool canFormPalindrome(string &s)
{
    int odd = 0;

    // Count frequency using two loops
    for (int i = 0; s[i]; i++) {
        int count = 0;

        for (int j = 0; s[j]; j++) {
            if (s[i] == s[j])
                count++;
        }

        if (count % 2 != 0)
            odd++;

        if (odd > 1)
            return false;
    }

    return true;
}

int main()
{
    string s1 = "geeksgeeks";
    string s2 = "geeksforgeeks";

    cout << (canFormPalindrome(s1)
                        ? "True\n" : "False\n");
    cout << (canFormPalindrome(s2)
                        ? "True\n" : "False\n");

    return 0;
}

