#include <iostream>
#include <string>
using namespace std;

bool canFormPalindrome(string &s)
{
    int mask = 0;

    // toggle bits
    for (int i = 0; s[i]; i++) {
        int bit = s[i] - 'a';
        mask ^= (1 << bit);
    }

    // check at most one bit set
    return (mask == 0) || (mask & (mask - 1)) == 0;
}

int main()
{
    string s1 = "geeksgeeks";
    string s2 = "geeksforgeeks";

    cout << (canFormPalindrome(s1)
                        ? "True\n" : "False\n");
    cout << (canFormPalindrome(s2)
                        ? "True\n" : "False\n");

    return 0;
}

