#include <algorithm>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

string maxPalindrome(string &s, int k)
{
    int n = s.length();
    vector<bool> changed(n, false);

    // Make the string a palindrome.
    int i = 0, j = n - 1;

    while (i < j)
    {
        if (s[i] != s[j])
        {
            // Replace the smaller digit with the larger digit.
            if (s[i] < s[j])
                s[i] = s[j];
            else
                s[j] = s[i];

            // Mark this pair as changed.
            changed[i] = changed[j] = true;
            k--;
        }

        i++;
        j--;
    }

    // Return -1 if it is not possible to make a palindrome.
    if (k < 0)
        return "-1";

    // Maximize the palindrome using the remaining changes.
    i = 0;
    j = n - 1;

    while (i < j)
    {
        if (s[i] != '9')
        {
            // One extra change is enough for an already changed pair.
            if (changed[i] && k >= 1)
            {
                s[i] = s[j] = '9';
                k--;
            }

            // Two changes are needed for an unchanged pair.
            else if (!changed[i] && k >= 2)
            {
                s[i] = s[j] = '9';
                k -= 2;
            }
        }

        i++;
        j--;
    }

    // Make the middle digit 9 if one change is available.
    if (i == j && k > 0)
        s[i] = '9';

    // Return the largest possible palindrome.
    return s;
}

