#include <algorithm>
#include <iostream>
#include <string>
using namespace std;

string maxPalindrome(string &s, int k)
{
    int n = s.length();
    int replacements = 0;

    // Count changes needed to make the string a palindrome.
    for (int i = 0, j = n - 1; i < j; i++, j--)
    {
        if (s[i] != s[j])
        {
            replacements++;

            // -1 if required changes exceed k.
            if (replacements > k)
                return "-1";
        }
    }

    // Maximize the palindrome using the remaining changes.
    for (int i = 0, j = n - 1; i <= j && k > 0; i++, j--)
    {

        // Maximize the middle digit for odd length.
        if (i == j)
        {
            s[i] = '9';
        }

        // Handle different mirror digits.
        else if (s[i] != s[j])
        {

            // Use one extra change to make both digits 9.
            if (k - replacements >= 1 && max(s[i], s[j]) != '9')
            {
                s[i] = s[j] = '9';
                replacements--;
                k -= 2;
            }

            // Otherwise, make both digits equal to the larger digit.
            else
            {
                s[i] = s[j] = max(s[i], s[j]);
                replacements--;
                k--;
            }
        }

        // Make an equal pair 9 if two extra changes are available.
        else if (k - replacements >= 2 && s[i] != '9')
        {
            s[i] = s[j] = '9';
            k -= 2;
        }
    }

    // Return the largest possible palindrome.
    return s;
}

