def maxPalindrome(s, k):
    n = len(s)
    replacements = 0

    # Count changes needed to make the string a palindrome.
    for i in range(n // 2):
        if s[i] != s[n - 1 - i]:
            replacements += 1

            # -1 if required changes exceed k.
            if replacements > k:
                return "-1"

    # Maximize the palindrome using the remaining changes.
    s = list(s)

    for i in range((n + 1) // 2):
        j = n - 1 - i

        if k <= 0:
            break

        # Maximize the middle digit for odd length.
        if i == j:
            s[i] = '9'

        # Handle different mirror digits.
        elif s[i] != s[j]:

            # Use one extra change to make both digits 9.
            if k - replacements >= 1 and max(s[i], s[j]) != '9':
                s[i] = s[j] = '9'
                replacements -= 1
                k -= 2

            # Otherwise, make both digits equal to the larger digit.
            else:
                s[i] = s[j] = max(s[i], s[j])
                replacements -= 1
                k -= 1

        # Make an equal pair 9 if two extra changes are available.
        elif k - replacements >= 2 and s[i] != '9':
            s[i] = s[j] = '9'
            k -= 2

    return ''.join(s)

