        if (s[i] !== s[j]) {
            replacements++;

            // -1 if required changes exceed k.
            if (replacements > k)
                return "-1";
        }
    }

    // Maximize the palindrome using the remaining changes.
    let sArray = s.split("");

    for (let i = 0, j = n - 1; i <= j && k > 0; i++, j--) {

        // Maximize the middle digit for odd length.
        if (i === j) {
            sArray[i] = "9";
        }

        // Handle different mirror digits.
        else if (sArray[i] !== sArray[j]) {

            // Use one extra change to make both digits 9.
            if (k - replacements >= 1
                && Math.max(Number(sArray[i]),
                            Number(sArray[j]))
                       !== 9) {

                sArray[i] = sArray[j] = "9";
                replacements--;
                k -= 2;
            }

            // Otherwise, make both digits equal to the
            // larger digit.
            else {
                let larger = Math.max(Number(sArray[i]),
                                      Number(sArray[j]));

                sArray[i] = sArray[j] = String(larger);
                replacements--;
                k--;
            }
        }

        // Make an equal pair 9 if two extra changes are
        // available.
        else if (k - replacements >= 2
                 && sArray[i] !== "9") {
            sArray[i] = sArray[j] = "9";
            k -= 2;
        }
